quests[10749] = { id = 10749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Zobelmähnes Gift", description = "Hier, bringt dies zu Eurem Auftraggeber. Ich bin mir sicher, dass Rexxar es sinnvoll einzusetzen weiß.\n\nOh, und stellt sicher, dass er sich im Klaren ist, dass er mir etwas schuldet.\n\nEr weiß, was ich will. Ich bin mir sicher, dass wir uns - ganz gleich, wie er es zu beschafften gedenkt - schneller wiedersehen werden, als Ihr vielleicht denkt.\n\nJetzt seid ein <braver Junge/braves Mädel> und bringt dies zu Rexxar.", sourceObjective = "Bringt Baron Zobelmähnes Gift zu Rexxar in der Donnerfeste im Schergrat.", progress = "{class}, so schnell schon zurück? Habt Ihr das Gift?", completion = "Die Verwendung von Giften ist ein dreckiges Geschäft. Aber so werden wir unsere Ziele erreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10750] = { id = 10750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Eroberung", description = "Meine Windreiter sind mit ein paar Neuigkeiten zurückgekehrt, {name}. Die Blutelfen der Mondfinsternis führen etwas Großes im Schilde. Sie haben begonnen, ihre Armeen beim Pfad der Eroberung zusammen zu ziehen. Er liegt weit im Süden und schließt an die Stätte der Mondfinsternis an.\n\nIch möchte, dass Ihr zum Pfad der Eroberung reist und die Situation einschätzt. Wenn Ihr fertig seid, benutzt diese Leuchtpistole um einen Windreiter herbeizurufen. Daraufhin wird sich einer aus den Lüften schwingen, um Euch zu treffen. Berichtet, was Ihr entdeckt habt und erwartet Eure neuen Befehle.", sourceObjective = "Reist zum Pfad der Eroberung im Schattenmondtal.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Diese lästigen Hunde planen etwas Heimtückisches. Wir müssen weitere Nachforschungen anstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10751] = { id = 10751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad bereinigen", description = "Wir brauchen mehr Zeit, {race}! Ich werde mit den anderen Windreitern vorausfliegen. Hoffentlich können wir ein paar weitere Informationen sammeln. Ihr müsst für mich den Pfad freiräumen. Und noch viel wichtiger: uns ihre Pfeile vom Leib halten!\n\nWenn Ihr ihre Reihen gelichtet habt, ruft einen Windreiter mithilfe der Leuchtpistole der Kor'kron!", sourceObjective = "Tötet 20 Soldaten der Mondfinsternis, 10 Dragoner der Mondfinsternis und 10 Zauberbinder der Mondfinsternis.", completion = "Ihr werdet es nicht glauben, Grunzer!", sourceObjectiveStatus = "unverified-source-field" }
quests[10752] = { id = 10752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Eschental!", description = "Vor Kurzem kam Raene Wolfsläufer aus Darnassus durch Auberdine. Sie war auf dem Weg ins Eschental und murmelte etwas von Furbolgs. Ich hatte keine Gelegenheit, sie genauer dazu zu befragen, aber vielleicht könnt Ihr Euch ja auf die Suche nach ihr begeben und ihr Eure Hilfe anbieten, {class}. Nehmt die südliche Straße aus Auberdine hinaus. Folgt der Straße einfach weiter, sobald Ihr die Grenze zum Eschental erreicht habt. Dort findet Ihr schließlich Astranaar und Raene Wolfsläufer.", sourceObjective = "Sprecht mit Raene Wolfsläufer in Astranaar.", completion = "Thundris Windwirker denkt also immer noch, dass man auf mich aufpassen muss? Ich werde ihn wohl daran erinnern müssen, wer hier wen gerettet hat. Er scheint vergessen zu haben, dass ich ihn vor den schlimmsten Übeln bewahrt habe.\n\nNun, da Ihr schon hier seid, {race}, habe ich vielleicht doch eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10753] = { id = 10753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis ausmerzen", description = "Die Zahl der Verbrechen, die die Brennende Legion begangen hat, steigt ins Unermessliche. Genau in diesem Moment schickt die Legion wieder ihre Truppen aus, um die Lebewesen dieser Welt heimzusuchen. Sie sind ihrer Macht hilflos ausgeliefert und fallen einer nach dem anderen ihrer Gewalt zum Opfer. {name}, helft mir dabei, diese Verbrechen gegen die Natur aufzuhalten und vernichtet alles, was von ihrer Verderbnis befallen wurde.\n\nHinter den Bergen im Osten könnt Ihr sehen, wie sich die Verderbnis in der Messerschlucht ausbreitet. Tötet die Verantwortlichen, die Teufelsverderber, und so viele Teufelsanbeter, wie Ihr nur könnt.", sourceObjective = "Tötet 4 Wesen der Schuppenflügelteufelsbrut, 4 Wesen der Dolchrachenteufelsbrut und 2 Teufelsverderber.", completion = "Es erfüllt mich nicht mit Stolz zu zerstören, was Elune erschaffen hat, aber die Verderbnis muss aufgehalten werden. Ihr habt Eure Arbeit gut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10754] = { id = 10754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugang zur Zitadelle", description = "Diese frisch gegossene Form wurde für die Herstellung eines Schlüssels benutzt. Das eingravierte Bild auf ihr deutet darauf hin, dass sie etwas mit der Höllenfeuerzitadelle zu tun hat.\n\nVielleicht interessiert sich Danath, der Truppenkommandant der Ehrenfeste, dafür.", sourceObjective = "Bringt die präparierte Schlüsselform zu Truppenkommandant Danath in der Ehrenfeste auf der Höllenfeuerhalbinsel.", progress = "Wollt Ihr mir etwas zeigen, {name}?", completion = "Kann das wahr sein? Lasst mich die Form einmal genauer betrachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10755] = { id = 10755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugang zur Zitadelle", description = "Diese frisch gegossene Form wurde für die Herstellung eines Schlüssels benutzt. Das eingravierte Bild auf ihr deutet darauf hin, dass sie etwas mit der Höllenfeuerzitadelle zu tun hat.\n\nVielleicht interessiert sich Nazgrel, der Anführer der Streifkräfte der Horde in Thrallmar, dafür.", sourceObjective = "Bringt die präparierte Schlüsselform zu Truppenkommandant Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Wollt Ihr mir etwas zeigen, {name}?", completion = "Eine Schlüsselform? Könnte es das sein, was uns Zugang zu den Zerschmetterten Hallen verschafft?", sourceObjectiveStatus = "unverified-source-field" }
quests[10756] = { id = 10756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Rohok", description = "Das Symbol auf dem Schlüsselgriff... man kann es in der Form nur schwer erkennen, aber ich erkenne es als das Siegel der Zerschmetterten Hand.\n\nEs besteht eine hohe Wahrscheinlichkeit, dass dieser Schlüssel Euch Zugang zu den Zerschmetterten Hallen bieten kann.\n\nSprecht mit Rohok, unserem Schmied hier. Wenn er diesen Schlüssel nicht für Euch herstellen kann, kann es niemand.", sourceObjective = "Bringt die präparierte Schlüsselform zu Rohok nach Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Was ist das?", completion = "Nazgrel möchte, dass ich einen Schlüssel herstelle? Hat er vergessen, dass wir auf einem Schlachtfeld sind? Es gibt Klingen und Speere zu schmieden!", sourceObjectiveStatus = "unverified-source-field" }
quests[10757] = { id = 10757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohoks Bitte", description = "Die Schmiedekunst der Höllenorcs mag nicht gerade die anspruchsvollste sein, aber es ist dennoch Geschick für ihr Handwerk von Nöten. Wenn wir einen funktionierenden Schlüssel herstellen möchten, dürfen wir nur Teufelseisen in diese Form gießen. Alles andere würde sie wahrscheinlich zum Zerbrechen bringen.\n\nBringt mir ein paar Teufelseisenbarren, ein wenig arkanen Staub und Feuerpartikel. Ich werde mich daran versuchen, aber ich kann nichts versprechen.", sourceObjective = "Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Rohok in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe?", completion = "Ausgezeichnet. Wollen wir es versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10758] = { id = 10758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer als die Hölle", description = "Es klappt nicht, {name}! Egal wie viele Kohlen ich auf das Feuer lege, die Hitze des Feuers reicht einfach nicht aus.\n\nMir fällt nur noch eine Sache ein, die heiß genug sein könnte, um diesen Schlüssel auf die richtige Temperatur zu bringen, und das ist das Innere eines Teufelshäschers der Legion.\n\nIch habe bisher nur einmal gesehen, wie einer niedergestreckt wurde. Seine Innereien rauchten, brannten und dampften, als er fiel. Nehmt diese Form und haltet sie in einen gefallenen Teufelshäscher. Ich würde Euch empfehlen, ein paar Freunde mitzunehmen, falls Ihr vorhattet, ihn alleine zur Strecke zu bringen.", sourceObjective = "Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Rohok in Thrallmar.", progress = "Habt Ihr getan, worum ich Euch gebeten habe, {class}?", completion = "Ihr habt es geschafft! Jetzt müsst Ihr sie nur noch ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10759] = { id = 10759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Deserteur", description = "Ich habe das Gefühl, dass alle Teile des Puzzles vor meinen Augen liegen, aber ich kann sie einfach nicht sinnvoll zusammensetzen.\n\nIch glaube, dass unsere heißeste Spur dieser Deserteur ist. Wir müssen ihn finden. Wenn er seine Kameraden im Lager zurückgelassen hat, besteht die Möglichkeit, dass Ihr ihn vielleicht dazu überreden könnt uns zu verraten, was die Arakkoa des Dunklen Rats vorhaben.\n\nBeginnt Eure Suche nach ihm in den Magmafeldern im Nordwesten. Wahrscheinlich hat er dort Zuflucht gesucht.", sourceObjective = "Sucht Parshah in den Magmafeldern und sprecht mit ihm.", completion = "<Der Arakkoa kichert.>\n\nJa, ich bin der Deserteur, den der Kommandant in seinem Tagebuch erwähnt. Ich habe auf den Tag gewartet, an dem auch andere die Bedrohung erkennen, die von meinen einstigen Brüdern ausgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10760] = { id = 10760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wrack der Sketh'lon", description = "Das Wrack der Sketh'lon, direkt im Osten, ist ein unheimlicher Ort. Die Peons sind davon überzeugt, dass es dort spukt.\n\nEs gibt dort ein paar Bäume, deshalb haben die Peons keine andere Wahl, als in die Ruinen der Arakkoa zu gehen und Holz zu schlagen. Die Geister der Arakkoa nähren sich an den Arbeitern. Sie saugen ihre Lebensenergie auf und benutzen sie, um ihre verdorbene Magie zu verstärken.\n\nWir müssen herausfinden, was den Dunklen Rat dazu treibt und ihn aufhalten, bevor sein Einfluss überhand nimmt. Durchsucht das Wrack der Sketh'lon nach Hinweisen auf ihre Pläne.", sourceObjective = "Besorgt das Tagebuch des Kommandanten der Sketh'lon - Seite 1, das Tagebuch des Kommandanten der Sketh'lon - Seite 2 und das Tagebuch des Kommandanten der Sketh'lon - Seite 3 von den Arakkoa des Dunklen Rats beim Wrack der Sketh'lon und bringt die Seiten zu Unteroffizier Kargrul in Schattenmond.", progress = "Was habt Ihr herausgefunden?", completion = "<Der Unteroffizier untersucht die Tagebuchseiten.>\n\nHier steht nicht viel Sinnvolles, aber ein paar Einträge könnten sich als nützlich erweisen. Wie es aussieht waren die Arakkoa dabei, ein kompliziertes magisches Ritual vorzubereiten, bis sie starben, aber warum? Hier steht auch etwas Merkwürdiges über einen 'Deserteur'.", sourceObjectiveStatus = "unverified-source-field" }
quests[10761] = { id = 10761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Deserteur", description = "Hier steht nichts, was erklären würde, warum die Geister dieser Arakkoa in dieser Welt zurückbleiben oder wie sie ihren Durst nach Orcblut entwickelt haben.\n\nIch glaube, dass unsere heißeste Spur dieser Deserteur ist. Wir müssen ihn finden. Wenn er seine Kameraden im Lager zurückgelassen hat, besteht die Möglichkeit, dass Ihr ihn vielleicht dazu überreden könnt uns zu verraten, was die Arakkoa des Dunklen Rats vorhaben.\n\nBeginnt Eure Suche nach ihm in den Magmafeldern im Süden. Wahrscheinlich hat er dort Zuflucht gesucht.", sourceObjective = "Sucht Parshah in den Magmafeldern und sprecht mit ihm.", completion = "<Der Arakkoa kichert.>\n\nJa, ich bin der Deserteur, den der Kommandant in seinem Tagebuch erwähnt. Ich habe auf den Tag gewartet, an dem auch andere die Bedrohung erkennen, die von meinen einstigen Brüdern ausgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10762] = { id = 10762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Dumphry", description = "Das Symbol auf dem Schlüsselgriff... man kann es in der Form nur schwer erkennen, aber ich erkenne es als das Siegel der Zerschmetterten Hand.\n\nEs besteht eine hohe Wahrscheinlichkeit, dass dieser Schlüssel Euch Zugang zu den Zerschmetterten Hallen bieten kann.\n\nSprecht mit Dumphry. Er ist ein Meister seiner Kunst. Wenn er diesen Schlüssel nicht für Euch herstellen kann, kann es niemand.", sourceObjective = "Bringt die präparierte Schlüsselform zu Dumphry in der Ehrenfeste.", progress = "Was ist das?", completion = "Ein Schlüssel? Danath sollte uns eigentlich an Belagerungsmaschinen arbeiten lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10763] = { id = 10763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dumphrys Bitte", description = "Die Höllenorcs mögen vollkommene Barbaren sein, aber ihre Schmiedekunst ist nicht so primitiv, wie Ihr denken mögt. Wenn wir einen funktionierenden Schlüssel herstellen möchten, dürfen wir nur Teufelseisen in diese Form gießen. Alles andere würde sie wahrscheinlich zum Zerbrechen bringen.\n\nBringt mir ein paar Teufelseisenbarren, ein wenig arkanen Staub und Feuerpartikel. Ich werde mich daran versuchen, aber ich kann nichts versprechen.", sourceObjective = "Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Dumphry in der Ehrenfeste auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe?", completion = "Dann wollen wir es mal versuchen. Mal sehen, was hinter der Schmiedekunst der Orcs steckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10764] = { id = 10764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer als die Hölle", description = "Es funktioniert nicht, <Kumpel/Mädel>. Ich kann einfach nicht genug Hitze erzeugen... die Materialien kommen nicht auf ausreichende Temperaturen.\n\nDie Teufelshäscher der Brennenden Legion werden von einem sengenden Kern aus Teufelsfeuer angetrieben, der viel heißer als gewöhnliches Feuer ist.\n\nWenn Ihr genügend Leute zusammentrommeln könntet, um einen davon zur Strecke zu bringen, könntet Ihr die Schlüsselform in dem gefallenen Häscher aufheizen. Aber seid vorsichtig, {class}, diese Teufelshäscher können ganz schön zuschlagen!", sourceObjective = "Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Dumphry in der Ehrenfeste.", progress = "Habt Ihr getan, worum ich Euch gebeten habe, {class}?", completion = "Ihr habt es geschafft, Junge! Jetzt müsst Ihr sie nur noch zur Höllenfeuerzitadelle bringen und ein paar Orcs erlegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10765] = { id = 10765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Welten kollidieren...", description = "Am südlichen Ende des Pfads der Eroberung, in der Nähe der lagernden Karawane, habe ich etwas beobachtet, das nach einem Treffen zwischen einem Riesen und einer Blutelfenkanzlerin aussah. Vielleicht habt Ihr auch schon die kleineren Riesen auf dem Pfad bemerkt. Irgendwas ist an der Sache faul, Soldat.\n\nIch möchte, dass Ihr Euch zu diesem Treffen durchschlagt und die Versammlung auflöst. Sammelt alles, was Ihr dort noch finden könnt, und ruft dann einen von uns mit der Leuchtpistole.", sourceObjective = "Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Sie versuchen also, sich die Gunst der Riesen zu erschleichen, was? Ich habe einen Plan, der diese unheilige Verbindung ganz schnell wieder zerreißen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10766] = { id = 10766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Katastrophe", description = "Jetzt, da wir Zugang zur Basis der Legion beim Invasionspunkt: Katastrophe haben, müssen wir herausfinden, wie wir sie dort aufhalten können. Die Wildhammerfeste ist erst in Sicherheit, wenn wir die Legion völlig aus dem Schattenmondtal vertrieben haben.\n\nIch habe einen Vortrupp zum Invasionspunkt geschickt, der mit Euch einen Plan entwickeln soll, wie wir die Vorräte der Legion zerstören können. Kehrt zur Feste der Legion zurück und benutzt den Teleporter, über dem grüne Kristalle schweben. Plexi erwartet Euch bereits am Ankunftsort.", sourceObjective = "Meldet Euch bei Plexi im Invasionspunkt: Katastrophe.", completion = "Es freut mich, Euch kennen zu lernen, {name}. Mein Name ist Plexi.\n\nIch werde Euch nicht mit Höflichkeiten langweilen. Wir wissen beide, warum wir hier sind. Und nun an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10767] = { id = 10767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Katastrophe", description = "Jetzt, da wir Zugang zur Basis der Legion beim Invasionspunkt: Katastrophe haben, müssen wir herausfinden, wie wir sie dort aufhalten können. Schattenmond ist erst in Sicherheit, wenn wir die Legion völlig aus dem Schattenmondtal vertrieben haben.\n\nIch habe einen Vortrupp zum Invasionspunkt geschickt, der mit Euch einen Plan entwickeln soll, wie wir die Vorräte der Legion zerstören können. Kehrt zur Feste der Legion zurück und benutzt den Teleporter, über dem grüne Kristalle schweben. Nakansi erwartet Euch bereits am Ankunftsort.", sourceObjective = "Meldet Euch bei Nakansi im Invasionspunkt: Katastrophe.", completion = "Ihr müsst derjenige sein, von dem Blutwache Gulmok gesprochen hat. Ich habe bereits einen Plan, aber ich brauche Eure Hilfe, um die Vorbereitungen abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10768] = { id = 10768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenröcke der Illidari", description = "Die Windreiter müssen nach Schattenmond zurückkehren, um sich auf die nächste Phase unseres Angriffs vorzubereiten. Ich benötige von Euch die Wappenröcke, die diese Blutelfen tragen.\n\nWenn Ihr genügend Wappenröcke gesammelt habt, benutzt die Leuchtpistole der Kor'kron, um einen Greifenreiter zu rufen. Seid ihr bereit für ein wenig Spionage, {race}?", sourceObjective = "Sammelt 10 Wappenröcke der Illidari.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Aha! Die werden funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10769] = { id = 10769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwietracht in den Rängen...", description = "Forscher Tiorus war so freundlich, uns dieses Gebräu für unseren finalen Schlag herzustellen. Ich schütte es einfach über den Wappenrock, den Ihr mir gebracht habt, um ihn mit der Essenz der Illidari zu erfüllen.\n\nNehmt diesen verzauberten Wappenrock und reist zu den Feldern der Mondfinsternis südwestlich der Stätte der Mondfinsternis. Wenn Ihr angekommen seid, benutzt den Wappenrock, um Euch in einen Anhänger Illidans zu verwandeln. Tötet die wahnsinnigen Kolosse, die auf den Feldern herumstreifen, solange Ihr verkleidet seid. Sie werden es für einen Angriff der Mondfinsternis halten und alle Beziehungen zu ihnen abbrechen.", sourceObjective = "Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Oberanführer Or'barokh in Schattenmond im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Kor'kron zurück.", progress = "Ihr seid zurück!", completion = "Gut, gut, gut... Wenn das nicht der Grunzer ist, den ich zu den Feldern geschickt habe. Ihr seid heil zurück.\n\n<Or'barokh nickt.>\n\nIch wusste, dass Ihr mich nicht enttäuschen würdet, Soldat. Ihr habt ein entscheidendes Vorrücken der Illidari aufgehalten und Euch damit eine Belohung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[10770] = { id = 10770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Funken", description = "Nordöstlich von hier, auf der Ebene über uns, liegt mein altes, zu Asche verbranntes Zuhause. Bevor die Legion ihre Sengwichtel geschickt hat, um uns in Flammen aufgehen zu lassen, stand dort einst ein stattlicher Wald. Dabei sind so viele ums Leben gekommen, dass sich mein altes Herz auch noch Jahrhunderte später nach Rache sehnt. Es sind zu viele von ihnen dort, um das Land tatsächlich zurückzufordern, aber Ihr könntet ihnen vielleicht ein wenig Angst einjagen.\n\nIhr werdet mir doch helfen, oder?", sourceObjective = "Moosborke der Uralte möchte, dass Ihr 8 Sengwichtel tötet und danach zu ihm im Ruuanwald zurückkehrt.", completion = "Es gibt so viele, dass wir sie nie alle töten können, aber Ihr habt mir Hoffnung gegeben. Vielleicht sollte ich noch ein paar Jahrhunderte lang stärker versuchen, meinen geliebten Wald wieder zum Leben zu erwecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10771] = { id = 10771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Asche", description = "Wenn Ihr der Straße nach Osten den Berg hinauf folgt und dann nach Norden abbiegt, gelangt Ihr an mein altes Zuhause.\n\nEinst stand dort ein prächtiger Wald, dessen Name schon lange vergessen ist. Doch vor ewigen Zeiten rief die Brennende Legion Sengwichtel und andere Flammenwesen herbei, zerstörte mein Zuhause und zwang mein Volk zu fliehen. Nun bin nur noch ich übrig.\n\nIch habe ein paar Eisenwurzelsamen aufgehoben, die in fruchtbaren vulkanischen Boden gepflanzt werden können. Ihre Magie ist sehr stark. Bitte tut mir diesen Gefallen und ich werde die Schätze längst vergangener Zeiten mit Euch teilen.", sourceObjective = "Moosborke der Uralte möchte, dass Ihr nach Skald reist und Eisenwurzelsamen in drei verschiedene Hügel fruchtbarer Vulkanerde pflanzt. Kehrt danach zu ihm im Ruuanwald zurück.", progress = "Ist es vollbracht? Habt Ihr etwas Leben in mein altes Zuhause zurückgebracht?", completion = "Ihr habt viele dieser verderbten Kreaturen getötet. Mit dieser Gewissheit kann ich nun etwas ruhiger schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10772] = { id = 10772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Eroberung", description = "Meine Greifenreiter sind mit ein paar Neuigkeiten zurückgekehrt! Die Blutelfen der Mondfinsternis führen etwas Großes im Schilde. Sie haben begonnen, ihre Armeen beim Pfad der Eroberung zusammen zu ziehen. Er liegt östlich von hier und schließt an die Stätte der Mondfinsternis an.\n\nIch möchte, dass Ihr zum Pfad der Eroberung reist und die Situation einschätzt. Wenn Ihr fertig seid, benutzt diese Leuchtpistole um einen Greifenreiter herbeizurufen. Daraufhin wird sich einer aus den Lüften schwingen, um Euch zu treffen. Berichtet, was Ihr entdeckt habt und erwartet Eure neuen Befehle.", sourceObjective = "Reist zum Pfad der Eroberung im Schattenmondtal.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Diese lästigen Hunde planen etwas Heimtückisches. Wir müssen weitere Nachforschungen anstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10773] = { id = 10773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad bereinigen", description = "Wir brauchen mehr Zeit, {race}! Ich werde mit den anderen Greifenreitern vorausfliegen. Hoffentlich können wir ein paar weitere Informationen sammeln. Ihr müsst für mich den Pfad freiräumen. Und noch viel wichtiger: uns ihre Pfeile vom Leib halten!\n\nWenn Ihr ihre Reihen gelichtet habt, ruft einen Greifenreiter mithilfe der Leuchtpistole der Wildhämmer!", sourceObjective = "Tötet 20 Soldaten der Mondfinsternis, 10 Dragoner der Mondfinsternis und 5 Söhne des Corok.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Ihr werdet es nicht glauben, Soldat!", sourceObjectiveStatus = "unverified-source-field" }
quests[10774] = { id = 10774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutelf + Riese = ???", description = "Am südlichen Ende des Pfads der Eroberung, in der Nähe der lagernden Karawane, habe ich etwas beobachtet, das nach einem Treffen zwischen einem Riesen und einer Blutelfe aussah. Was machen die Riesen überhaupt hier? Irgendwas ist an der Sache faul, Soldat.\n\nIch möchte, dass Ihr Euch zu diesem Treffen durchschlagt und die Versammlung auflöst. Sammelt alles, was Ihr dort noch finden könnt, und ruft dann einen von uns mit der Leuchtpistole.", sourceObjective = "Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Sie versuchen also, sich die Gunst der Riesen zu erschleichen, was? Ich habe einen Plan, der diese unheilige Verbindung ganz schnell wieder zerreißen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10775] = { id = 10775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenröcke der Illidari", description = "Die Greifenreiter müssen zur Wildhammerfeste zurückkehren, um sich auf die nächste Phase unseres Angriffs vorzubereiten. Ich benötige von Euch die Wappenröcke, die diese Blutelfen tragen.\n\nWenn Ihr genügend Wappenröcke gesammelt habt, benutzt die Leuchtpistole der Wildhämmer, um einen Greifenreiter zu rufen. Seid ihr bereit für ein wenig Spionage, {race}?", sourceObjective = "Sammelt 10 Wappenröcke der Illidari.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Aha! Die werden funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10776] = { id = 10776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwietracht in den Rängen...", description = "Gnomus war so freundlich, uns dieses Gebräu für unseren finalen Schlag herzustellen. Ich schütte es einfach über den Wappenrock, den Ihr mir gebracht habt, um ihn mit der Essenz der Illidari zu erfüllen.\n\nNehmt diesen verzauberten Wappenrock und reist zu den Feldern der Mondfinsternis südwestlich der Stätte der Mondfinsternis. Wenn Ihr angekommen seid, benutzt den Wappenrock, um Euch in einen Anhänger Illidans zu verwandeln. Tötet die wahnsinnigen Kolosse, die auf den Feldern herumstreifen, solange Ihr verkleidet seid. Sie werden es für einen Angriff der Mondfinsternis halten und alle Beziehungen zu ihnen abbrechen.", sourceObjective = "Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Than Yoregar in der Wildhammerfeste im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Wildhämmer zurück.", progress = "Ihr seid zurück!", completion = "Gut, gut, gut... Wenn das nicht der Soldat ist, den ich zu den Feldern geschickt habe. Ihr seid heil zurück.\n\n<Yoregar nickt.>\n\nIch wusste, dass Ihr mich nicht enttäuschen würdet, Soldat. Ihr habt ein entscheidendes Vorrücken der Illidari aufgehalten und Euch damit eine Belohung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[10777] = { id = 10777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asghars Totem", description = "Was im Tagebuch des Kommandanten steht, ist wahr. Während sich die orcische Horde unter Gul'dan sammelte, versuchte mein Volk, diese Bedrohung abzuwenden, indem sie einen Angriff planten. Gul'dan erfuhr jedoch davon und wirkte einen mächtigen Zauber, der unsere Lager zerstörte und die Geister meiner Brüder zerbrach.\n\nSie müssen aufgehalten werden, bevor sie noch mehr Unheil anrichten. Sucht nach Asghar beim Wrack der Sketh'lon im Norden und bringt mir das Totem, das er bei sich trägt. Damit können wir beginnen, die Pläne des Dunklen Rats zu vereiteln.", sourceObjective = "Bringt das Kriegstotem der Sketh'lon zu Parshah in den Magmafeldern.", progress = "Habt Ihr das Totem von Asghar beschafft?", completion = "<Parshah untersucht das Totem.>\n\nGut. Dieses alte Totem hat seine Macht über die Jahre nicht eingebüßt, doch es alleine reicht noch nicht aus, um den Dunklen Rat aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10778] = { id = 10778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rute von Lianthe", description = "Das Totem alleine ist nicht stark genug, um der teuflischen Magie des Dunklen Rats entgegen zu wirken.\n\nWir können es jedoch mit anderen mächtigen Gegenständen zu einem Stab verarbeiten, mit dem wir die Energien bündeln können. Es ist nicht mehr möglich, meine Brüder aus den Tiefen ihrer Verderbtheit zu erretten, aber wir können sie aufhalten.\n\nEiner dieser Gegenstände, den ich benötige, ist die Rute von Lianthe, die sich im Besitz der Blutelfen in der Stätte der Mondfinsternis im Südosten befindet. Sie wird in einem Pavillon ganz oben in den Ruinen aufbewahrt und sehr schwer bewacht. Seid vorsichtig, {name}.", sourceObjective = "Besorgt Euch den Schlüssel von Lianthe von den Blutelfen in der Stätte der Mondfinsternis und benutzt ihn, um die Schließkassette von Lianthe zu öffnen und die Rute von Lianthe an Euch zu nehmen. Bringt die Rute zu Parshah in den Magmafeldern.", progress = "Konntet Ihr die Rute beschaffen?", completion = "Gut gemacht. Ein solcher Schatz verdient besseres, als in einer dunklen Kiste weggesperrt zu werden. Wir werden ihn für einen guten Zweck einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10779] = { id = 10779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Jägers", description = "Hallo, junger Jäger. Ihr seht aus, als wärt Ihr bereits tüchtig genug, um ein Tier auszubilden und zu Eurem Begleiter zu machen.\n\nSprecht mit Kella Nachtbogen auf der Azurmythosinsel. Sie kann Euch beibringen, wie man ein eigenes Tier beherrscht.", sourceObjective = "Sprecht mit Kella Nachtbogen auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10780] = { id = 10780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn der Sketh'lon", description = "Uns fehlt noch ein letztes Element des Stabs. Wir müssen seine Macht gegen die Geister des Dunklen Rats richten.\n\nDies erreichen wir, indem wir Federn bei den Ruinen des Basislagers der Sketh'lon sammeln und an dem Stab befestigen. Das Basislager befindet sich im Süden, östlich der Wildhammerfeste.\n\nGul'dans Magie hat meine Brüder vernichtet und nur ihre Geister übrig gelassen, doch das war nicht alles. Die Magie hat sich an dem Zauber, den die Arakkoa vorbereiteten, genährt und eine ruchlose Macht erschaffen, die die Geister in ihren Bann gezogen hat.", sourceObjective = "Sammelt 8 Federn der Sketh'lon und bringt sie zu Parshah in den Magmafeldern.", progress = "Habt Ihr die Federn für den Stab schon gesammelt?", completion = "<Parshah nimmt Euch die aschebestäubten Federn ab und schüttelt den Kopf.>\n\nEs wäre besser gewesen, wenn ich an diesem Tag gestorben wäre, aber die Dinge sind niemals so einfach. Dass Gul'dans Magie sie in etwas verwandelt hat, das sie aufzuhalten versuchten, ist ein grausames Spiel des Schicksals.", sourceObjectiveStatus = "unverified-source-field" }
quests[10781] = { id = 10781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht an der Purpurwacht", description = "Während wir uns hier unterhalten, suchen sie Euch wahrscheinlich auf dem Pfad der Eroberung. Ihr müsst fliehen, {race}!\n\nLasst mich zurück, ich bin ohnehin dem Untergang geweiht... Sie... Ich glaube, ich höre sie kommen. Jetzt oder nie! Flieht! Wenn Ihr bleibt, werdet Ihr kämpfen müssen!\n\nWenn Ihr doch kämpft und es irgendwie schafft, zu überleben, berichtet A'dal in Shattrath von dem, was Ihr gesehen habt!", sourceObjective = "Bekämpft Illidans Truppen bei der Purpurwacht und überlebt!\n\nKehrt zu A'dal in Shattrath zurück, wenn Ihr als Sieger aus der Schlacht hervorgehen solltet.", completion = "Wir werden weitere Nachforschungen über das Purpursiegel anstellen. Sie stellen eine Bedrohung für alles Leben in Draenor dar. Ich sehe einen Tag voraus, an dem ihr dunkler Herr für seine Verbrechen geradestehen muss. Vielleicht seid Ihr ja derjenige, der ihn der Gerechtigkeit zuführen wird, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10782] = { id = 10782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kopfstück mit Magie erfüllen", description = "Der Stab ist fast fertig!\n\nJetzt müssen wir nur nach das Kopfstück mit der Macht von Gul'dans Echo, das durch diesen verfluchten Ort hallt, erfüllen. Im Osten, in der Nähe der Teufelsgruben und südlich der Todesschmiede, befindet sich der Altar der Verdammnis.\n\nDort sind Teile der Vergangenheit gefangen. Wenn Ihr das unfertige Kopfstück des Stabs in die Gegend um den Altar herum bringt, werden einige Wesenheiten darauf reagieren. Seid also auf der Hut. Ihr tragt einen sehr gefährlichen Gegenstand bei Euch, der eng mit der Katastrophe zusammenhängt.", sourceObjective = "Legt das unfertige Kopfstück an und reist zum Altar der Verdammnis. Benutzt das Kopfstück, während Ihr in der Nähe von Gul'dan steht, und kehrt zu Parshah in den Magmafeldern zurück, wenn Ihr es aufgeladen habt.", progress = "Seid Ihr mit dem magieerfüllten Kopfstück zurück?", completion = "<Parshah nimmt Euch das Kopfstück ab und hält es behutsam in den Händen.>\n\nDieses Kopfstück enthält die Macht, die wir brauchen, um die Pläne des Dunklen Rats im Basislager der Sketh'lon zunichte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10783] = { id = 10783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Zobelmähne", description = "Das ist mein Plan. Wir werden die Oger vergiften und dann ihren Gronnmeister vernichten.\n\nWährend meinen Reisen in diesen Bergen habe ich einen Mann namens Baron Zobelmähne getroffen. Er ist ein Meister der Alchemie und lässt sich vielleicht davon überzeugen, uns zu helfen.\n\nIhr findet ihn beim Zirkel des Blutes, unten in der Schlucht nördlich von hier. Welchen Preis er auch immer verlangen mag, nehmt ihn an!", sourceObjective = "Sprecht mit Baron Zobelmähne beim Zirkel des Blutes im Schergrat.", completion = "Hallo, {race}. Ich bin Baron Zobelmähne. Ein Freund Rexxars ist auch mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[10784] = { id = 10784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet das Lager der Blutschläger!", description = "<Tor'chunk beugt sich zu Euch herüber und flüstert.>\n\n{name}, mit Euren Erfolgen im Kampf gegen die Oger bisher habt Ihr uns mehr als stolz gemacht. Und auch wenn ich vollstes Vertrauen in Rexxars Plan habe, möchte ich Euch trotzdem bitten, die Oger im Lager der Blutschläger zu vernichten, bevor Ihr zurückkehrt.\n\nSo können wir unseres Erfolgs doppelt sicher sein.\n\nIhr gelangt in das Lager, indem Ihr den Weg nach Norden aus der Donnerfeste hinausgeht. Wendet Euch am Ende des Steilwegs nach Westen durch Drachenend hindurch und dann nach Norden durch die Grabenschlucht und die Dolchrachenklamm.", sourceObjective = "Tötet 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger.", completion = "<Tor'chunk nickt und scheint dabei sichtlich zufrieden mit Eurer mörderischen Kühnheit.>\n\nIhr erstaunt mich immer wieder, {name}. Jedes Mal, wenn einer dieser stinkenden Oger zu Boden geht, sind wir einen Schritt näher daran, einen unwürdigen Feind loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10785] = { id = 10785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist eine Falle!", description = "Es gibt nichts, was ich auf der Welt mehr hasse, als die Söhne Gruuls und ihren Vater! Sie haben mein Volk und meine Kinder abgeschlachtet, und nun will ich meine Rache dafür!\n\nIch habe eine Falle aus Drachenfeuer gebaut. Wenn Ihr gewitzt genug seid, könnt Ihr damit einen Gronn töten.\n\nBeeilt Euch und bringt die Falle zu Rexxar. Mein Rachedurst muss gestillt werden!", sourceObjective = "Bringt die Drachenfeuerfalle zu Rexxar in der Donnerfeste im Schergrat.", progress = "Habt Ihr bekommen, was auch immer in diesem Sack des Gronns war? Habt Ihr es Zobelmähne gebracht? Hat er Euch etwas für mich mitgegeben?", completion = "Hm, eine Falle, die aus der Essenz einer Drachenflamme gebaut wurde? Ich frage mich, wie Zobelmähne an eine so seltene Substanz gekommen ist!\n\nNun, ganz egal. Nicht egal ist allerdings, dass wir sie benutzen werden, um einen Sohn des Gruul zu töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10786] = { id = 10786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemetzel in Fels'mok", description = "Ich weiß, dass Rexxar Euch nach Fels'mok schicken möchte. Es gibt etwas, das Ihr für mich tun könntet, wenn Ihr dort seid.\n\nWir müssen jede Gelegenheit nutzen, um den Ogern dieser Berge einen Schlag zu versetzen. Sonst werden sie uns überrennen und alles, wofür wir geblutet haben und gestorben sind, zunichte machen!\n\nFels'mok liegt weit im Nordwesten. Reist nach Norden zum Ruuanwald und von dort aus nach Westen durch den Tunnel hinter den Rabenwald.\n\n{name}, ich möchte, dass Ihr die Oger der Speerspießer in Fels'mok tötet. Radiert sie aus!", sourceObjective = "Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok. Kehrt danach zu Tor'chunk Zweiklaue in der Donnerfeste im Schergrat zurück.", completion = "<Tor'chunk grinst, als Ihr ihm von Euren Abenteuern in Fels'mok erzählt.>\n\nAch, ich wünschte, ich hätte mit Euch kommen können. Ich will Euch etwas sagen, {name}, lasst Euch nie auf Pflichten ein, die Euch vom Ruhm der Schlacht fernhalten!\n\nHa! Habt Ihr mir überhaupt noch ein paar Oger in den Bergen übrig gelassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10788] = { id = 10788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Talionia zurück", description = "Einer Eurer Meister, Talionia in Silbermond, schickt nach Euch, {name}. Ich bin mir sicher, dass für Euch die Zeit gekommen ist zu lernen, wie man einen mächtigeren Dämon beschwört und kontrolliert. Ich schlage daher vor, dass Ihr Euch sofort auf den Weg macht. Wie ich weiß befindet sich Talionia im Sanktum, einer gemütlichen kleinen Hütte des Bösen an der Mördergasse.", sourceObjective = "Sprecht mit Talionia in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[10789] = { id = 10789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Carendin Halgar", description = "Ah, da seid Ihr ja, {name}.\n\nCarendin Halgar schickt nach Euch. Ihr sollt ihn im Magieviertel von Unterstadt aufsuchen. Er ist nicht gerade für seine Geduld bekannt, daher würde ich ihn an Eurer Stelle nicht so lange warten lassen.", sourceObjective = "Sprecht mit Carendin Halgar in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10790] = { id = 10790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Gan'rul Blutauge", description = "Ihr seid weit von zu Hause entfernt, {race}. Vielleicht ist es an der Zeit, dass Ihr zurückkehrt, um von Eurem Meister Gan'rul Blutauge zu lernen. Für sein Wissen ist er bei allen, die etwas von der Kunst verstehen, bekannt, sogar bei uns hier.\n\nGan'rul lebt in der Kluft der Schatten in Orgrimmar.", sourceObjective = "Sprecht mit Gan'rul Blutauge in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10791] = { id = 10791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen Wolfgeist!", description = "Ich habe die Gewandung, die ich während der Zeremonie tragen werde, fast fertig. Während ich die letzten Handgriffe erledige, möchte ich Euch bitten, diesen Weihrauch bei den Kerzen in der Nähe des Runensteins zu meiner Linken zu platzieren.\n\nIch glaube, dass er uns dabei helfen wird, die Aufmerksamkeit des Wolfgeistes zu erlangen, da er aus den Tagen der orcischen Klans stammt. Ich kann fast schon sehen, wie meine Vorfahren ihn in einer Zeremonie entzündeten, in der sie dem Wolfgeist nach einer erfolgreichen Jagd dankten.\n\nSobald Ihr den Weihrauch platziert habt, werde ich mit der Zeremonie beginnen.", sourceObjective = "Benutzt den zeremoniellen Weihrauch in der Nähe der Kerzen in Malukaz' Hütte und beobachtet die Zeremonie. Sprecht erneut mit Malukaz, wenn die Zeremonie vorbei ist.", progress = "Die Verbindung mit dem Wolfgeist wiederherzustellen ist nur der Anfang meiner Reise, nicht das Ende.", completion = "Es ist unglaublich! Ich bin zu dieser Reise aufgebrochen, ohne auch nur die leiseste Ahnung zu haben, ob der Wolfgeist auf unsere Anrufung hin kommen würde. Und nun fühlt es sich an, als wäre er nie fort gewesen. Vielleicht war er das auch nie, {name}.\n\nVielleicht hat er darauf gewartet, dass die Orcs verstehen, was ihre Entscheidung bewirkt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10792] = { id = 10792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor muss brennen!", description = "Der Klan des Blutenden Auges hat seine noble Herkunft verraten! Wir, die Orcs, die gekämpft haben und gestorben sind, um uns vor der Verderbtheit Mannoroths zu schützen, sehen in unseren bösen Vettern nur Schwäche und Unwürdigkeit... und dafür sollen sie brennen!\n\nGeht nach Zeth'Gor, ihre Bastion im Osten, und steckt ihre Gebäude in Brand. Tötet die Peons, um an ihre Fackeln zu kommen, entzündet diese an ihrer Schmiede und werft die brennenden Fackeln auf ihre Hütten, ihren Stall und ihre Kaserne. Brennt sie alle nieder und kehrt dann zu mir zurück!\n\nFür die Horde!", sourceObjective = "Tötet Peons des Blutenden Auges, um an ihre Fackeln zu kommen. Entzündet sie an der Schmiede von Zeth'Gor und werft die brennenden Fackeln auf die Gebäude von Zeth'Gor.", completion = "Hah! Ich konnte die Flammen über Zeth'Gor bis hierher sehen! Mögen unsere Feinde des Blutenden Auges zu Asche zerfallen und keinem wahren Orc mehr unter die Augen kommen!\n\nVielen Dank, {name}. Ihr habt geholfen, eine Beleidigung für den Geist eines jeden Orcs hinfort zu brennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10793] = { id = 10793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'zareqs Tagebuch: Vorboten des Krieges", description = "Dieses Tagebuch dokumentiert die letzten Handlungen von Illidans Armeen. Es erklärt auch, warum Val'zareq auf dem Pfad der Eroberung eine Parade abgehalten hat. Er war persönlich für die Gefangennahme eines hohen Generals der Sha'tar verantwortlich.\n\nDieser General wird an einem Außenposten namens Purpurwacht, der sich am südlichen Ende des Pfades der Eroberung befindet, gefangen gehalten. Eine mysteriöse Vereinigung, die sich selbst das Purpursiegel nennt, ist dafür verantwortlich, ihn sicher unter Verschluss zu halten. Wenn Ihr Euch entschließt, weitere Nachforschungen anzustellen, solltet Ihr einige Verbündete mitnehmen.", sourceObjective = "Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht.\n\nSucht ihn in einem Kristallgefängnis.", progress = "<General Auralion schwebt in der Mitte des Kristalls.>\n\nWa... Was tut Ihr hier?", completion = "Ihr habt ihren Eroberer getötet? Dann haben wir nicht viel Zeit...\n\nDas Purpursiegel besteht aus der Elite von Illidans Dienern. Sie stehen am oberen Ende der Befehlskette für Illidans Armeen außerhalb des Schwarzen Tempels. Diese Soldaten stehen in direktem Kontakt mit dem Verräter und führen seine Anweisung ohne Fragen zu stellen aus.\n\nSie sind diejenigen, die ohne mit der Wimper zu zucken einen Angriff auf diese Welt starten und dabei alles, was ihnen in Wege steht, dem Erdboden gleich machen würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10794] = { id = 10794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurken der Zerschmetterten Hand", description = "{name}, es gibt Geheimnisse auf dieser Welt, die wir jetzt noch nicht verstehen. Die Zerschlagene Hand in Orgrimmar kann Euch zu einem dieser Geheimnisse führen: der Kunst, tödliche Gifte zu brauen. Tut einfach, was sie sagen, und Ihr werdet ihr Vertrauen gewinnen.\n\nUm nach Orgrimmar zu kommen müsst Ihr das Portal in Silbermond nach Unterstadt nehmen. Begebt Euch danach aus der Stadt hinaus und sucht den in der Nähe gelegnen Turm auf, bei dem die Zeppeline der Goblins ihre Fahrgäste aufnehmen. Fliegt von dort aus nach Orgrimmar, wo Ihr Shenthul in der Kluft der Schatten finden könnt.", sourceObjective = "Sprecht mit Shenthul in Orgrimmar.", completion = "Ihr wollt also für die Zerschlagene Hand arbeiten? Wie es aussieht, bekommen wir jeden Tag jemand Neues dazu.\n\nHört genau zu. Ich werde Euch erklären, was Ihr zu tun habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10795] = { id = 10795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit Dorgok", description = "Gut, ich habe Euch hier gesehen und wollte Euch in einer Angelegenheit von ziemlicher Wichtigkeit sprechen.\n\nMich ereilen Berichte, laut denen die Oger der Blutschläger einen Angriff gegen Sylvanaar und den Rabenwald planen. Wir wissen nicht, wer oder was sie dazu treibt, dies zu tun, aber ich bin entschlossen, ihren Plan im Keim zu ersticken!\n\nDie Angriffe sollen vom Lager der Blutschläger aus starten. Begebt Euch nach Nordwesten den Pfad aus dem Ruuanwald hinab in das Lager. Ich möchte, dass Ihr ihren Anführer Dorgok tötet!", sourceObjective = "Tötet Dorgok im Lager der Blutschläger.", completion = "Jetzt, da Dorgok tot ist, sind die Oger der Blutschläger ohne Anführer und hoffentlich verwirrt, bis ein neuer Anführer aus ihren Rängen gewählt wird.\n\nVielen Dank, {class}. Ich glaube, wir können nun ein wenig aufatmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10796] = { id = 10796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet das Lager der Blutschläger!", description = "Ich habe gehört, dass Ihr uns im Kampf gegen die Oger bis jetzt mehr als stolz gemacht habt. Nun möchte ich Euch bitten, ihnen nochmals gegenüber zu treten. Ich möchte, dass Ihr das Lager der Blutschläger vernichtet!\n\nIhr gelangt dorthin, indem Ihr den nordwestlichen Weg aus den Ruuanwald hinab nehmt. Ihr findet die Oger am Ende des Weges.\n\nViel Glück, {class}!", sourceObjective = "Tötet 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger.", completion = "<Der Leutnant nickt und scheint mit Eurer mörderischen Kühnheit sichtlich zufrieden.>\n\nIch bin beeindruckt, {name}. Euer Ruf scheint wohlverdient zu sein.\n\nJedes Mal, wenn einer dieser Oger zu Boden geht, sind wir einen Schritt näher daran, einen Feind loszuwerden, der uns niemals in Frieden lassen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10797] = { id = 10797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gunst der Gronn", description = "Aus Dorgoks leblosem Griff fällt ein Abzeichen in Form einer kleinen Statuette. Sie hat frappierende Ähnlichkeit mit einem Gronn.\n\nKommandant Haephus Steinwall im ewigen Hain im Ruuanwald, den Weg im Osten hinauf, ist daran sicher sehr interessiert.", sourceObjective = "Bringt Gorgroms Gunst zu Kommandant Haephus Steinwall im ewigen Hain im Schergrat.", progress = "Hallo, Junge! Was gibt es Neues?", completion = "Oh, das ist aber hübsch. Sieht ein bisschen aus wie diese Gronn, die die Oger der Speerspießer immer durch die Gegend scheuchen.\n\nKomisch, dass Ihr es in der Hand eines Anführers der Blutschläger gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10798] = { id = 10798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Baron einen Besuch abstatten", description = "Das sind schlechte Nachrichten. Gorgrom der Drachenfresser steckt hinter den Plänen der Blutschläger, Sylvanaar anzugreifen.\n\nIch weiß nicht, warum er sie manipuliert und nicht einfach die Speerspießer dazu benutzt. Aber wenn wir uns mit einem Gronn auseinandersetzen müssen, werden wir Hilfe benötigen.\n\nIch kenne einen Mann, der in allen möglichen Arten exotischer Magie bewandert ist. Sein Name ist Baron Zobelmähne. Er hält sich beim Zirkel des Blutes auf. Ihr könnt dorthin gelangen, indem Ihr den Weg im Nordwesten hinabsteigt und dann nach Südenwesten durch die Schlucht geht.\n\nBittet ihn, uns eine Falle für den Gronn herzustellen.", sourceObjective = "Sprecht mit Baron Zobelmähne im Zirkel des Blutes im Schergrat.", completion = "Ah, ein Gesandter der gerühmten Allianz. Sagt mir, Lakai, warum seid Ihr es, der hierher gekommen ist und mich um dieses Ding bittet, und nicht Eurer illustrer Kommandant?\n\nKann es etwa sein, dass er Angst vor mir hat? Irgendetwas an Euch sagt mir, dass Ihr keine habt, aber ich weiß noch nicht, was das ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10799] = { id = 10799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Grabenschlucht", description = "Nun gut, ich werde diese Falle herstellen, aber zunächst möchte ich etwas dafür haben.\n\nZufälligerweise befindet sich ein Gronn in der Nähe im Besitz eines Gegenstands, den ich haben möchte. Ihr könnt ihm Euch jedoch nicht stellen, zumindest noch nicht.\n\nDaher werden wir ein Schlafpulver aus dem Gift der Krustenbohrer dieser Gegend herstellen.\n\nIhr findet sie in der Grabenschlucht im Südwesten. Bringt mir ein paar ihrer Drüsen und macht schnell!", sourceObjective = "Beschafft Euch 7 Giftdrüsen eines Krustenbohrers.", progress = "Habt Ihr die Giftdrüsen? Wenn nicht, dann hinfort mit Euch und wagt nicht, meine Zeit zu verschwenden, bevor Ihr sie habt!", completion = "Sehr gut, Ihr habt eine einfache, wenn nicht gar banale Aufgabe erfüllt. Nun gebt mir die Drüsen, damit ich den schwierigen Teil erledigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10800] = { id = 10800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Nacht, Gronn", description = "Ich habe mich mal wieder selbst übertroffen. Ich habe für Euch ein Schlafpulver erstellt, das Ihr Grulloc verabreichten könnt, dem Gronn, der besitzt, was ich möchte.\n\nGrulloc hält sich im verfluchten Dunkel auf. Diese Gegend befindet sich am östlichen Rand von Drachenend auf der anderen Seite des Zirkels des Blutes.\n\nAn Eurer Stelle würde ich nicht lange zögern, sobald Ihr seinen Sack geschnappt habt. Die Wirkung des Staubs lässt schnell nach.", sourceObjective = "Beschafft Euch Grullocs Sack.", progress = "Ihr steht mir wieder gegenüber, {class}. Das muss bedeuten, dass Ihr den Sack unter Grullocs Nase weggeschnappt habt.", completion = "<Baron Zobelmähne lugt in den Sack des Gronns und scheint zufrieden.>\n\nSehr gut, Ihr habt Euren Teil der Abmachung gehalten. Nun werde ich Euren Kommandanten mit der Falle beschenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10801] = { id = 10801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist eine Falle!", description = "Es gibt nichts, was ich auf der Welt mehr hasse, als die Söhne Gruuls und ihren Vater! Sie haben mein Volk und meine Kinder abgeschlachtet, und nun will ich meine Rache dafür!\n\nIch habe eine Falle aus Drachenfeuer gebaut. Wenn Ihr gewitzt genug seid, könnt Ihr damit einen Gronn töten.\n\nIch bin mir sicher, dass Ihr einen bestimmten Gronn in Sinn habt. Mir ist ganz gleich welcher, Hauptsache, Ihr tötet einen. Beeilt Euch und bringt die Falle zu Kommandant Steinwall.\n\nMein Rachedurst muss gestillt werden!", sourceObjective = "Bringt die Drachenfeuerfalle zu Kommandant Haephus Steinwall im ewigen Hain im Schergrat.", progress = "Hat der Baron uns eine Falle gebaut? Eine, die stark genug ist, um einen Gronn zu töten?", completion = "Hm, eine Falle, die aus der Essenz einer Drachenflamme gebaut wurde? Ich frage mich, wie Zobelmähne an eine so seltene Substanz gekommen ist!\n\nNun, ganz egal. Nicht egal ist allerdings, dass wir sie benutzen werden, um einen Sohn des Gruul zu töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10802] = { id = 10802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrom der Drachenfresser", description = "Wir müssen den Ogern zeigen, dass sie sich nicht mit uns anlegen sollten! Wir müssen ihnen eine Nachricht zukommen lassen.\n\nReist nach Fels'mok und tötet die Oger dort. Hebt ihre Köpfe auf!\n\nGeht danach zu Gorgroms Altar und stellt die Falle auf. Daraufhin wird Gorgrom erscheinen. Ihr müsst versuchen, ihn in die Falle zu locken. Wenn er tot ist, stellt die Ogerköpfe als grausige Totems bei seinem Körper auf, damit die Oger ihren gefallenen Meister und ihre gefallenen Kameraden sehen können. Dann werden sie wissen, was man bekommt, wenn man sich mit uns anlegt!", sourceObjective = "Beschafft Euch 3 grausige Totems von den Ogern von Fels'mok. Benutzt danach Zobelmähnes Falle bei Gorgroms Altar, um Gorgrom den Drachenfresser zu rufen und zu töten.\n\nPlatziert die 3 grausigen Totems in der Nähe seines Körpers, wenn er gestorben ist.", progress = "Wurde die Nachricht schon überbracht?", completion = "Gut gemacht, {name}. Sehr gut gemacht!\n\nIch nehme an, dass wir nun nicht mehr von den Ogern und ihrem Herrn hören werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10803] = { id = 10803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemetzel in Fels'mok", description = "Ich weiß, dass wir vorhaben, Euch nach Fels'mok zu schicken. Es gibt etwas, das Ihr für mich tun könntet, wenn Ihr dort seid.\n\nWir müssen jede Gelegenheit nutzen, um den Ogern dieser Berge einen Schlag zu versetzen. Sonst werden sie uns überrennen und alles, wofür wir geblutet haben und gestorben sind, zunichte machen!\n\nFels'mok liegt im Westen. Reist nach Südwesten, überquert die Brücke und geht durch den Tunnel. Ihr findet sie auf der westlichen Seite des Rabenwalds.\n\n{name}, ich möchte, dass Ihr die Oger der Speerspießer in Fels'mok auslöscht!", sourceObjective = "Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok.", completion = "<Leutnant Schönwetter grinst, als Ihr ihr von Euren Abenteuern in Fels'mok erzählt.>\n\nAch, ich wünschte, ich hätte mit Euch kommen können. Ich will Euch etwas sagen, {name}, lasst Euch nie auf Pflichten ein, die Euch vom Ruhm der Schlacht fernhalten!\n\nHa! Habt Ihr mir überhaupt noch ein paar Oger in den Bergen übrig gelassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10804] = { id = 10804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundlichkeit", description = "Etwas hat sie aufgescheucht, {race}.\n\n<Mordenai zeigt auf die Netherdrachen, die über Euch fliegen.>\n\nSie kommen nicht einmal herunter, wenn ich sie füttere. Ich habe schon einige gesehen, die einfach zu Boden fielen. Sie sind vor Erschöpfung gestorben, noch bevor ihr Körper die Erde berührt hat.\n\nWir müssen sie retten! Die Felsspitzenschinder, die sich in der Nähe der Kristalle aufhalten, sind ihre natürliche Beute. Tötet die Schinder und nehmt ihre Kadaver. Legt einen Kadaver auf das Feld und verhaltet Euch äußerst ruhig. Solange Ihr keine hektischen Bewegungen macht, werden sie Euch auch nicht angreifen.", sourceObjective = "Mordenai bei den Netherschwingenfeldern im Schattenmondtal möchte, dass Ihr 8 ausgewachsene Drachen der Netherschwingen füttert.", progress = "Ich kann sie nicht alleine retten, {name}!", completion = "Ihr seid ein freundlicher und mitfühlender {race}, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[10805] = { id = 10805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massaker in Gruuls Unterschlupf", description = "Ihr habt Euch als sehr nützlich erwiesen. Daher werde ich Euch in meinem persönlichen Kampf gegen Gruul und seine Söhne einsetzen.\n\nDer Stamm der Speerspießer steht in der Gunst der Gronn. Auch wenn Ihr ihre Reihen an anderen Orten bereits deutlich gelichtet habt, habt Ihr die Stärksten noch nicht erwischt.\n\nGruul lasst seinen Unterschlupf nur von den Kräftigsten unter den Ogern bewachen, und genau die müsst Ihr vernichten. Begebt Euch nach Norden durch die Dolchrachenklamm. An ihrem Ende findet Ihr Gruuls Unterschlupf.", sourceObjective = "Tötet 10 Vollstrecker der Speerspießer, 5 Kampfmagier der Speerspießer, 5 Felshetzer der Speerspießer und ihren Anführer Fingrom.", completion = "Sehr gut. Ich habe eine weise Wahl getroffen, als ich Euch zur Speerspitze meines Kampfes gemacht habe. Ich schätze, es ist an der Zeit, die Dinge auf eine ganz neue Ebene zu tragen.\n\nErinnert Ihr Euch an den kleinen Leckerbissen, den Ihr Grolloc für mich unter der Nase weggeschnappt habt? Ihr werdet die Gelegenheit bekommen, ihn sinnvoll einzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10806] = { id = 10806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finale", description = "Es ist für uns an der Zeit, uns Goc zu stellen, dem Herrn der Oger der Speerspießer. Es ist auch an der Zeit, dass ich mich in die Geschehnisse einmische und dem Gronn in seiner Todesstunde beiwohne.\n\nNehmt meinen Siegelring. Wenn Ihr zum Altar von Goc gelangt, benutzt ihn und ich werde Euch zur Hilfe kommen.\n\nZusammen werden wir Goc vernichten.", sourceObjective = "Benutzt Zobelmähnes Siegelring beim Altar von Goc und tötet Goc.", progress = "Bald werden alle Söhne des Gruul vernichtet sein.", completion = "Für einen wie Euch habt Ihr erstaunlich gut gekämpft. Es war mir eine Ehre, Euch an meiner Seite zu wissen. Meine Verwandlung muss Euch wohl ein wenig überrascht haben. Ich hoffe, ich habe Euch nicht allzu sehr erschreckt.\n\nWir sollten meine wahre Identität jedoch für uns behalten. Als Belohnung für Eure treuen Dienste biete ich Euch eines dieser Schmuckstücke an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10807] = { id = 10807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aschenzungen", description = "Der Aschenzungenstamm wird von allen Zerschlagenen gefürchtet. Er besteht aus den bösartigsten und blutrünstigsten Gestalten, die von Akama persönlich ausgewählt wurden. Sie sind so wild und rücksichtslos wie jeder Naga, Dämon oder Blutelf in Illidans Armee. Eine große Anzahl von ihnen wurde in den Ruinen von Baa'ri nördlich von hier stationiert. Begebt Euch dorthin und dezimiert ihre Zahl, bevor sie die Gelegenheit haben, uns anzugreifen.", sourceObjective = "Varen der Fordernde möchte, dass Ihr zu den Ruinen von Baa'ri geht und 3 Antreiber der Aschenzungen, 4 Krieger der Aschenzungen und 6 Schamanen der Aschenzungen tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ehre den Sehern, {name}. Ihr habt den Willen des Lichts ausgeführt und Illidans Anhänger vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10808] = { id = 10808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Dunklen Rat in die Quere kommen", description = "Die Geister des Dunklen Rats versuchen, ein altes und mächtiges Übel durch ein Ritual, das bei den Lavabecken südlich des Basislagers der Sketh'lon durchgeführt werden soll, in diese Welt zu beschwören.\n\nGul'dans Magie vermischt mit ihrer eigenen! Und damit wollen sie diese Kreatur in unsere Welt rufen! Das dürfen wir nicht zulassen, {name}. Der Tod und die Zerstörung, die dieses Wesen in unsere Welt bringen würde, sind unvorstellbar!\n\nBringt den Stab zu dem Ort, an dem sie die Beschwörung durchführen wollen und benutzt seine Magie, um den Dunklen Rat ein für allemal aufzuhalten!", sourceObjective = "Tötet die Ritualisten des Dunklen Rats und benutzt Parshahs Stab, um das Beschwörungsritual des Dunklen Rats zu beenden. Kehrt danach zu Parshah in den Magmafeldern zurück.", progress = "Ist es vollbracht, {name}? Habt Ihr den Dunklen Rat davon abgehalten, das Ritual zu vollenden?", completion = "Ich habe jahrelang nach einem Weg gesucht, um den Dunklen Rat aufzuhalten. Ihr habt geschafft, wobei ich versagt habe. Die finsteren Rituale des Dunklen Rats werden nie wieder zu einer Bedrohung für uns.\n\nIch fühle mich oft schuldig, weil ich meine Kameraden vor all diesen Jahren verlassen habe, aber nun weiß ich endlich, dass es die richtige Entscheidung war. Hätte mein Gewissen damals nicht zu mir gesprochen, wäre ich nun vielleicht ein Schatten unter ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10809] = { id = 10809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Worgmeister Kruush", description = "Auf dem Anschlag steht geschrieben:\n\n\"Worgmeister Kruush führt die Worgreiter des Blutenden Auges an. Da seine Reiter große Opfer unter den Versorgungskarawanen des Rückenbrecherpostens gefordert haben, wurde ein Preis auf seinen Kopf ausgesetzt.\"\n\n\"Späher berichten, dass er in Zeth'Gor gesehen wurde. Der Held, der den abgetrennten Kopf des Übeltäters zu mir bringt, wird den Dank der Horde sowie ein großzügiges Kopfgeld erhalten.\"\n\nGezeichnet: Hauptmann Nachtheul", sourceObjective = "Tötet Worgmeister Kruush und bringt seinen Kopf zu Hauptmann Nachtheul im Rückenbrecherposten.", progress = "Berichtet, {name}. Ist das Blut des Blutenden Auges da auf Eurem Ärmel? Ich hoffe doch!", completion = "Ihr habt also den Tunichtgut Kruush erschlagen! Gut gemacht, {name}! Sehr gut! Sein Tod wird seinen verfluchten Worgreitern die Giftzähne ziehen! Ich hoffe, Ihr habt auch ein paar von ihnen erledigt, als Ihr Euren kleinen Ausflug nach Zeth'Gor gemacht habt!\n\nHier ist Eure Belohung. Ihr habt sie Euch verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[10810] = { id = 10810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beschädigte Maske", description = "Während ihr die beschädigte Maske betrachtet, hört Ihr Geräusche aus ihrem Inneren kommen. Wenn die Maske nicht beschädigt wäre, könntet Ihr die Geräusche deutlicher hören.\n\nO'Mally Zapschnapper im Ruuanwald könnte sie vielleicht reparieren.", sourceObjective = "Bringt die beschädigte Maske zu O'Mally Zapschnapper in den ewigen Hain im Schergrat.", progress = "Geht mir nicht auf die Nerven! Könnt Ihr nicht sehen, dass ich dabei bin, mysteriöse Kräfte zu entfesseln?", completion = "Ah, was habt Ihr denn da? Lasst mich das mal genauer ansehen, {class}. Ja, ja... es ist genau das, was ich dachte. Lasst mich die Maske für Euch reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10811] = { id = 10811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Neltharaku auf", description = "Ihr Patron schwebt hoch oben in den Lüften, {name}. Vielleicht hat die Freundlichkeit, die Ihr seinen Kindern gegenüber gezeigt habt, sein Herz bewegt. Sucht Neltharaku auf und bittet ihn um Hilfe. Zusammen könnt Ihr vielleicht die Not der Netherschwingendrachen beenden.\n\n<Mordenai zeigt in den Himmel.>\n\nFliegt hoch, Freund...", sourceObjective = "Sucht Neltharaku, den Patron des Drachenschwarms der Netherschwingen auf.", completion = "Meine Kinder haben mir von Eurer heldenhaften Tat erzählt, {race}. Es gibt noch mehr, was Ihr tun könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10812] = { id = 10812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geheimnisvolle Maske", description = "Gut, jetzt sollte sie funktionieren. Was das ist, fragt Ihr? Nun, es ist ein Kommunikationsgerät. Diese Schafsköpfe kommunizieren so miteinander. Ihr wisst schon, die Brennende Legion! Ich würde Euch empfehlen, die Maske zu Wildfürst Antelarion zu bringen. Er geht dort drüben auf und ab. Immer in Bewegung!\n\nNun los mit Euch! Er versucht schon eine ganze Weile eine von den Masken in die Finger zu bekommen.", sourceObjective = "Bringt die geheimnisvolle Maske zu Wildfürst Antelarion in den ewigen Hain im Schergrat.", progress = "Ich traue meinen Augen nicht.", completion = "Diese Maske, die Ihr da in den Händen haltet, ist eine Gasmaske der Teufelsbrut! Und wie es aussieht, ist sie nicht beschädigt! Der Ärger, den wir damit im Konstruktionslager: Groll anrichten können, ist grenzenlos! Habt Ihr Lust, uns dabei zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10813] = { id = 10813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Grillok", description = "{name}, Ihr habt im Nest der Orcs des Blutenden Auges, im gefürchteten Zeth'Gor, Euren Heldenmut bewiesen und überlebt! Vielleicht seid Ihr stark genug, um mir zu helfen, denn ich werde in den Geist ihres finstersten Hexers blicken, Grillok!\n\nNehmt diesen Splitter. Benutzt ihn, um ein Auge von Grillok zu behexen und bindet es an Euch. Kehrt dann zu mir zurück und nähert Euch meinem Kessel... er wird das Auge anziehen.\n\nGeht, {name}. Und seid auf der Hut! Ein Auge von Grillok wird Euch an Eure Feinde verraten, wenn es auch nur die geringste Gelegenheit dazu bekommt!", sourceObjective = "Benutzt Zezzaks Splitter, um ein Auge von Grillok zu fangen und nähert Euch damit Zezzaks Kessel. Bringt den Splitter zu Zezzak zurück, wenn Ihr das Auge dem Kessel übergeben habt.", progress = "Die Orcs des Blutenden Auges waren einst starke Verbündete... und nun sind sie noch stärkere Feinde.", completion = "Ich stehe tief in Eurer Schuld, {name}. Ihr habt ein weiteres Mal über Zeth'Gor triumphiert und seine Dunkelheit nahe an Euer Herz gelassen. Ich werde das Auge untersuchen und damit hoffentlich die Geheimnisse seines Meisters Grillok lüften.\n\nHoffentlich kann es seine Magie nicht länger einsetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10814] = { id = 10814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharakus Geschichte", description = "Ich habe Informationen, die Euch vielleicht weiterhelfen können. Bitte hört Euch an, was ich zu erzählen habe.", sourceObjective = "Sprecht mit Neltharaku und hört Euch seine Geschichte an.", completion = "Werdet Ihr uns also helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10815] = { id = 10815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'zareqs Tagebuch: Vorboten des Krieges", description = "Dieses Tagebuch dokumentiert die letzten Handlungen von Illidans Armeen. Es erklärt auch, warum Val'zareq auf dem Pfad der Eroberung eine Parade abgehalten hat. Er war persönlich für die Gefangennahme eines hohen Generals der Sha'tar verantwortlich.\n\nDieser General wird an einem Außenposten namens Purpurwacht, der sich am südlichen Ende des Pfades der Eroberung befindet, gefangen gehalten. Eine mysteriöse Vereinigung, die sich selbst das Purpursiegel nennt, ist dafür verantwortlich, ihn sicher unter Verschluss zu halten. Wenn Ihr Euch entschließt, weitere Nachforschungen anzustellen, solltet Ihr einige Verbündete mitnehmen.", sourceObjective = "Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10816] = { id = 10816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückforderung geheiligten Bodens", description = "Ihr habt Eure Arbeit bei den Zerschlagenen in Baa'ri gut gemacht, {name}. Wollen wir mal sehen, wie Ihr gegen Illidans gefürchtetste Armee besteht.\n\nDie Terrasse von Ata'mal war einst eine geheiligte Stätte, an der wir die Kristalle von Ata'mal benutzten, um spirituelle Zeremonien durchzuführen. Nun ist dieser Orts von den Höllenorcs des Schattenmondklans besetzt worden.\n\nWir hatten guten Grund zur Annahme, dass sie einen Kristall von Ata'mal in der Nähe versteckt halten, aber unsere magische Beobachtung dieses Ortes lieferte kein Ergebnis. Dennoch sind die Orcs auf unserem geheiligten Boden eine Schmach, die wir nicht tolerieren können.", sourceObjective = "Verteidiger Aluumen möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.\n\nDas Abschließen von Aufgaben für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ausgezeichnete Arbeit, {class}. Möge das Licht Euch beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10817] = { id = 10817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Vergeltung", description = "Ihr habt Euch im Kampf gegen die Zerschlagenen der Aschenzungen tapfer geschlagen, {name}. Wenn Ihr bereit seid, habe ich eine weitere Herausforderung für Euch.\n\nVor nicht allzu langer Zeit wurde das Sanktum der Sterne Opfer eines gewaltigen Angriffs durch Illidans Höllenorcs.\n\nWir haben herausgefunden, dass die Schattenmondorcs, die die Terrasse von Ata'mal behausen, dieses Verbrechen verübt haben.\n\nZeigt ihnen, dass man sich besser nicht mit den Sehern anlegen sollte!", sourceObjective = "Varen der Fordernde möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ihr habt meinen höchsten Respekt verdient, {name}.\n\nEinen Höllenorc alleine zu töten ist schon keine leichte Aufgabe. Eine ganze Meute von ihnen zu töten ist, nun... heroisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10818] = { id = 10818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Zobelmähne verlangt nach Euch", description = "{name}, während Ihr Euch da draußen als Bild von <einem/einer:c> {class} bewiesen habt, hat Baron Zobelmähne seinen Drachen mit einer Nachricht hierher geschickt.\n\nEr hat nach Euch persönlich gefragt. So wie ich es verstanden habe, möchte er, dass Ihr seinen eigenen Kampf gegen die Gronn weiterführt.\n\nIch schätze, dass Ihr wohl die geeignetste Person in der ganzen Scherbenwelt seid, um ihm dabei zu helfen, aber an Eurer Stelle würde ich ein paar Freunde bitten, Euch zum Zirkel des Blutes zu begleiten.", sourceObjective = "Sprecht mit Baron Zobelmähne im Zirkel des Blutes im Schergrat.", completion = "Ah, wie ich sehe habt Ihr beschlossen, Euch ganz schön Zeit zu lassen, bis Ihr meinem Aufruf Folge geleistet habt.\n\nWie auch immer, ich hatte genug Zeit, um an meinen Racheplänen zu feilen, und Ihr sollt in der kommenden Schlacht mein Vollstrecker sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10819] = { id = 10819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gasmaske der Teufelsbrut", description = "Ich habe eine ganz besondere Aufgabe für Euch, {name}. Ich möchte, dass Ihr Euch in das Konstruktionslager: Groll östlich von hier einschleicht. Ihr werdet die Gasmaske der Teufelsbrut tragen müssen, wenn Ihr das Lager betretet, um den Legionskommunikator zu suchen. Sobald Ihr das Kommunikationsgerät gefunden habt, benutzt es. Sprecht mit demjenigen, der sich auf der anderen Seite meldet.\n\nWenn alles klappt, könnt Ihr dem Dämon ein Märchen auftischen! Versucht, ihm zu erzählen, dass im Konstruktionslager: Groll ein Aufstand ausgebrochen ist.\n\nViel Glück, {class}.", sourceObjective = "Setzt die Gasmaske der Teufelsbrut auf und benutzt den Legionskommunikator im Konstruktionslager: Groll im Schergrat.\n\nBereitgestellter Gegenstand:", completion = "Was soll das bedeuten? Niemand ruft mich! Sprecht, oder ich werde Euch für immer zum Schweigen bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10820] = { id = 10820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täuscht den Feind", description = "Mit jedem Moment, in dem ich Stille höre, rückt Ihr dem Tod ein Stückchen näher! SPRECHT!\n\nWas? Das Lager revoltiert? Das kann nicht wahr sein! Meine Diener würden es niemals wagen, meine Autorität zu untergraben.\n\nNun gut, jeder Einzelne von ihnen wird für diesen Verrat bezahlen... teuer bezahlen! Bringt sie alle zum Schweigen! Meldet Euch bei mir zurück, wenn Ihr meinen Befehl ausgeführt habt, oder ich werde mich um Euch kümmern.", sourceObjective = "Tötet 4 Knechte der Schicksalsschmiede und 4 Ingenieure der Schicksalsschmiede.", progress = "Meine Geduld neigt sich dem Ende zu, warum habt Ihr sie noch nicht erledigt?", completion = "Das wird ihnen sicher zeigen, dass sie besser tun sollten, was ich ihnen sage...\n\nÜbrigens... wo ist Schicksalsrufer? Warum habt Ihr mir von dieser Revolte berichtet und nicht sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[10821] = { id = 10821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid gefeuert!", description = "Schicksalsruferin hat nichts gegen den Aufstand unternommen? Wie kann sie es wagen! Sie hat schon seit einer Weile versucht, meine Autorität zu untergraben. Doch zum allerletzten Mal! Ihr müsst sie rufen und persönlich zur Verantwortung ziehen.\n\nIhre Grollwachen tragen die Schlüssel bei sich, mit denen sie ins Konstruktionslager: Groll gerufen werden kann. Beschafft Euch die fünf Schlüssel und aktiviert die fünf Obelisken der Legion. Die Obelisken schalten sich nach kurzer Zeit wieder ab, also seht zu, dass Ihr sie alle gleichzeitig aktiviert. Und denkt daran: die Grollwachen tragen noch mehr Schlüssel bei sich.", sourceObjective = "Tötet Schicksalsruferin.", completion = "Das sind wirklich großartige Nachrichten, {name}. Ich hätte es mir nicht besser wünschen können. Eure Dienste gegenüber meinem Volk sind sehr geschätzt. Bitte wählt Euch einen dieser Gegenstände aus.\n\nEuer Name wird für immer in den Herzen unseres Volkes klingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10822] = { id = 10822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Siegel des Sonnenzorns", progress = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, {name}. Unsere Feinde sind stark, aber wir werden siegen!", completion = "Sieg für die Seher! Kaels Streitmächte werden bald fallen!" }
quests[10823] = { id = 10823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Siegel des Sonnenzorns", progress = "Wir verläuft der Kampf gegen Kaels Streitmächte?", completion = "Ihr macht Euch einen Namen, {name}. Weiter so!" }
quests[10824] = { id = 10824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des Sonnenzorns", description = "Das Überleben der Seher hängt davon ab, ob wir es schaffen, mehr Rekruten zu sammeln als Kael'thas. Jeder Pilger aus Quel'Thalas, der sich auf seine Seite schlägt, bringt ihn einen Schritt näher an den Sieg. Und das bedeutet das Gegenteil für uns.\n\nBald werden uns jedoch die Rekruten ausgehen und es wird darauf hinauslaufen, wer den anderen schneller tötet. Beweist Euch gegenüber den Sehern und bringt mir die Siegel des Sonnenzorns der höherrangigen Blutelfen, die im Bunde mit Illidan und Kael'thas stehen. Ihr findet sie bei der Stätte der Mondfinsternis im Westen und in den Ruinen von Karabor im Nordosten.", sourceObjective = "Kampfmagierin Vyara beim Sanktum der Sterne möchte, dass Ihr ihr 10 Siegel des Sonnenzorns bringt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Los, {name}. Sprecht.", completion = "Kaels Armee des Sonnenzorns ist sehr gut ausgebildet. Ausgezeichnete Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10825] = { id = 10825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die kugellose Wahrheit", description = "Diese merkwürdige, magische Kugel fällt aus dem Federkleid des Arakkoa.\n\nSie ist von einem unheimlichen violetten Leuchten umgeben und pulsiert zu einem unhörbaren Takt. Sie in der Hand zu halten gibt Euch ein unangenehmes Gefühl, daher packt Ihr sie schnell in Eure Tasche.\n\nVielleicht würde Baumhüter Chawn im Ruuanwald im Westen, jenseits des Tunnels und der Brücke des Wyrmschädels, sie gerne untersuchen?", sourceObjective = "Bringt die Kugel der Grishna zu Baumhüter Chawn in den ewigen Hain im Schergrat.", progress = "{class}, könnt Ihr das spüren? Ich fühle, dass etwas Unnatürliches und Böses in der Nähe ist.", completion = "Ja, es ist die Kugel, die Ihr da habt! Merkwürdig, sie scheint von den Arakkoa zu stammen. Wart Ihr kürzlich in Grishnath?\n\nAh, das erklärt das Ganze. Aber ich frage mich, welchem teuflischen Zweck dieses Objekt dient. Obwohl das Böse eindeutig darin schlummert, scheint sie doch mit der Natur verbunden zu sein.\n\nBitte erlaubt mir zu versuchen, sie zu aktivieren. Das Böse darin ist so stark, es erinnert mich an etwas...", sourceObjectiveStatus = "unverified-source-field" }
quests[10826] = { id = 10826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Male des Sargeras", description = "Inzwischen sollte Euch klar geworden sein, dass wir der Brennenden Legion und ihren Dienern feindlich gesonnen sind.\n\nWenn Ihr Euch den Aldor gegenüber beweisen wollt, dann bringt mir die Insignien der hochrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Hier im Schattenmondtal könnt Ihr eine große Ansammlung der Legion weit im Westen in der Feste der Legion und der Todesschmiede finden.", sourceObjective = "Bringt 10 Male des Sargeras zu Herold Saronen im Schattenmondtal.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Tragt Ihr irgendwelche Insignien des Feindes bei Euch, {name}?", completion = "Ihr seid sehr mutig, Freund. Mögen alle wissen, dass Ihr ein wahrer Freund der Priesterschaft seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[10827] = { id = 10827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Male des Sargeras", progress = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, {name}? Wir bekämpfen die Legion, bis das Licht siegt!", completion = "Besiegt die Feinde des Lichts, wo immer Ihr sie findet, {name}." }
quests[10828] = { id = 10828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Male des Sageras", progress = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", completion = "Ihr beweist auch weiterhin Euren Wert, {name}." }
quests[10829] = { id = 10829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baumriese muss es wissen", description = "Das ist erschütternd! Die Arakkoa bewirken, dass die Urtume und Beschützer von bösen Geistern besessen werden!\n\nEs gibt jedoch ein Urtum, das auf gar keinen Fall davon betroffen sein kann. Sein Name ist Baumriese. Wenn wir die Bäume des Rabenwaldes retten wollen, müsst Ihr sofort zu ihm gehen!\n\nBegebt Euch in den Rabenwald. Ihr findet ihn an der Weggabelung kurz hinter Grishnath.", sourceObjective = "Sprecht mit Baumriese, ein Urtum der Lehren, das im Rabenwald im Schergrat lebt.", completion = "Grüße, kleiner {race}. Die Vögel in meinen Zweigen haben mir zugeflüstert, dass Ihr kommen würdet.\n\nIhr seid hier, um die Bäume des Waldes von ihrer Besessenheit zu heilen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10830] = { id = 10830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Exorzismus der Bäume", description = "Die Grishna sind dafür verantwortlich, dass die Laubbärte und Steinborken von bösen Koikoigeistern übernommen werden.\n\nWir müssen die Bäume retten, sonst ist der Rabenwald bald verloren!\n\nKombiniert die Macht einer Kugel von Grishnath, die überall in Grishnath zu finden sind, mit einem Terrorfederkiel eines Terrorraben.\n\nBenutzt die dadurch entstandene Exorzismusfeder, um die Koikoigeister hervorzulocken und so schnell wie möglich umzubringen. Die Steinborken sind für dieses Ritual zu stark, aber wenn Ihr genügend Laubbärte befreit, werden auch sie frei sein.", sourceObjective = "Sammelt 5 Kugeln von Grishnath und 5 Terrorfederkiele und stellt daraus Exorzismusfedern her. Benutzt die Federn, um 5 Koikoigeister von den Laubbärten des Rabenwaldes zu exorzieren und zu töten.", progress = "Das Böse, das den Bäumen innewohnt, breitet sich auf die gesamte Natur des Waldes aus.\n\nIhr müsst schnell handeln, {name}, bevor es zu spät ist!", completion = "Das Böse verschwindet aus dem Rabenwald! Könnt Ihr es fühlen, {name}?\n\nIhr habt uns und alle Wildtiere hier vor der unweigerlichen Zerstörung gerettet, kleines Wesen!\n\nFür solche Gelegenheiten trage ich vier magische Ringe in meinen Zweigen und verschenke sie, wenn ein Held sich erhebt, um eine große Tat zu vollbringen.\n\nIhr seid solch ein Held! Im Namen des gesamten Rabenwaldes danke ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10831] = { id = 10831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Mondstoffschneider wird", description = "Ich kann Euch die Kunst des Mondstoffschneiderns beibringen, wenn Ihr möchtet. Wenn Ihr Euch auf die Mondstoffschneiderei spezialisiert, werdet Ihr bei der Herstellung von Urmondstoff den doppelten Ertrag erhalten und Zugang zu mehreren exklusiven Mustern bekommen. Dazu müsst Ihr nur einen einfachen Test bestehen.\n\nDer Test besteht darin, eine kleine Probe Urmondstoff im Mondbrunnen der Zuflucht des Cenarius herzustellen. Ich werde Euch alle Materialien, die Ihr dafür benötigt, zur Verfügung stellen. Bringt mir die Probe, wenn Ihr sie fertig gestellt habt, damit ich sie beurteilen kann.", sourceObjective = "Benutzt das magieerfüllte Netherstoffstück während Ihr im Mondbrunnen der Zuflucht des Cenarius steht, um eine Urmondstoffprobe herzustellen. Bringt die fertige Urmondstoffprobe zu Nasmara Mondweise im unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", progress = "Habt Ihr die Urmondstoffprobe hergestellt?", completion = "<Nasmara untersucht den Stoff und dreht ihn in den Händen hin und her.>\n\nDas ist eine hervorragende Probe, {name}. Ihr werdet einen ausgezeichneten Mondstoffschneider abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10832] = { id = 10832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Zauberfeuerschneider wird", description = "Ich kann Euch die Kunst der Zauberfeuerschneiderei beibringen, aber seid gewarnt, es ist eine gefährliche Kunst.\n\nDie Herstellung von Zauberstoff im Nethersturm lockt mächtige Nethergespenster an. Ich bin auf der Suche nach einem Weg, um den Effekt zu mildern, aber dazu brauche ich noch mehr Essenzen der Nethergespenster für meine Forschungen.\n\nBringt dieses Signal zum Nethersturm und benutzt es, um ein Nethergespenst zu rufen. Bringt mir seine Essenz, dann werde ich Euch unterrichten. Als Zauberfeuerschneider werdet Ihr doppelt so viel Stoff erhalten und Zugang zu exklusiven Mustern bekommen.", sourceObjective = "Bringt eine Probe einer Nethergespenstessenz zu Gidge Spruchwirker im unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", progress = "Habt Ihr die Nethergespenstprobe?", completion = "<Gidge untersucht die Nethergespenstessenz.>\n\nSogar in dieser kleinen Probe der Essenz ist seine Macht deutlich sichtbar. Vielleicht habe ich missverstanden, was vor sich geht. Wir erzürnen die Gespenster nicht, wenn wir der Umwelt die Energie nehmen. Die Umwelt und die Geister sind vielmehr eins!\n\nZögert nicht, mich zu informieren, wenn Ihr weitere Entdeckungen machen solltet... nun, da Ihr ein Zauberfeuerschneider seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[10833] = { id = 10833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Schattenzwirnschneider wird", description = "Wenn Ihr Euch auf die Schattenzwirnschneiderei spezialisiert, werdet Ihr doppelt so viel Schattenstoff wie ein gewöhnlicher Schneider herstellen können und Zugang zu exklusiven Mustern erhalten.\n\nNatürlich kann jeder Schneider den Altar der Schatten benutzen, aber ein Schattenzwirnschneider hat eine tiefere Verbindung zu dem Altar und entfesselt dadurch Mächte, die sich nur wenige vorstellen können.\n\nBringt diesen Kristall in das östliche Schattenmondtal und sucht den Netherschwingenpass, der von den Netherschwingenfeldern aus nach Süden führt. Nahe am Ende der Welt findet Ihr den Altar der Schatten. Benutzt dort den Kristall.", sourceObjective = "Benutzt den Kristall der tiefen Schatten in der Nähe des Altars der Schatten, um Eure Verbindung zu dem Altar zu stärken. Kehrt danach zu Andrion Dunkelweber im unteren Viertel in Shattrath zurück.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", completion = "Wie ich sehe war Euer Besuch beim Altar erfolgreich. Etwas an Euch hat sich verändert. Nur wenigen wird es auffallen, aber es ist ohne Zweifel da.", sourceObjectiveStatus = "unverified-source-field" }
quests[10834] = { id = 10834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grillok 'Finsterauge'", description = "Grillok Finsterauge hat einen Teil von sich den dunklen Mächten verpfändet und dafür große Macht erhalten. Sein verlorenes Auge brennt nun in irgendeiner teuflischen Grube als Schmuckstück eines Dämonen... und die Klappe, die seinen Verrat versteckt, hat ihr ganz eigenes dunkles Geheimnis.\n\nBringt mir Grilloks Augenklappe, {name}, und ich werde Euch fürstlich für Eure Dienste belohnen.", sourceObjective = "Tötet Grillok Finsterauge und bringt Grilloks Augenklappe zu Zezzak im Rückenbrecherposten.", progress = "Die Bösartigkeit der Orcs des Blutenden Auges kennt keine Grenzen und wird nur noch von der ihrer Vettern der Zerschmetterten Hand übertroffen.", completion = "Ah ja. Ich frage mich, ob Grillok in seinen dunklen, dunklen Träumen immer noch mit seinem verlorenen Auge verbunden ist, wie jemand, der eine Hand oder ein Bein in der Schlacht verloren hat...\n\nAuch ich werde davon träumen. Und wenn das Schicksal auf unserer Seite steht, werden wir dadurch erfahren, was Grillok und die Orcs des Blutenden Auges dazu gebracht hat, sich den Dämonen zu unterwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10835] = { id = 10835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apotheker Antonivich", description = "{name}, ich habe einen vorläufigen Bericht über meine Befunde bezüglich der Orcs des Blutenden Auges angefertigt. Mein Kollege in Thrallmar, Apotheker Antonivich, will ihn sicher gerne lesen. Auch er befasst sich mit dem Phänomen der Höllenorcs und hofft verhindern zu können, dass eine solche Tragödie auch unseren orcischen Verbündeten zustoßen könnte.\n\nBringt diesen Bericht zu ihm. Ich werde in der Zwischenzeit weiter das Blut, das Ihr mir gebracht habt, untersuchen. Wenn das Glück auf unserer Seite ist, können wir die Ursache für das Leiden der Höllenorcs herausfinden.", sourceObjective = "Bringt Albrecks Befund zu Apotheker Antonivich nach Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Guten Tag, {name}. Wie gefällt Euch Euer Aufenthalt auf der Höllenfeuerhalbinsel? Ich bin mir sicher, dass er sehr ergiebig ist...", completion = "Ah, ein Bericht von Albreck? Sehr gut. Die königliche Apothekervereinigung versucht verzweifelt herauszufinden, wie die Orcs der Höllenfeuerhalbinsel zu Höllenorcs geworden sind. Ihr Verrat ist unverzeihlich... und wir müssen sicherstellen, dass unsere Orcfreunde für alle Zeit vor dieser Verderbnis sicher sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[10836] = { id = 10836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwanderung der Festung des Drachenmals", description = "Ich brauche Zeit, um einen Plan zu entwickeln, mit dem ich meine Kinder und mein Weibchen retten kann. Ihr werdet mir diese Zeit beschaffen, <Sterblicher/Sterbliche>.\n\nReist zur Festung des Drachenmals am östlichen Ende der Netherschwingenfelder und vernichtet alle Orcs des Drachenmals, die Ihr finden könnt. Das daraus resultierende Chaos und die Verwirrung sollte ihre Pläne maßgeblich beeinflussen.\n\nDoch seid auf der Hut. Einige meiner Art sind bereits von den Orcs des Drachenmals verderbt worden. Für sie besteht die einzige Erlösung im Tod. Ihr habt meine Erlaubnis, auch ihr Leben zu beenden.", sourceObjective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 15 Orcs des Drachenmals tötet.\n\nSämtliche Orcs des Drachenmals in der Festung des Drachenmals kommen dafür in Frage.", progress = "Ist es vollbracht? Ich hoffe nur, dass es noch nicht zu spät ist...", completion = "Gut gemacht, {name}. Ich habe einen Weg gefunden, wie wir die versklavten Drachen in der Festung des Drachenmals befreien können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10837] = { id = 10837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Netherschwingenscherbe!", description = "Ich glaube, dass ich die Netherrankenkristalle mit meiner eigenen Essenz erfüllen kann. Die Macht in diesen magieerfüllten Kristallen sollte ausreichen, um die versklavten Drachen aus den Klauen ihrer Meister zu befreien.\n\nReist zur Netherschwingenscherbe, einer Insel am zerbrochenen Rand des Schattenmondtals im Südosten. Auf der Netherschwingenscherbe könnt Ihr die Netherrankenkristalle finden. Kehrt zu mir zurück, wenn Ihr genügend Kristalle gefunden habt, um Eure Taschen damit zu füllen.\n\nUnd Vorsicht, {name}. Der Drachenmalklan hat sich nun auf der Insel niedergelassen.", sourceObjective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 12 Netherrankenkristalle auf der Netherschwingenscherbe sammelt.", progress = "Ich brauche Netherrankenkristalle.", completion = "<Neltharaku nimmt Euch die Kristalle ab.>\n\nIch werde nun die Kristalle mit meiner Magie erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10838] = { id = 10838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dämonische Seher", description = "Der dämonische Seher ist nun bereit. Bringt ihn hinter die Höllenfeuerzitadelle, in das Höllenfeuerbecken, und platziert ihn dort auf dem Boden. Er wird sich dann selbst auf die Höllenfeuerzitadelle einstellen. Sprecht danach mit dem Seher und schreibt auf, was Ihr erfahrt. Bringt Euren Aufschrieb zu mir...\n\nGeht, {name}, aber erst, wenn Ihr bereit seid. Die Höllenfeuerzitadelle wird ohne Zweifel die Anwesenheit des Sehers entdecken und Wärter schicken, um ihn zu vernichten!", sourceObjective = "Benutzt den dämonischen Seher im Höllenfeuerbecken, wartet, bis er sich eingestellt hat und führt dann eine Messung durch.\n\nBringt den dämonischen Seher und die Messungen des dämonischen Sehers zu Apotheker Antonivich in Thrallmar.", progress = "Habt Ihr die Messung? War Euer Auftrag mit dem dämonischen Seher erfolgreich?", completion = "Ihr habt die Messung? Ausgezeichnet. Ich bin mir sicher, dass diese Daten sich für unsere Forschungen als unersetzlich erweisen werden. Ich werde sie gleich an Apothekerin Zelana und Apotheker Albreck weiterleiten.\n\nIhr solltet stolz auf Euch sein, {name}. Eure Stärke und Euer Mut steht außer Frage... genauso wie Eure Leistungen gegenüber der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10839] = { id = 10839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelstein des Skithverstecks", description = "Das Skithversteck liegt nordwestlich der Karawane und südlich von Shattrath in einem versteckten Hain im Wald. Man sagt, dass die Kolonie von Skettis dort einen bösartigen Altar der Verehrung errichtet hat. Wenn die Arakkoa der Skith jemals erlöst werden wollen, muss Terokks Dunkelstein zuerst geläutert werden.\n\nNehmt diese Rute der Läuterung und werft sie auf den Dunkelstein. Da sie von A'dal selbst gesegnet wurde, sollte die Reinheit der Rute stark genug sein, um den Dunkelstein zu reinigen. Nun geht. Möge das Licht über Euch wachen.", sourceObjective = "Benutzt die Rute der Läuterung bei Terokks Dunkelstein im Skithversteck und kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane in der Knochenwüste zurück.", progress = "Die Dunkelheit umgibt uns. Was habt Ihr mir aus dem Skithversteck zu berichten?", completion = "Ich habe bis hierher die Explosion hören können. Nicht mit meinen Ohren, sondern mit meinem Herzen.\n\nWenn die Berührung des gesegneten Naaru A'dal nicht ausreicht, um die Arakkoa zu erlösen, dann kann nichts auf der Welt das schaffen. Diejenigen, die ihre Seele nicht dem Licht ausgeliefert haben, sind nichts als Diener des Bösen.\n\nSie müssen vernichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10840] = { id = 10840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grab des Lichts", description = "Im Osten, unter dem versengten Sand, befindet sich das Grab des Lichts. Das Grab ist eine verlorene Ruhestätte unserer Toten. Bevor unsere Karawane überfallen wurde, war ich auf dem Weg zu dem Grab, um es von bösen Geistern zu befreien.\n\nIch hatte ja keine Ahnung, dass es bereits von einem anderen Übel heimgesucht wird. Sogar jetzt noch plündern die Astralen die Körper unsere Gefallenen, um an die Schmückstücke und Andenken zu kommen, die den Toten vor Jahrhunderten mit ins Jenseits gegeben wurden.\n\nAber ich kann nichts dagegen unternehmen, solange unsere Karawane ums Überleben kämpft.", sourceObjective = "Hohepriester Orglum möchte, dass Ihr zum Grab des Lichts reist und 10 astrale Nethermanten und 10 astrale Brandschatzer tötet. Kehrt danach zu ihm zurück. Zu finden ist er bei der Flüchtlingskarawane.", completion = "Hier in der Wildnis der Scherbenwelt sind wir schwach. Nur wenige Helden verteidigen unsere Rechte, aber Ihr habt ihnen gezeigt, dass sie sich fürchten müssen, {class}. Ich glaube nicht, dass die Astralen Euren starken Arm so schnell vergessen werden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10841] = { id = 10841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der rachsüchtige Herold", description = "Geht in das Grab des Lichts und aktiviert das Gerät.", sourceObjective = "Aktiviert das Gerät.", sourceObjectiveStatus = "unverified-source-field" }
quests[10842] = { id = 10842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rachsüchtige Seelen", description = "Das Grab des Lichts wurde vom Schattenrat verderbt und die toten Draenei wurden zu verfluchten Geistern, die von Zorn erfüllt sind und vor Hass auf die Lebenden brennen.\n\nBetretet das Grab", sourceObjective = "Hohepriester Orglum möchte, dass Ihr in das Grab des Lichts reist und 5 rachsüchtige Draenei besiegt.", progress = "Ihr habt uns alle gerettet. Wie können wir Euch nur danken?", completion = "Ihr könnt nicht wissen, was Ihr hier getan habt, {name}. Ihr habt so viele von uns aus einer ewigen Dunkelheit errettet. Ich kann nur wenig für die Lebenden tun und Euch nichts geben, das als Dank für Euch ausreichen würde. Nehmt Euch, was Euch nützlich erscheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[10843] = { id = 10843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seit ich denken kann...", description = "Schon seit ich denken kann haben wir gegen die Oger der Speerspießer gekämpft.\n\nWir haben es geschafft, sie so weit zurück zu drängen, dass sie nun nur noch im Außenposten der Speerspießer vertreten sind. Dieser Außenposten befindet sich dort, wo Ihr herkommt, am südwestlichen Rand des Messergrats.\n\nBeweist mir Euren Wert, indem Ihr ihren Anführer Gnosh Brognat tötet.\n\nWollen wir mal sehen, aus welchem Holz Ihr geschnitzt seid, wenn es darum geht, die Oger zu bekämpfen.", sourceObjective = "Tötet Gnosh Brognat, den Anführer der Oger im Außenposten der Speerspießer.", completion = "<Leoroxx mustert Euch aufmerksam.>\n\nGnosh Brognats Tod ist ein Segen für alle Mok'Nathal. Das ist gut für Euch.\n\nMal schauen, ob Ihr immer noch so heldenhaft seid, wenn wir die Messlatte etwas anheben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10844] = { id = 10844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager: Groll" }
quests[10845] = { id = 10845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Brutmutter", description = "Meine Jäger sind gerade von einer Aufklärungsmission im singenden Bergrücken zurückgekehrt. Wie es aussieht hat sich die Zahl der Netherdrachen, die die Kristalle dort heimsuchen, deutlich vergrößert. Bald werden sie sich weiter ausbreiten!\n\nDa Ihr Euch als <fähiger/fähige:c> {class} herausgestellt habt, wollen wir einmal sehen, ob Eure Fertigkeiten einem ausgewachsenen Drachen gewachsen sind.\n\nIhr findet den singenden Bergrücken, indem Ihr nach Süden durch die Schuppenflügelbank geht. Tötet ihre Brutmutter, Unheilschwinge.", sourceObjective = "Tötet Unheilschwinge.", completion = "Nein! Ihr habt Unheilschwinge getötet? Vielleicht habe ich mich in Euch getäuscht, {class}.\n\nVielleicht.\n\nDennoch habt Ihr die Anführer der drei größten Bedrohungen für unser Volk erschlagen. Darauf könnt Ihr stolz sein.\n\nIch werde Euch ein Zeichen meiner Wertschätzung geben, aber lasst es Euch nicht zu Kopf steigen. Ihr habt immer noch keine Ahnung davon, was es bedeutet, ein Mok'Nathal zu sein. Vielleicht werden wir immer noch auf Eure Fähigkeiten zurückkommen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10846] = { id = 10846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verständnis für die Mok'Nathal", description = "<Leoroxx schaut Euch mit einem Blick an, der Euch das Blut in den Adern gefrieren lässt.>\n\nIhr kommt zu den Mok'Nathal, aber Ihr versteht uns nicht. Ihr versteht unseren Kampf um Leben oder Tod nicht.\n\nWenn Ihr uns verstehen wollt, müsst Ihr Euch diesem Kampf aussetzen.\n\nIm Süden findet Ihr die Arakkoa der Vekh'nir. Sie halten eine Gruppe von Ogern in den Höhlen, die als Trogmas Besitz bekannt sind, als Sklaven. Dort findet Ihr auch ihren Anführer Vekh.\n\nTötet ihn!", sourceObjective = "Tötet Vekh, Anführer der Arakkoa der Vekh'nir.", completion = "Die Vekh'nir sind noch die harmlosesten unserer Feinde.\n\nIhr habt also einen übergroßen Vogel getötet. Das macht Euch noch lange nicht zu einem wahren Krieger. Das lässt Euch auch nicht unser Wesen verstehen.\n\nAber es ist ein Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[10847] = { id = 10847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Skettis", description = "Von den Klippen von Skettis zieht Unheil heraus.\n\nDas Schicksal meines Volkes, der Arakkoa, wird von einem unaussprechlichen Bösen verschleiert. Schon zu oft haben wir schwarze Magie für üble Taten eingesetzt. Durch A'dal erfuhren wir vom Licht und von der Erlösung.\n\nTerokk überwacht seine Kolonien von Skettis aus mithilfe von Sphären, die er mit seiner schwarzen Kunst verzaubert hat. Stehlt diese Augen aus dem Reskkversteck und dem Shienorversteck im nördlichen Terokkar. Ich möchte sehen können, was Terokk sieht. Lasst mich durch die Augen von Skettis schauen.", sourceObjective = "Bringt das Auge des Reskkverstecks und das Auge des Shienorverstecks zu Rilak dem Erlösten im unteren Viertel von Shattrath.", progress = "Ihr seid zurück, {class}. Welche Neuigkeiten bringt Ihr?", completion = "Euer Mut sollte belohnt werden. Die Wachen von Skettis rücken ihre Besitztümer nur ungern heraus.\n\nAber die Heldentaten der Vergangenheit sind nun nicht von Belang. Wir sollten uns lieber darum kümmern, dass dieser Heldenmut auch in der Zukunft weiter herrscht, denn Terokks Blick richtet sich gen Süden.\n\nDiese Augen sehen alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[10848] = { id = 10848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das untote Böse des Rhazeverstecks", description = "Das Rhazeversteck war eine besonders bösartige Kolonie von Skettis.\n\nTrotz der Auslöschung seiner Bewohner durch die Katastrophe von Auchindoun hielt Terokk seinen Einfluss auf die bösartigen Geister dort aufrecht. Reist nach Westen zum Rhazeversteck und tötet diese mörderischen Schufte. Ihr findet sie westlich des Schattengrabs, an der Grenze zwischen der Knochenwüste und den Wäldern von Terokkar.\n\nDies wird unser erster Schlag gegen Terokk und die Wächter von Skettis werden.", sourceObjective = "Tötet 4 Todeskrallengeister, 4 kreischende Geister und 2 Geistraben und kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane zurück.", completion = "Diese verderbten Geister haben es verdient zu sterben. Der Tod, den sie über alle anderen gebracht hätten, ist dafür Grund genug.\n\nEs besteht keine Hoffnung, dass wir die, die unter Terokks Einfluss stehen, erlösen können. Aber wir werden ihnen im Namen des Lichts ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10849] = { id = 10849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Kirrik", description = "Es waren noch andere Arakkoa an dem Verrat an Terokk beteiligt.\n\nKirrik erkannte in Terokk einen Scharlatan und keinen Propheten. Die einzige Prophezeiung, die Terokk vorausgesehen hat, war das Verderben, das auf seinen eigenen Wunsch heraufbeschworen wurde.\n\nEs war Kirrik, der uns mutig aus Skettis herausgeführt hat. Nach unserer Pilgerreise nach Shattrath ging Kirrik in alle anderen Kolonien, um nach Gleichgesinnten zu suchen.\n\nIn diesem Schreiben steht, was die Augen gesehen haben. Kirrik muss davon erfahren! Folgt der Straße nach Süden aus Shattrath hinaus zu der Knochenwüste und haltet nach der Karawane Ausschau.", sourceObjective = "Bringt Rilaks Schreiben zu Kirrik den Erwachten bei der Flüchtlingskarawane in der Knochenwüste.", progress = "Ihr seid weit gereist und bringt mir Nachrichten.", completion = "Rilaks Geschichte ist grausam, Reisender. Wie Ihr am Zustand der Karawane sehen könnt, gibt es dieser Tage viel Leid und Düsterkeit in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10850] = { id = 10850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethergas in einem Teufelsfeuermotor", progress = "Ihr findet die Öffnung, durch die der Teufelshäscher betankt wird.", completion = "Als Ihr den falschen Treibstoff einfüllt, beginnt der Motor des Teufelshäschers zu rumpeln und zu stottern." }
quests[10851] = { id = 10851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Totems meines Feindes", description = "Es gibt solche Wege, die Ahnen zu ehren, und es gibt andere Wege.\n\nDie Oger der Speerspießer tragen Totems bei sich, aber sie benutzten sie nicht, um ihre Ehrfurcht auszudrücken. Stattdessen wollen sie damit manipulieren und kontrollieren.\n\nWir sollten ihre Totems stehlen, denn sie sind unwürdig! Wir werden eine bessere Verwendung für sie finden.\n\nGeht zum Außenposten der Speerspießer im Westen, südwestlich des Messergrats. Erschlagt die Mystiker und Zermalmer der Speerspießer und nehmt ihnen die Totems ab!", sourceObjective = "Sammelt 5 Totems der Speerspießer.", progress = "Wart Ihr im Außenposten der Speerspießer und habt ihnen die Totems abgenommen?", completion = "Das sieht nach einer guten Sammlung aus. Wir sollten einen Weg finden können, sie respektvoll einzusetzen.\n\nIn der Tat habe ich sogar schon eine Idee!", sourceObjectiveStatus = "unverified-source-field" }
quests[10852] = { id = 10852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Freunde", description = "Wir haben uns hier niedergelassen, weil des Nachts ein paar Kerle kamen und Radau gemacht haben. Es war gruselig. Ich weiß nicht, wann wir weitergehen werden.\n\nEinige meiner Freunde fehlen. Ich habe keine Ahnung, wo sie sind. Ich fürchte, diese schauerlichen Vogelmänner haben sie mit nach Nordwesten genommen. Wahrscheinlich haben sie sie in Käfige eingesperrt und all so was. Es wäre toll, wenn Ihr sie finden könntet. Ich mache mir Sorgen um sie.", sourceObjective = "Ethan möchte, dass Ihr 12 seiner vermissten Freunde im Skithversteck findet und sie zu ihm bei der Flüchtlingskarawane zurückbringt.", completion = "Ihr habt all meine Freunde gefunden! Jetzt habe ich wieder jemanden, der mit mir spielt. Vielen Dank, Herr {name}.\n\nDa ich jetzt wieder andere Kinder zum Spielen habe, könnt Ihr ja eins meiner Spielzeuge haben. Dann habt Ihr auch etwas zum Spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10853] = { id = 10853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisteranrufung", description = "Die Geister der Netherdrachen im singenden Bergrücken müssen befreit werden.\n\nDie Netherdrachen waren nicht immer Netherdrachen. Einst waren sie schwarze Drachen.\n\nDoch dann schwappte mit der Zerstörung dieser Welt eine Welle von Netherenergie über alles und veränderte die Eier der Drachlinge.\n\nSeitdem ist ihr eigenes Ich verzerrt. Wir müssen ihnen helfen, Frieden zu finden.\n\nDas erreicht Ihr, indem Ihr einen Drachen in der Nähe des Totems der Geisteranrufung tötet und ihm dann seine Seele nehmt.", sourceObjective = "Benutzt das Totem der Geisteranrufung, um 8 Geister eines geringen Netherdrachen zu sammeln.", progress = "Die Drachen des singenden Bergrückens sind vielleicht eine Bedrohung für uns, doch sie sind majestätische Wesen.\n\nOder sie waren es zumindest. Ich hoffe, dass Ihr ihre Geister retten könnt.\n\nUnd falls Ihr noch mehr Totems brauchen solltet, habe ich noch ein paar über.", completion = "Ihr habt heute eine große Tat vollbracht, {class}. Die Geister der Drachen werden nun wieder singen können, denn sie sind frei. Und die Überreste ihrer Geister, die sie hinterlassen, dienen als mächtiges Heilmittel.\n\nHabt Ihr vielleicht Lust auf eine Reise in den Norden? Es gibt da eine Sache im Zusammenhang mit den Astralen, die mich brennend interessiert.\n\nIch fühle großen Schmerz aus dieser Richtung kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10854] = { id = 10854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht Neltharakus", description = "Nehmt diesen verzauberten Netherrankenkristall und begebt Euch zurück zur Festung des Drachenmals. Sucht nach den versklavten Drachen, wenn Ihr angekommen seid, und setzt die Magie des Kristalls frei. Meine eigenen Energien werden dafür sorgen, dass die Drachen ihre Fesseln abwerfen können. Wenn Ihr seht, dass ein Drache freigekommen ist, helft ihm schnell seinen Kerkermeister zu vernichten! Sie sind von der Gefangenschaft sicherlich noch geschwächt.\n\nLasst alle frei, die Ihr finden könnt und kehrt dann zu mir zurück, {name}!", sourceObjective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 5 versklavte Drachen der Netherschwingen befreit.", progress = "Verschwendet keine Zeit, wir haben viel zu tun!", completion = "<Neltharaku lacht.>\n\nDie Orcs müssen einen ganz schönen Schreck bekommen haben, als die Drachen sich plötzlich gegen sie gewendet haben. Gut gemacht, {name}. Vielleicht seid Ihr wirklich der Held unseres Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[10855] = { id = 10855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelshäscher, nein Danke!", description = "Ah ja, der Teufelshäscher! Das ist sicherlich die schrecklichste mechanische Erfindung der Legion. Und nicht weniger als drei dieser Abscheulichkeiten sind direkt auf die Sturmsäule gerichtet.\n\nZu unserem Glück sind sie noch nicht aktiviert. Das gibt uns die Möglichkeit, dieses Problem mit Sabotage anstatt mit roher Gewalt zu lösen.\n\nBeschafft Euch kondensiertes Nethergas von den Gan'arg in der Konstruktionsbasis: Vergessenheit und füllt es in den Tank eines Teufelshäschers. Ich glaube, sein Motor wird sich nicht allzu sehr darüber freuen.", sourceObjective = "Beschafft Euch 5 Einheiten kondensiertes Nethergas von den Robogenieuren der Gan'arg in der Konstruktionsbasis: Vergessenheit und füllt sie in einen deaktivierten Teufelshäscher. Kehrt danach zu Netherpirscher Nauthis zurück.", completion = "Das sind ausgezeichnete Nachrichten, {name}. Jetzt, da wir wissen, wie wir mit ihnen zu verfahren haben, kann ich ein paar Leute anheuern, um die übrigen Häscher zu sabotieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10856] = { id = 10856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beste Verteidigung", description = "Mutige Industriesabotage wird uns leider nur bis zu einem gewissen Punkt weiterbringen, {name}. Genauso wie die Konstruktionsbasis: Vergessenheit als Produktionsstätte für die Teufelshäscher dient, ist die Konstruktionsbasis: Gehenna sowohl ein Stützpunkt für ihre Armee, als auch der Ort, an dem sich die meisten Teleporter der Legion befinden.\n\nIch möchte, dass Ihr dorthin geht, und ihre Zahl tüchtig verringert. Bis heute müssen sie ein volles Regiment von Zornschaffern angesammelt haben. Das dürfen wir nicht zulassen!", sourceObjective = "Netherpirscher Nauthis möchte, dass Ihr 12 Zornschaffer in der Konstruktionsbasis: Gehenna nördlich der Sturmsäule vernichtet.", completion = "Gute Arbeit, {name}. Macht weiter so, dann werde ich beim Nexusprinzen ein gutes Wort für Euch einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10857] = { id = 10857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teleportiert das!", description = "So lustig es auch sein mag, Dämonen zu töten, so wenig hilft es uns, wenn die Legion weiterhin ihre Teleporter benutzen kann, um jeden Dämon, den wir töten, zu ersetzen.\n\nUnglücklicherweise habe ich gerade keinen hochwertigen Sprengstoff zur Hand... aber die Mo'arg, die die Teleporter warten, schon!\n\nNehmt diesen Stab... Ich habe seine Kraft so eingestellt, dass er die Gehirnströme der Mo'arg beeinflussen kann. Kehrt zur Konstruktionsbasis: Gehenna zurück und beeinflusst jeden Mo'arg, den Ihr seht. Viel Zeit bleibt Euch nicht, aber sie wird reichen, um ihre Sprengladungen bei den Teleportern in der Nähe zu benutzen.", sourceObjective = "Netherpirscher Nauthis möchte, dass Ihr den Stab der geistigen Beeinflussung bei den Mo'arg in der Konstruktionsbasis: Gehenna einsetzt und ihre Fähigkeit 'Teleporter sprengen' bei den drei Teleportern in der Konstruktionsbasis benutzt.", progress = "Ist es vollbracht? Sind die Teleporter außer Gefecht?", completion = "Dank Euch kann ich wieder etwas durchatmen, {name}. Das meine ich natürlich im übertragenen Sinne!\n\nIch nehme an, Ihr wollt nun eine Art Belohnung, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[10858] = { id = 10858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karynaku", description = "Ich schäme mich, Euch erneut um Hilfe zu bitten, {name}, aber Ihr seid die einzige Hoffnung meines Schwarms. Ohne mein Weibchen stirbt die Brut der Netherschwingen vielleicht ganz aus!\n\nMacht Euch auf den Weg zur Spitze der Festung des Drachenmals und findet Karynaku.\n\nWir werden über Euch fliegen. Sollte sich ein Loch in ihrer Verteidigung auftun, wird die geballte Macht der Netherschwingen Euch zur Hilfe eilen.", sourceObjective = "Sucht nach Karynaku in der Festung des Drachenmals.", completion = "Es sind die Ketten. Sie berauben mich meiner Macht. Der einzige Ausweg ist, den Schlüssel von Zuluhed zu beschaffen und mich loszuketten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10859] = { id = 10859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt die Kugeln", description = "Die Astralen der Razaani haben merkwürdige Geräte, aus denen kleine, rosafarbene schwebende Lichtkugeln herauskommen. Sie erinnern mich an Seelen.\n\nMan darf sie nicht mit den großen gelben Kugeln verwechseln, die sich aus den Astralen lösen, wenn sie sterben. Diese hier sind ganz anders.\n\nIch möchte, dass Ihr nach Norden zu Razaans Landeplatz geht und ein paar Totems aufstellt, die die rosafarbenen Lichtkugeln anziehen.\n\nBringt sie zu mir zurück, damit ich genau herausfinden kann, aus was sie bestehen.", sourceObjective = "Benutzt das Kugelfängertotem, um 15 Lichtkugeln der Razaani zu sammeln.", progress = "Habt Ihr alle Lichtkugeln der Razaani, die ich brauche, gesammelt?", completion = "Etwas fühlt sich hier falsch an.\n\nBitte, {name}, reicht mir das Totem. Ich muss diese Kugeln untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10860] = { id = 10860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckerbissen der Mok'Nathal", description = "Seid Ihr hungrig, {race}? Der große Geist hilft denen, die sich selbst helfen. Wenn Ihr Euch ein Essen verdienen wollt, schlage ich vor, dass Ihr zuhört, denn Braagor da drüben wird Euch nichts umsonst geben, zumindest nichts, was so schmackhaft wäre.\n\nDie Raptoren und Schuppenflügel der Messergrats und der Schuppenflügelbank haben alles, was man für zwei der schmackhaftesten Gerichte, die Ihr je zu essen bekommen werdet, braucht. Bringt mir ihre Raptorenrippchen das Schlangenfleisch, und ich werde Euch beide zubereiten.\n\nIch kann Euch auch beibringen, sie selbst zu kochen, wenn Ihr in Eile seid.", sourceObjective = "Sammelt 3 Raptorenrippchen und 3 Stück Schlangenfleisch.", progress = "Habt Ihr alle Zutaten schon? Darüber zu reden hat mir das Wasser im Munde zusammenlaufen lassen!", completion = "Mmm, ich kann sie schon schmecken! Schnell, reicht mir die Zutaten... Ich werde sie rasch klein würfeln und dann ab damit aufs Feuer!\n\nZu Eurem Glück hält sich das Zeug lange, und ich meine damit sehr lange! So, nehmt dies. Und da Ihr so freundlich wart, meine Speisekammer aufzufüllen, gebe ich Euch die Rezepte gleich noch dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[10861] = { id = 10861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Präventivschlag gegen das Lithicversteck", description = "In der verachtungswürdigen Kolonie im Südwesten, die als Lithicversteck bekannt ist, versuchen die Diener Terokks ihre geflügelten Brüder schon vor dem Schlüpfen zu verderben. Die schwarzen Zauberer von Lithic belegen die Eier mit einem schattenhaften Fluch. Wenn die Küken schlüpfen, sind sie bereits willenlose Diener Terokks.\n\nReist ins Lithicversteck und zerbrecht die Eier, bevor der Fluch wirken kann. Sogar wenn es dazu schon zu spät ist, könnt Ihr die verderbten Eier vernichten.\n\nDenkt daran, in der Dunkelheit strahlt das Licht noch heller.", sourceObjective = "Zerbrecht die verfluchten Eier im Lithicversteck. Erlöst 3 Jungtiere und tötet 3 bösartige Jungtiere. Kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane zurück.", completion = "Es ist eine grausame Aufgabe, Jungtiere zu quälen, und doch wäre es unverzeihlich, das wachsende Böse zu ignorieren. Ihr habt gute Arbeit geleistet. A'dals Gunst leuchtet auf Euch herab.", sourceObjectiveStatus = "unverified-source-field" }
quests[10862] = { id = 10862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslieferung an die Horde", description = "Die feigen Arakkoa greifen uns täglich an. Sie lauern unseren Jägern auf und plündern ab und an sogar innerhalb unserer Stadtmauern! Wir töten sie, wenn wir können, aber ihre Magie ist stark und sie schaffen es oft, unseren Truppen zu entkommen.\n\nIch habe erfahren, dass einige Arakkoa der Horde gegenüber freundlich gesonnen sein sollen. Sie leben in Shattrath im Nordwesten. Ihr Anführer nennt sich Rilak der Erlöste. Sucht im unteren Viertel nach ihm und fordert ihn auf, sich auszuliefern.", sourceObjective = "Rokag möchte, dass Ihr Rilak den Erlösten im unteren Viertel von Shattrath aufsucht und von ihm fordert, dass er und sein Volk sich der Horde ausliefern.", completion = "Euer Volk ist wütend, aber ich kann nicht viel dagegen tun. Einige von uns wurden von der Macht der Naaru berührt und für alle Zeiten verändert. Doch diejenigen von uns, die in der Wildnis leben, sind noch immer so, wie wir damals waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10863] = { id = 10863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Arakkoa", description = "Hier an der Front müssen wir uns Tag für Tag mit den Arakkoa herumschlagen. Sie greifen uns an, wenn es ihnen gerade passt, plündern unsere Vorräte und erschlagen unsere Späher.\n\nUnd doch wissen wir nur wenig über diese rätselhaften Kreaturen. Ich habe Informationen erhalten, denen zufolge in Shattrath im Nordwesten einige Arakkoa leben sollen, die nicht so feindselig sind und vielleicht die Geheimnisse ihres Volks mit uns zu teilen bereit sind.\n\nRilak der Erlöste ist ihr Anführer. Er lebt im Norden des unteren Viertels.", sourceObjective = "Lady Dena Kennedy möchte, dass Ihr Rilak den Erlösten im unteren Viertel von Shattrath aufsucht und herausfindet, welche Geheimnisse der Arakkoa mit Euch teilen wird.", completion = "Es war sehr weise von Euch, mich aufzusuchen. Es gibt vieles, was ich Euch zeigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10864] = { id = 10864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Last auf der Seele", description = "Ich habe ein Gerät, mit dem man Teufelsmagie analysieren kann, der dämonische Seher. Ich würde Euch den Seher ja benutzen lassen, aber zunächst müsst Ihr ihn... besänftigen. Ihr müsst wissen, dass innerhalb des Sehers ein Wesen von höchster Intelligenz steckt, das einige, sagen wir, exzentrische Bedürfnisse hat.\n\nUm den Seher zu besänftigen, müsst Ihr Orcs töten, insbesondere die Orcs der Zerschmetterten Hand. Der Seher verlangt ihre Seelen.\n\nKehrt zu mir zurück, wenn Ihr die Seelen geerntet habt. Ihr findet die Orcs nördlich, südlich und um die Höllenfeuerzitadelle herum.", sourceObjective = "Tötet 20 Orcs der Zerschmetterten Hand und kehrt danach zu Apotheker Antonivich in Thrallmar zurück.", progress = "Der dämonische Seher ist noch nicht besänftigt, {name}. Kehrt zu mir zurück, nachdem Ihr die Seelen der Orcs der Zerschmetterten Hand geerntet habt.", completion = "Gut gemacht, {name}. Eure Seele ist mit vielen Toden belastet... und der dämonische Seher wird nun seine Pflicht für Euch erfüllen.\n\nWollen wir hoffen, dass Ihr für das Folgende gewappnet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10865] = { id = 10865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informiert Leoroxx!", description = "Schnell, Ihr müsst Leoroxx über die Geschehnisse bei Razaans Landeplatz informieren.\n\nDiese Kugeln wurden aus Seelen geschaffen, einige davon Seelen der Mok'Nathal!", sourceObjective = "Sprecht mit Leoroxx darüber, was die Astralen der Razaani treiben. Ihr findet ihn im Dorf der Mok'Nathal im Schergrat.", completion = "Ist das, was Ihr da sagt, überhaupt möglich? Was sage ich da? Natürlich ist es das, wenn der Geistrufer davon überzeugt ist.\n\nErinnert Ihr Euch noch, als ich sagte, dass wir vielleicht wieder Eure Hilfe brauchen würden? Wie es scheint, kann ich in die Zukunft sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10866] = { id = 10866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed der Geschlagene", description = "Er versteckt sich in meinen Gedanken, <Sterblicher/Sterbliche>. Er wartet darauf, dass ich zerbreche... mich seinem Willen unterwerfe.\n\nUnd das wird sein Untergang sein. Ich werde ihn rufen. Ich werde ihm sagen, dass ich tue, was er verlangt. Wenn er erscheint, müsst Ihr ihn töten und den Schlüssel nehmen!\n\nSeid gewarnt: Zuluhed ist ein uralter Orc mit ungeahnten Kräften. Sicher hat Illidan seine Macht noch weiter verstärkt. Ihr riskiert Euer Leben, wenn Ihr tut, worum ich euch bitte. Seid Ihr sicher, dass Ihr ein solches Opfer bringen wollt?", sourceObjective = "Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien.", progress = "<Karynaku brüllt.>", completion = "Ich bin frei! Ihr habt uns gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10867] = { id = 10867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann nur eine Antwort geben", description = "Es kann nur eine Antwort auf diese... diese SCHÄNDUNG der Seelen unserer Vorfahren geben!\n\n{name}, wenn Ihr uns helfen wollt, die Seelen unserer verehrten Toten zu ihrem richtigen Platz zurück zu bringen, dann kehrt zu Razaans Landeplatz zurück.\n\nGeht dorthin zurück und tötet die Razaani bis ihr Anführer, Nexusprinz Razaan, sein feiges Gesicht zeigt. Tötet ihn, beschafft Euch die Seelen zurück und übergebt sie Geistrufer Dohgar!", sourceObjective = "Beschafft Euch die Seelensammlung.", progress = "Habt Ihr es getan? Sind die Seelen unserer Vorfahren sicher vom Bösen der Astralen?", completion = "Es ist gut, dass der Abschaum der Astralen und ihr Anführer tot sind. Ich wünsche ihren Brüdern tausend Plagen auf den Hals!\n\nIhr sollt für Eure Taten im Namen aller Mok'Nathal belohnt werden, {name}! Ihr seid wirklich ein Held für uns!\n\nLasst uns nun die Seelen unserer Vorfahren dem reinigenden Feuer übergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10868] = { id = 10868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegspfad der Arakkoa", description = "Die Arakkoa haben uns erneut angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt um zu entkommen, bevor wir losstürmen und ihnen Auge in Auge entgegentreten konnten. Sie benutzen ihre Beschwörungskreise, um ihre Krieger von dem sicheren Tod zu retten, aber wenn wir ihr Zuhause angreifen, können sie uns nicht entkommen. Das Reskkversteck und das Shienorversteck liegen im Norden und Nordosten.\n\nSucht diese Nester der Arakkoa und tötet so viele, wie Ihr könnt.", sourceObjective = "Beraterin Faila bittet Euch, 14 Krallaniere der Shienor und 6 Zauberer der Shienor zu töten. Kehrt danach zu ihr in der Steinbrecherfeste zurück.", completion = "Gut gemacht, {class}. Die Arakkoa haben gelernt, die Macht der Horde zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10869] = { id = 10869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herde ausdünnen", description = "Die Arakkoa haben uns erneut angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt um zu entkommen, bevor wir unsere Soldaten losschicken konnten.\n\nDas Reskkversteck und das Shienorversteck liegen im Norden und Nordwesten. Sucht diese Nester der Arakkoa und tötet so viele, wie Ihr könnt. Vielleicht fürchten sie uns nicht, aber wir können ihre Zahl dennoch verringern!", sourceObjective = "Leutnant Kieshammer bittet Euch, 14 Krallaniere der Shienor und 6 Zauberer der Shienor zu töten. Kehrt danach zu ihm in Allerias Feste zurück.", completion = "Gut gemacht, {class}. Die Arakkoa haben gelernt, die Macht der Allianz zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10870] = { id = 10870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündeter der Netherschwingen", description = "Erlaubt mir, Euch zu Mordenai zurück zu bringen. Ich bin mir sicher, dass er Euch nochmals sehen möchte.", sourceObjective = "Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen.", completion = "Ihr habt Euch als Verbündeter der Netherschwingen erwiesen. Meine Mutter ist frei und meine Brüder und Schwestern gerettet!\n\nVielleicht werde ich Euch eines Tages erneut rufen. Wenn dieser Tag kommt, werdet Ihr mit offenen Armen begrüßt werden, als Bruder des Drachenschwarms der Netherschwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10871] = { id = 10871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündeter der Netherschwingen", description = "Erlaubt mir, euch zu Mordenai zurück zu bringen. Ich bin mir sicher, dass er Euch nochmals sehen möchte.", sourceObjective = "Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen.", completion = "Ihr habt Euch als Verbündeter der Netherschwingen erwiesen. Meine Mutter ist frei und meine Brüder und Schwestern gerettet!\n\nVielleicht werde ich Euch eines Tages erneut rufen. Wenn dieser Tag kommt, werdet Ihr mit offenen Armen begrüßt werden, als Bruder des Drachenschwarms der Netherschwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10872] = { id = 10872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed der Geschlagene", description = "Er versteckt sich in meinen Gedanken, <Sterblicher/Sterbliche>. Er wartet darauf, dass ich zerbreche... mich seinem Willen unterwerfe.\n\nUnd das wird sein Untergang sein. Ich werde ihn rufen. Ich werde ihm sagen, dass ich tue, was er verlangt. Wenn er erscheint, müsst Ihr ihn töten und den Schlüssel nehmen!\n\nSeid gewarnt: Zuluhed ist ein uralter Orc mit ungeahnten Kräften. Sicher hat Illidan seine Macht noch weiter verstärkt. Ihr riskiert Euer Leben, wenn Ihr tut, worum ich euch bitte. Seid Ihr sicher, dass Ihr ein solches Opfer bringen wollt?", sourceObjective = "Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien.", completion = "Ich bin frei! Ihr habt uns gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10873] = { id = 10873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Nacht verschleppt", description = "Unser kleiner Außenposten wird ständig angegriffen. Vor ein paar Nächten haben die Spinnen des Netherweberkamms, der am südöstlichen Ende der Knochenwüste liegt, unser Lager überfallen. Sie haben viele von uns vergiftet, in ihre Netze gewickelt und fort getragen. Einige unserer Krieger haben zu den Waffen gegriffen und sind den Spinnen todesmutig in die finstere Nacht gefolgt.\n\nWir haben weder die Gefangenen noch die Krieger seit diesem Tag wieder gesehen. Wir hoffen, dass sie noch am Leben sind. Vielleicht halten die Spinnen sie gefangen? Wir sind nur so wenige. Könnt Ihr nach unseren Leuten suchen?", sourceObjective = "Späher Navrin möchte, dass Ihr zum Netherweberkamm reist und 6 eingesponnene Verteidiger der Sha'tar befreit. Kehrt danach zu Navrin ins Basislager der Sha'tari zurück.", completion = "Ihr habt so viele gerettet. Ich habe nicht geglaubt, dass wir sie je wieder sehen würden. Wir können Euch nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10874] = { id = 10874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signalfeuer des Shalasverstecks", description = "Über der Knochenwüste im Osten wirft Skettis, der lange Arm Terokks, bedrohlich seine Schatten. Am Fuße von Skettis liegt das Shalasversteck, Terokks vortrefflichste Kolonie. Von diesem Stützpunkt aus führen Terokks Diener Krieg gegen das Licht.\n\nDie Unholde der Shalas kommunizieren über ein komplexes System aus magischen Signalfeuern mit ihrem Meister. Reist nach Osten, {race}, und löscht die Feuer. Sobald das Shalasversteck zum Schweigen gebracht wurde, können wir den Fall von Skettis planen.\n\nAber ich greife mir selbst vor.", sourceObjective = "Kirrik der Erwachte bei der Flüchtlingskarawane möchte, dass Ihr die vier Signalfeuer des Shalasverstecks löscht.", completion = "Wir haben gesehen, wie der verfluchte Rauch aufgestiegen ist. Ihr seid außergewöhnlich mutig, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10875] = { id = 10875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Nazgrel", description = "{name}, während Eures Auftrags mit dem dämonischen Seher habe ich einen Bericht über Eure Taten gegen die Höllenorcs geschickt. Nazgrel, unser berühmter Anführer in Thrallmar, möchte mit Euch sprechen. Ich glaube, er hat einen blutigen Auftrag für Euch...", sourceObjective = "Sprecht mit Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", completion = "Es ist schön, von Euren Schachzügen gegen die Höllenorcs zu erfahren, {name}. Die Apotheker haben viel Zeit und viel Mühe aufgewendet, um hinter den Grund der Verderbnis zu kommen, und auch wenn diese Informationen sicher unersetzlich sind... schreit mein Orcblut danach, diesen Verrätern einen anständigen Schlag zu verpassen!\n\nHört genau zu, wenn ich Euch Eure Aufgabe erkläre...", sourceObjectiveStatus = "unverified-source-field" }
quests[10876] = { id = 10876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Fuße der Zitadelle", description = "Truppenkommandant Gorax trainiert die Hauptmänner am Fuß der Höllenfeuerzitadelle und drillt sie, bis sie so scharf wie Rasierklingen sind. Ihr müsst ihn töten, {name}. Sein Verlust wäre ein großer Schaden für die Höllenorcs.\n\nDas ist jedoch nicht alles, was Ihr tun müsst.\n\nNehmt dieses Banner. Platziert es auf Gorax' Leichnam. Wenn auch nur ein Tropfen echtes Orcblut in seinem Körper steckt, muss sein Kommandant, die Hand von Kargath, Eure Herausforderung annehmen!\n\nSein Kopf, der Kopf der Hand von Kargath, ist das, was ich begehre.", sourceObjective = "Tötet Truppenkommandant Gorax, platziert die Herausforderung der Horde auf seinem Leichnam. Tötet danach die Hand von Kargath und bringt den Kopf der Hand von Kargath zu Nazgrel in Thrallmar.", progress = "Habt Ihr Euch der Hand von Kargath gestellt, {name}?", completion = "Ihr habt eine große Tat geleistet, {name}. Die Höllenorcs sind eine Schande für alle wahren Orcs. Wenn wir eine Angst haben, so ist es die, erneut einer dämonischen Verderbnis zu verfallen. Unser Krieg gegen die Höllenorcs ist also mehr als nur eine Schlacht gegen schlimme Feinde, es ist eine Schlacht in uns selbst.\n\nUnd mit einer Stärke, wie Ihr sie heute bewiesen habt, werden wir diese Schlacht gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10877] = { id = 10877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schreckensrelikt", description = "Vor langer Zeit machte sich eine Karawane auf den Weg nach Auchindoun mit der Mission, ein Schreckensrelikt aus den uralten Gräbern unter der Stadt der Toten zu bergen. Sie sind geflohen, aber das Relikt sollte ihr Untergang sein. Das Relikt ist böse und ruft Böses herbei, wenn es berührt wird. Ihre Karawane wurde irgendwo im Osten vernichtet.\n\nDieses finstere Artefakt ist der Schlüssel zu meinem schrecklichen Plan, Teribus den Verfluchten zu töten, eine Kreatur, die über der Knochenwüste ihre Kreise zieht. Wenn Ihr wünscht, könnt Ihr mir helfen, aber Euer Leben und Eure Seele stehen dabei auf dem Spiel.", sourceObjective = "Oakun möchte, dass Ihr nach Osten zur herrenlosen Karawane reist und das Schreckensrelikt besorgt. Kehrt zu Oakun zurück, wenn Eure Aufgabe erledigt ist.", progress = "Habt Ihr das Schreckensrelikt? Wir müssen es bekommen.", completion = "Es ist unglaublich, dass Ihr es geschafft habt. Das Schreckensrelikt ist viel mächtiger, als ich befürchtet hatte. Nur ein starker Held hätte die lange Rückreise mit so einem blasphemischen Gegenstand überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10878] = { id = 10878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevor die Dunkelheit sich senkt", description = "Nachdem unsere Karawane einem Angriff von Kultisten der Kabale des Schattenrats zum Opfer gefallen ist, wurden Späher auf der Suche nach Hilfe nach Shattrath geschickt. Die Wachen denken, wir sind vorerst sicher, aber sie unterschätzen diese Verrückten.\n\nIch freue mich jedenfalls nicht darauf, mir meine Kehle von irgendeinem Initianden der Kabale mitten in der Nacht durchschneiden zu lassen. Tut uns allen einen Gefallen und greift sie an, bevor sie es tun.\n\nIhr findet unsere Angreifer südlich von hier, am nördlichen Eingang von Auchindoun.", sourceObjective = "Mekeda bei der Flüchtlingskarawane möchte, dass Ihr 8 Scharmützler der Kabale, 4 Zauberwirker der Kabale und 2 Initianden der Kabale tötet.", completion = "Vorerst kann ich erleichtert durchatmen, {name}. Der Schattenrat wird sich bis auf weiteres zurückhalten.\n\nSie sind Mörder und Feiglinge. Eure Zurschaustellung von Mut wird sie einschüchtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10879] = { id = 10879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensive aus Skettis", description = "Skettis hat uns den Krieg erklärt! Habt Ihr genug Hilfe für die Verteidigung Shattraths gesammelt?\n\nHaltet die Angreifer auf!", sourceObjective = "Haltet die Angreifer auf und sprecht mit Rilak den Erlösten.", progress = "Wir haben jetzt keine Zeit für einen Plausch, {name}. Wir werden angegriffen! Haltet die Eindringlinge auf!", completion = "Ich ziehe meinen Hut vor Euren Kampfkünsten, {class}. Ihr habt Euch als wahrer Verteidiger des Lichts bewiesen. Möge A'dals Segen in Euren dunkelsten Stunden auf Euch ruhen.\n\nDoch seht zum fernen Horizont. Dunkle Wolken ziehen unheilvoll über Skettis herauf. Sicher plant Terokk schon seinen nächsten Schachzug. Für heute ist Shattrath gerettet. Doch wer weiß schon, welch Verderben der nächste Tag über uns alle bringen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10880] = { id = 10880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle der Kabale", description = "Die Botschaft trägt ein dunkles Siegel. Auch wenn Euch die Sprache bekannt vorkommt, scheint der Text verschlüsselt zu sein.\n\nVielleicht weiß jemand bei der Flüchtlingskarawane etwas darüber.", sourceObjective = "Bringt die Befehle der Kabale zu Mekeda bei der Flüchtlingskarawane in der Knochenwüste.", progress = "Wollt Ihr mir etwas zeigen, {name}?", completion = "Ah, ja... dieser Text wurde in einer einfachen Form der Geheimschrift der Schatten geschrieben. Mein Wissen darüber ist nicht perfekt, aber es sollte ausreichen, um sie zu übersetzen.\n\nMan kann viel von den zwielichtigen Gestalten lernen, wenn man unter den Ausgestoßenen und Flüchtlingen im unteren Viertel lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10881] = { id = 10881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattengrab", description = "Viele glauben, dass der Schattenrat die Explosion, die Auchindoun in tausend Stücke gerissen hat, verursacht hat. Gerüchten zufolge sollen sie im Inneren ein großes Übel erweckt haben.\n\nWenn das stimmt, muss dieses Böse sich gegen sie gewandt haben. Laut diesen Befehlen flieht ein Teil des Schattenrats aus Auchindoun. Sie benutzen das Schattengrab, um mächtige Artefakte aus Auchindoun zu lagern.\n\nDrei dieser Artefakte sind heilig, denn sie gehörten den mächtigen Patriarchen Arunen, K'alen und Atalor. Ich muss Euch bitten, sie wieder zu holen.", sourceObjective = "Geht in das Schattengrab westlich der Flüchtlingskarawane und beschafft Euch Arunens Tuch, K'alens Hammer und Atalors Schriftrolle. Kehrt danach zu Mekeda bei der Flüchtlingskarawane zurück.", progress = "Habt Ihr die Relikte, {name}? Wir können nicht zulassen, dass der Schattenrat sie für seine dunklen Zwecke einsetzt.", completion = "Das Licht hat mich vielleicht vergessen, aber ich habe das Licht nicht vergessen. Diese Relikte waren meinem Volk einst sehr heilig.\n\nDem Schattenrat zu erlauben, sie für Böses einzusetzen ist... undenkbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10882] = { id = 10882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herold der Verdammnis", description = "<Ein Missklang ertönt in A'dals 'Stimme'.>\n\nPrinz Kael'thas hat seine Wärter schlampig ausgewählt, und nun brechen die Wesenheiten, die in der Arkatraz eingesperrt waren, aus.\n\nBesonders eine davon, ein Diener der alten Götter, der als Herold Horizontiss bekannt ist, versucht, die Vision seines Meisters von der Eroberung aller Welten in diesem Universum in die Tat umzusetzen.\n\n{name}, Ihr dürft nicht zulassen, dass er entkommt. Kehrt zur Festung der Stürme zurück und begebt Euch in die Arkatraz. Tötet Herold Horizontiss, bevor es zu spät ist!", sourceObjective = "Ihr wurdet beauftragt, zur Arkatraz in der Festung der Stürme zu reisen und Herold Horizontiss zu töten. Kehrt danach zu A'dal auf der Terrasse des Lichts in Shattrath zurück.", completion = "<Das kristallene Klingen von A'dals Stimme fließt in einer deutlich ruhigeren Melodie als die letzten beiden Male, in denen Ihr miteinander gesprochen habt.>\n\nWieder einmal habt Ihr Euren Eifer bewiesen. Wenn Herold Horizontiss ausgebrochen wäre, wären Tausende dem Konflikt zum Opfer gefallen, genauso, wie es bei einem anderen Diener der alten Götter, Skeram, auf Eurer Welt Azeroth geschehen ist.\n\n{name}, was ich Euch als Belohnung anbiete, scheint im Vergleich erbärmlich zu sein, aber seid Euch bewusst, dass die ewige Dankbarkeit der Sha'tar damit verbunden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10883] = { id = 10883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel der Stürme", description = "Ihr habt Euch in großen Taten bewiesen, {name}. Eure Entdeckung der Litanei der Verdammnis und Kael'thas' Rolle dabei sind für unsere Sache von äußerster Wichtigkeit. Sollte Kael'thas die Litanei benutzen, würde der kleine Rest, der noch von dieser Welt übrig ist, in sich zusammenfallen.\n\nA'dal ist davon überzeugt, dass Kael aufgehalten werden muss und ist nun auf der Suche nach Abenteurern, die sich seinen Prüfungen unterziehen möchten. Die Naaru werden denjenigen, die ihre Stärke beweisen, ihre Gunst gewähren.\n\n<Khadgar nickt.>\n\nA'dal erwartet Euch...", sourceObjective = "Sprecht mit A'dal in Shattrath.", completion = "Die Festung der Stürme ist eine Erfindung der Naaru, Sterblicher. Zutritt zu der Festung zu gewähren lag schon immer alleine im Ermessen der Naaru. Eine Rückkehr zur Festung der Stürme erschien uns jedoch unnötig. Vielleicht mag das für ein sterbliches Volk wie Stolz aussehen, doch wir Naaru halten nur wenig von solchen Dingen.\n\nWir gehen nun, weil wir es müssen. Kael'thas darf die Litanei der Verdammnis niemals vorlesen.\n\nAuch wenn der Weg offen steht, so würde sich nur ein Narr unerprobt hineinwagen. Unterschätzt nicht den Zweck der Prüfungen, Sterblicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[10884] = { id = 10884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Erbarmen", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle werden drei Leute Eures Volkes von dem erbarmungslosen Kargath Messerfaust gefangen gehalten. Er hat vor, sie als Zeichen seiner Männlichkeit und Stärke hinzurichten. Ihr müsst diese Gefangenen retten, bevor eine solche Grausamkeit geschehen kann. Bringt mir die unbenutzte Axt des Henkers als Beweis Eurer Tat. Es darf kein einziger Tropfen Blut an der Klinge sein!", sourceObjective = "A'dal in Shattrath möchte, dass Ihr die unbenutzte Axt des Henkers aus den Zerschmetterten Hallen der Höllenfeuerzitadelle besorgt.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "<A'dal grüßt Euch.>", completion = "Gut gemacht, {name}. Ihr habt die Prüfung des Erbarmens abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10885] = { id = 10885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Stärke", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nDie Prüfung der Stärke besteht aus zwei Teilen. Ihr müsst den Anführer der Dampfkammern des Echsenkessels, Kriegsherr Kalithresh, töten und mir seinen Dreizack bringen. Außerdem müsst Ihr das außerdimensionale Wesen Murmur im Schattenlabyrinth in Auchindoun erlegen und mir seine Essenz bringen.\n\nWenn Ihr dies geschafft habt, habt Ihr die Prüfung der Stärke bestanden.", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Kalithreshs Dreizack und Murmurs Essenz besorgt.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "<A'dal grüßt Euch.>", completion = "Gut gemacht, {name}. Ihr habt die Prüfung der Stärke abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10886] = { id = 10886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Zuverlässigkeit", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nAuf unseren Reisen haben wir viele gefährliche Wesen getroffen. Einige dieser Wesen wurden eingefangen und werden nun an Bord der Arkatraz in der Festung der Stürme gefangen gehalten.\n\nEiner der Gefangenen ist jedoch Opfer eines unglücklichen Zufalls. Er war zur falschen Zeit als blinder Passagier auf dem falschen Schiff der Naaru unterwegs.\n\nReist zur Arkatraz und rettet den Gnom Millhaus Manasturm. Stellt sicher, dass er überlebt.", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Millhaus Manasturm aus der Arkatraz in der Festung der Stürme rettet.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", completion = "Gut gemacht, {name}. Ihr habt die Prüfung der Zuverlässigkeit abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10887] = { id = 10887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus dem Grab", description = "Ich weiß Eure Hilfe zu schätzen, {name}. Ich war mir sicher, dass ich sterben würde.\n\nLasst uns schnell von hier verschwinden. Bald werden uns noch mehr Kultisten auf den Fersen sein.", sourceObjective = "Helft Akuno zur Flüchtlingskarawane zu gelangen. Sprecht danach mit Mekeda.", completion = "Ihr habt Akuno, meinen geschätzten Freund, errettet. Dafür stehe ich in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10888] = { id = 10888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Magtheridon", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft Euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", progress = "<A'dal grüßt Euch.>", completion = "Ihr habt Euch als Wesen mit großer Macht bewiesen. Die Naaru sind sich einig...", sourceObjectiveStatus = "unverified-source-field" }
quests[10889] = { id = 10889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Shattrath", description = "Auch wenn Eure Taten sehr mutig waren, wird Terokk sicher nicht lange auf seine Rache warten lassen.\n\nGeht schnell nach Shattrath! Verständigt Rilak!", sourceObjective = "Reist nach Shattrath und Sprecht mit Rilak den Erlösten im unteren Viertel.", completion = "Die Wachen von Skettis werden langsam unruhig. Shattrath steckt in Schwierigkeiten. Wir werden Terokks Rache sicher eiskalt zu schmecken bekommen.\n\nStellt schnell eine Verteidigung auf die Beine! Sprecht mit Verteidiger Grashna und lasst ihn wissen, dass Ihr bereit seid, die Waffen gegen unsere Angreifer zu erheben!", sourceObjectiveStatus = "unverified-source-field" }
quests[10891] = { id = 10891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenrüstung", description = "In Gadgetzan gibt es einen Zwerg namens Derotain Matschnipper der Euch beibringen kann, wie man eine imperiale Brustplatte herstellt. Ihr müsst nur nach Tanaris reisen und ihn suchen. Interesse?", sourceObjective = "Sprecht Derotain Matschnipper in Gadgetzan in Tanaris.", completion = "Natürlich bringe ich Euch bei, wie man eine imperiale Plattenrüstung herstellt! Es wird Euch allerdings ein wenig Gold kosten... in Form von Thoriumbarren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10892] = { id = 10892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenrüstung", description = "In Gadgetzan gibt es einen Zwerg namens Derotain Matschnipper der Euch beibringen kann, wie man eine imperiale Brustplatte herstellt. Ihr müsst nur nach Tanaris reisen und ihn suchen. Interesse?", sourceObjective = "Sprecht Derotain Matschnipper in Gadgetzan in Tanaris.", completion = "Natürlich bringe ich Euch bei, wie man eine imperiale Plattenrüstung herstellt! Es wird Euch allerdings ein wenig Gold kosten... in Form von Thoriumbarren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10893] = { id = 10893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langschweif ist der springende Punkt", description = "Da die Wyrmkultisten der Pechschwingen sich im Tunnel sammeln, sehen wir uns gezwungen, der Lage Herr zu werden. Ehrlich gesagt sind sie deutlich in der Überzahl.\n\nAuch wenn wir bisher diejenigen, die uns zu nahe gekommen sind, zurückhalten konnten, wären wir einem ernsthaften Angriff von ihnen nicht gewachsen.\n\nDie Lage erfordert, dass jemand sich bis an das andere Ende des Tunnels durchkämpft und ihre Anführerin, Draaca Langschweif, unschädlich macht. Habt Ihr Lust auf ein wenig Spaß?", sourceObjective = "Tötet Draaca Langschweif, die Anführerin der Wyrmkultisten im Tunnel des Wyrmschädels.", progress = "Ist sie tot?\n\n{name}, wenn wir auch nur die leiseste Chance gegen sie haben wollen, müsst Ihr Verwirrung unter ihren Rängen säen, indem Ihr Draaca Langschweif tötet!", completion = "Nun, da Draaca unschädlich gemacht wurde, sollten wir in der Lage sein, unseren Vorteil aus der Situation zu ziehen. Sie werden sich jetzt untereinander darum streiten, wer die Leitung übernehmen soll, und das wird uns viel Druck nehmen.\n\nEs sei denn der Aufseher aus dieser Einladung, die Ihr mir gegeben habt, nimmt ihren Platz ein.\n\nWir sollten sicherstellen, dass das niemals passieren wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[10894] = { id = 10894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behüter des Wyrmschädels", description = "Hm, ich weiß nicht so recht, was wir tun sollen. Ich bin nicht gerade ein Militärstratege.\n\nBehüter Mondschatten weiß sicher, was zu tun ist. Er kümmert sich um unsere Verteidigung beim Tunnel des Wyrmschädels im Westen, am Ende der Brücke des Wyrmschädels. Wir unterhalten dort eine Streitmacht, falls die Kultisten zu übermütig werden.\n\nBitte, bringt ihm so schnell wie möglich diese Nachricht.", sourceObjective = "Bringt die Einladung zum Treffen zu Behüter Mondschatten beim Eingang des Tunnels des Wyrmschädels im Schergrat.", progress = "Wie kann ich Euch helfen? Bringt Ihr Nachrichten aus dem ewigen Hain?", completion = "Es ist genau so, wie ich es befürchtet habe, und das ist nicht gut!\n\nIch habe schon eine Idee, wie ich Euch helfen kann, aber vielleicht könnt zunächst Ihr uns helfen?\n\nEine Hand wäscht die andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[10895] = { id = 10895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor muss brennen!", description = "Es ist an der Zeit, Zeth'Gor aus der Luft anzugreifen! Unsere Greifenreiter sind bereit für einen kleinen Ausflug, {name}. Aber wir brauchen jemanden, der vom Boden aus ihre Angriffe lenkt. Seid Ihr bereit für einen kleinen Geheimauftrag?\n\nBringt diese Rauchsignale nach Zeth'Gor, dem Stützpunkt des Blutenden Auges im Westen. Dort befinden sich vier Wachtürme: einer in der Nähe der nördlichen Mauer, einer in der Nähe der südlichen Mauer, einer in der Nähe der Schmiede und einen in den Hügeln. Platziert ein Rauchsignal unter jedem Turm und wir werden sie bombardieren!", sourceObjective = "Benutzt das Rauchsignal unter jedem Wachturm in Zeth'Gor und kehrt danach zu Schwadronskommandant Dabir'ee beim Expeditionsposten zurück.", progress = "Die Zeit drängt, {name}. Wir müssen diese Wachtürme anzünden!", completion = "Ich konnte von hier aus den Rauch und die Flammen sehen! Gute Arbeit, {name}! Ihr verdient mehr als nur ein paar Lobesworte von unseren Greifenreiter. Was Ihr da getan habt, erfordert eine gehörige Portion Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[10896] = { id = 10896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verseuchten Beschützer", description = "Die Macht, die von Auchindoun freigesetzt wurde, hat verheerende Auswirkungen auf die Bäume dieses Landes. Die verderbte Magie, die dort entfesselt wurde, hat das Land in diese Wüste verwandelt, die Ihr nun hier überall sehen könnt. Die Bäume, die überlebt haben, sind nun von schädlichen Baummilben befallen, die unter ihre Rinde kriechen und ihr Holz anfressen.\n\nFaulende Waldwüter und befallene Wurzelwandler sind ein idealer Nährboden für die Milben. Man kann sie am östlichen Waldrand finden. Vernichtet diese Kreaturen und tötet dann die Milben, die aus ihrer Hülle fliehen.", sourceObjective = "Lakotae möchte, dass Ihr 25 Baummilben tötet und danach zu ihm bei der Flüchtlingskarawane zurückkehrt. Ihr findet die Milben in den Körpern der faulenden Waldwüter und befallenen Wurzelwandler.", completion = "Ihr habt viel zur Rettung der Wälder von Terokkar beigetragen, {name}. Jetzt, da die schlimmsten Milbenkolonien vernichtet sind, können wir vielleicht dieses öde Land zurückerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10897] = { id = 10897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Tränke", description = "Wie Ihr sicher wisst verfügen die Pflanzen über Eigenschaften, mit deren Hilfe Alchemisten über Tränke andere stärken und verjüngen können.\n\nMein Wissen über die Pflanzen in der Scherbenwelt ermöglicht mir, Alchemisten beizubringen, wie sie das Beste aus ihnen herausholen können. Wenn Ihr Euer Wissen über Tränke vertiefen möchtet, müsst Ihr nur eine kleine Aufgabe für mich erledigen.\n\nHochbotaniker Freywinn in der Festung der Stürme soll angeblich einen ausführlichen Botanikführer geschrieben haben. Bringt ihn zusammen mit ein paar Proben Eurer Arbeit zu mir und ich werde Euch das Wissen lehren, das Ihr wünscht.", sourceObjective = "Lauranna Thar'well möchte, dass Ihr die Botanika der Festung der Stürme betretet und den Naturführer der Botanika von Hochbotaniker Freywinn besorgt. Zusätzlich möchte sie, dass Ihr ihr 5 erstklassige Heiltränke, 5 erstklassige Manatränke und 5 erhebliche Tränke des traumlosen Schlafs bringt.\n\nACHTUNG! Ihr könnt nur eine Alchimiespezialisierung wählen.", progress = "Seid Ihr Euch sicher, {name}? Wenn Ihr Euch in der Kunst der Tränke spezialisiert, werdet Ihr keine weiteren Spezialisierungen erlernen können.", completion = "Ausgezeichnet! Wie es aussieht, seid Ihr begierig darauf zu lernen, also lasst uns beginnen. Ich werde Euch beibringen, wie Ihr das Beste aus den Pflanzen für Eure alchimistischen Tränke herausholt.\n\nIhr werdet sehen, dass ganz schön viel in den Kräutern steckt, wenn man weiß, was man zu tun hat. Manchmal kann man sogar zwei Tränke mit den Materialien für einen herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10898] = { id = 10898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolkenschwinge", description = "Wolkenschwinge flattert um Euch herum.\n\nEurer Einschätzung nach möchte er, dass Ihr ihm folgt.", sourceObjective = "Begleitet Wolkenschwinge und meldet Euch dann bei Rilak dem Erlösten in Shattrath.", completion = "Also stand der arme Wolkenschwinge unter dem schrecklichen Fluch von Luanga dem Kerkermeister!\n\nWolkenschwinge hatte sich auf den Weg ins Shalasversteck gemacht, um zu versuchen, die anderen auf den Weg des Lichts zu bringen. Sie haben seine Versuche nicht gerade positiv aufgenommen, vor allem nicht, da sie direkt am Fuße von Skettis liegen.\n\nLuanga war einer von Terokks gefürchtetsten Dienern. Es war gut von Euch Wolkenschwinge zu befreien! Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10899] = { id = 10899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Transmutation", description = "Jeder Alchemist kann Euch erklären, dass Materie formbar ist und jede Substanz in eine andere verwandelt werden kann. Jedoch wird dabei nichts wirklich erschaffen oder zerstört.\n\nEin wahrer Meister der Transmutation kann lernen, diese Grenzen zu überwinden. Und ich kann Euch zeigen, wie man dies erreichen kann!\n\nAls angehender Transmutierer seid Ihr sicher mit der Urmacht vertraut, der Verbindung der Materialien aller Urkräfte. Beweist mir Euer Können in der Kunst der Transmutation. Dann werde ich mein Wissen mit Euch teilen.", sourceObjective = "Zarevhi in der Sturmsäule im Nethersturm möchte, dass Ihr ihm 4 Einheiten Urmacht bringt.\n\nACHTUNG! Ihr könnt nur eine Alchimiespezialisierung wählen.", progress = "Seid Ihr sicher, dass Ihr ein Meistertransmutierer werden wollt? Wenn Ihr Euch auf diesem Gebiet spezialisiert, werdet Ihr Euch nicht auf Tränke oder Elixiere spezialisieren können.", completion = "Ausgezeichnete Arbeit, {name}! Diese Transmutationen sind in jeder Hinsicht perfekt!\n\nIch werde Euch nun beibringen, wie man mit Hilfe der alchimistischen Transmutation Materie aus dem Nichts erschaffen kann! Nutzt Euer Wissen weise, Meistertransmutierer.\n\nWenn Ihr mich nun entschuldigen möchtet, ich muss einen Kunden aufsuchen, der an Urmacht interessiert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10900] = { id = 10900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal von Vashj", sourceObjective = "Brennt es nieder, {race}! Brennt alles nieder! Sie haben nichts verdient. Habt Ihr mich verstanden? NICHTS! Sie müssen für ihre Taten bezahlen. Auch für ihre zukünftigen.\n\nIch würde Vashj selbst töten, wenn ich von diesen verdammten Fesseln frei wäre.\n\nOder wollt Ihr vielleicht Neptulons Arbeit erledigen? Ihr Tod ist uns beiden dienlich, Weichhaut. Werdet Ihr mir dabei helfen, den heiligen Knüppel herzustellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10901] = { id = 10901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Knüppel von Kar'desh", description = "Bringt mir die Elementarsiegel, die ich für den Knüppel brauche!\n\nDas Erdensiegel befindet sich im Besitz von Gruul dem Drachenschlächter. Ihr findet ihn in seinem Unterschlupf im Schergrat.\n\nDas zweite Siegel ist das flammende Herz einer Kreatur, die als Schrecken der Nacht bekannt ist. Diese mystische Kreatur soll sich angeblich in den geheiligten Hallen des Propheten Medivh aufhalten.\n\nBeeilt Euch!", sourceObjective = "Nar'biss der Ketzer in den heroischen Sklavenunterkünften des Echsenkessels möchte, dass Ihr ihm das Erdensiegel und das Flammensiegel bringt.", progress = "Mit dem Knüppel werde ich meine Fesseln lösen können und zum Schlangenschrein zurückkehren, um meine Rache an Vashj und ihren Dienern zu üben!", completion = "Endlich!\n\nMit gelösten Fesseln und dem Knüppel in meinem Besitz werde ich diese Meereshexe wieder zurück in die eisigen Tiefen senden...", sourceObjectiveStatus = "unverified-source-field" }
quests[10902] = { id = 10902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Elixiere", description = "Ich habe mein Leben der Perfektion meiner Elixiere gewidmet. Trotz meines Erfolgs habe ich es nie geschafft, ein Elixier des ewigen Lebens herzustellen.\n\nIch glaube zu wissen, welche Reagenz mir fehlt. Ich habe von einem Ort in Azeroth gehört, der die Höhlen der Zeit genannt wird. Die Eindringlinge dort, Fürsten der Zeitenrisse genannt, und die Bewahrerinnen der Zeitrisse können auf den Zeitlinien hin- und herspringen.\n\nDurch diesen Wechsel in der Zeit entstehen Risse, die sich in alle Ewigkeit ziehen und zu unendlicher Essenz kristallisieren. Bringt mir diese Essenz zusammen mit Proben Eures handwerklichen Könnens und ich werde Euch alles beibringen, was ich weiß.", sourceObjective = "Begebt Euch in den Schwarzen Morast in den Höhlen der Zeit und besorgt 10 Essenzen der Unendlichkeit von den Fürsten der Zeitenrisse und den Bewahrerinnen der Zeitenrisse. Bringt die Essenzen zusammen mit 5 Elixieren der erheblichen Verteidigung, 5 Elixieren des Meisters und 5 Elixieren der erheblichen Beweglichkeit zu Lorokeem im unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie wählen!", progress = "Die Essenzen! Habt Ihr sie?", completion = "Ihr versteht Euch auf Elixiere, wenn man diesen hier glauben mag. Ihr werdet ein guter Schüler sein.\n\nDiese Essenzen werden ausreichen, um mein Rezept zu entwickeln. Für diese Entdeckung werde ich Berühmtheit unter allen Alchimisten erlangen!\n\nWenn Ihr nun bereit seid zu lernen, bin ich bereit zu lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10903] = { id = 10903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Ehrenfeste", description = "{name}, während Ihr mit Eurem Auftrag in Zeth'Gor beschäftigt wart, habe ich Nachricht von meinem befehlshabenden Offizier, Oberst Jules erhalten. Er wurde während des Kampfes beim Außenposten von Gor'gaz von einer dämonischen Verderbnis befallen. Sein Zustand wird immer schlechter.\n\nIhr habt so viele große Erfolge gegen die Höllenorcs erzielt. Eure Kraft in der Schlacht steht außer Frage... ist Euer Geist auch so stark?\n\nBitte, kehrt zur Ehrenfeste zurück und sprecht mit Klatu. Er befindet sich in einem Raum über dem Gasthaus der Ehrenfeste.", sourceObjective = "Sprecht mit Gehilfe Klatu im Gasthaus der Ehrenfeste.", completion = "Ja, es ist wahr. Oberst Jules' Zustand hat sich in den letzten Tagen stark verschlechtert. Anachoret Barada betet schon die ganze Zeit für ihn... Wir hoffen, dass er geheilt werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10904] = { id = 10904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsmunition", description = "Wir müssen der Brennenden Legion den Zugang zu Schwelle des Todes versperren, aber zunächst müsst Ihr die beiden Warptore zerstören!\n\nDas Problem ist, dass wir diesen Dingern nicht einmal einen Kratzer zufügen können, daher müsst Ihr ihre eigenen Waffen gegen sie verwenden.\n\nDie Mächte des Todes, die Augen des Todes, die Oberschmiede der Todesschmiede und die Techniker der Todesschmiede tragen die Munition für die Teufelskanonen bei sich.\n\nNormalerweise kann diese Munition ihnen nichts anhaben, aber wenn Ihr die Kanonenkugeln zu mir bringt, werde ich sie mit dem unbändigen Zorn der Natur erfüllen!", sourceObjective = "Beschafft Euch 5 Teufelskanonenkugeln.", progress = "Habt Ihr die Kanonenkugeln schon?", completion = "Diese Dinger stinken ja schlimmer, als ich dachte!\n\nSchnell, gebt sie mir, damit ich die mit der Macht der Natur erfüllen kann. Dann werden sie zu tödlichen Waffen gegen die teuflischen Meister und ihre unnatürlichen Schöpfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10905] = { id = 10905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Tränke", description = "Mein Wissen über die Alchemie ist sehr groß. Jedoch ist es eher allgemein gehalten. Wenn Ihr Euch spezialisieren möchtet, müsst Ihr Euch an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\n\nWenn Ihr Euch auf die Herstellung von Tränken spezialisieren möchtet, empfehle ich Euch, Lauranna Thar'well von der Expedition des Cenarius aufzusuchen.\n\nIhr Wissen über die Pflanzen wird Euch dabei helfen, das Beste aus Euren Rohmaterialien herauszuholen. Sucht sie in den Zangarmarschen auf und sagt ihr, dass ich Euch geschickt habe.", sourceObjective = "Sprecht mit Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie erlernen.", completion = "Ihr wollt, dass ich Euch bei Euren Studien der Tränke helfe? Nun gut, {name}. Wollen wir mal schauen, was wir da machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10906] = { id = 10906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Elixiere", description = "Mein Wissen über die Alchemie ist sehr groß. Jedoch ist es eher allgemein gehalten. Wenn Ihr Euch spezialisieren möchtet, müsst Ihr Euch an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\n\nWenn Ihr Euch auf die Herstellung von Elixieren spezialisieren möchtet, empfehle ich Euch, den Arakkoa namens Lorokeem um Hilfe zu bitten.\n\nSein Wissen über Elixiere sucht seinesgleichen, und doch verschwendet er sein Können darauf, ein Elixier des ewigen Lebens zu brauen. Sucht nach ihm und schaut, was er Euch beibringen kann.", sourceObjective = "Sprecht mit Lorokeem im unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie erlernen.", completion = "Ihr wollt von mir lernen? Hmmm, ja. Vielleicht seid Ihr ja ein geeigneter Schüler.", sourceObjectiveStatus = "unverified-source-field" }
quests[10907] = { id = 10907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Transmutation", description = "Mein Wissen über die Alchemie ist sehr groß. Jedoch ist es eher allgemein gehalten. Wenn Ihr Euch spezialisieren möchtet, müsst Ihr Euch an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\n\nWenn Ihr Euch in der Kunst der Transmutation spezialisieren möchtet, empfehle ich Euch, den Astralen namens Zarevhi um Hilfe zu bitten. Er lebt in der Sturmsäule im Nethersturm.\n\nSeine Beherrschung der Transmutation ist... nun, exotisch! Seht nach, was Ihr von ihm lernen könnt. Aber seid vorsichtig: Astrale sind hartnäckige Verhandlungspartner.", sourceObjective = "Sprecht mit Zarevhi in der Sturmsäule im Nethersturm.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie erlernen.", completion = "Ihr wollt, dass ich Euch bei Euren Studien der Transmutation helfe? Nun gut, {name}. Wollen wir mal schauen, was wir da machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10908] = { id = 10908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Rilak dem Erlösten", description = "Ihr seht überrascht aus, dass ich mit Euch rede. Ich mache Euch keinen Vorwurf. Mein Volk, die Arakkoa, verdienen Euren Argwohn.\n\nSprecht mit Rilak dem Erlösten in Shattrath, wenn Ihr mehr erfahren wollt. Er hält sich im nördlichen Teil des unteren Viertels bei den anderen Ausgestoßenen der Skettis auf.\n\nUnd {name}, wir werden voneinander hören.", sourceObjective = "Kirrik der Erwachte möchte, dass Ihr mit Rilak dem Erlösten im unteren Viertel von Shattrath sprecht.", completion = "So treffen wir uns also, {name}. Bitte vergebt mir meine fehlenden Manieren, aber die Zeit drängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10909] = { id = 10909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllengeister", description = "Oberst Jules wurde in einer Schlacht in der Nähe des Außenpostens von Gor'gaz, einer der Lieblingsorte der Höllenorcs der Zerschmetterten Hand, verflucht. Mein Meister Barada versucht verzweifelt, den armen Menschen zu heilen, aber er braucht Hilfe. Der verwirrte Geist des Oberst sucht nach Frieden, und ich fürchte, dass ein Teil des Weges dazu der Weg der Rache ist.\n\nBringt dieses Relikt des Anachoreten zum Außenposten von Gor'gaz. Stellt es in der Nähe der Orcs der Zerschmetterten Hand auf und besiegt sie. Das wird ihre Höllengeister freisetzen. Ihr müsst die Höllengeister töten, damit Jules Geist sich erholen kann.", sourceObjective = "Klatu in der Ehrenfeste möchte, dass Ihr das Relikt des Anachoreten beim Außenposten von Gor'gaz benutzt, die Orcs der Zerschmetterten Hand in der Nähe des Relikts tötet und dann 10 freigesetzte Höllengeister vernichtet, um Oberst Jules zu rächen.", progress = "Die Höllengeister der Orcs der Zerschmetterten Hand sind für Jules arme Seele eine Schmach. Sagt mir, {name}... habt Ihr ihn gerächt?", completion = "Die Orcs der Zerschmetterten Hand sind verderbt und nicht mehr zu retten. Und dennoch erfüllt es mein Herz mit Traurigkeit, dass die Rettung von Oberst Jules ein solches Blutvergießen erfordert.", sourceObjectiveStatus = "unverified-source-field" }
quests[10910] = { id = 10910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwelle des Todes", description = "Wir haben von einer sogar noch größeren Bedrohung durch die Legion erfahren. Im Süden befindet sich ein Portal, dass als Schwelle des Todes bekannt ist. Es ist die Tür zu einer entsetzlichen Welt, in der die Legion ihre verschiedenen Hunderassen züchtet.\n\nUm dorthin zu gelangen, müsst Ihr den ewigen Hain Richtung Osten verlassen und den Pfad hinauf gehen. Folgt dem Weg nach Süden durch die Messerschlucht, an Razaans Landeplatz vorbei durch den Messergrat und über die Schuppenflügelbank. Nehmt dann den Pfad hinab nach Vekhaar und betretet die Schwelle des Todes durch den Tunnel südlich des Dorfs der Mok'Nathal.\n\nBenutzt dieses Druidensignal, sobald Ihr angekommen seid.", sourceObjective = "Benutzt das Druidensignal bei der Schwelle des Todes, um einen Druiden des ewigen Hains zu rufen und mit ihm zu sprechen.\n\nBereitgestellter Gegenstand:", completion = "Ich bin sehr erleichtert, dass Wildfürst Antelarion Euch zu uns geschickt hat. Das Problem ist noch viel schlimmer, als wir befürchtet haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[10911] = { id = 10911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei!", description = "Jetzt, da unsere Munition der Brennenden Legion Schaden zufügen kann, ist es an der Zeit, dass Ihr sie benutzt.\n\nEs gibt zwei Warptore, die für die Teleportation und die Verbesserung der Schrecken der Leere benutzt werden. Eines befindet sich im Süden, das andere im Norden. Beide liegen in der Reichweite einer Teufelskanone.\n\nKämpft Euch bis zu den Teufelskanonen durch und benutzt die naturalisierte Munition, um die Kontrolle über die Kanonen zu erlangen und die Warptore zu zerstören.\n\nHütet Euch jedoch von den Verteidigern, die ausschwärmen werden, um die Kanone anzugreifen!", sourceObjective = "Verwendet die naturalisierte Munition, um die Kontrolle über die Teufelskanonen der Schwelle des Todes zu erlangen. Benutzt die Kanonen, um das südliche Warpportal und das nördliche Warpportal zu zerstören.", progress = "Habt Ihr beide Warpportale schon zerstört?", completion = "Euer Heldenmut ist beeindruckend!\n\nSehr gut. Nun, da die Warpportale außer Gefecht sind, bleibt nur noch eines zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10912] = { id = 10912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hundehetzer", description = "Baelmon der Hundehetzer muss sterben! Er ist es, der das Ritual vollzieht, mit dem das Portal aufrechterhalten wird!\n\nDas Portal der Schwelle des Todes befindet sich am nördlichen Ende der Schlucht. Wenn Ihr es gefunden habt, findet Ihr auch Baelmon.\n\nIhr werdet dabei Hilfe brauchen, also nehmt diesen Stab mit. Benutzt ihn, wenn Ihr gegen den Hundehetzer kämpft, und ein paar meiner Freunde werden Euch zur Hilfe eilen.\n\nKehrt zu Wildfürst Antelarion zurück, wenn Ihr Baelmon besiegt habt.\n\nUnd {name}, vielen Dank für alles, was Ihr unseretwegen auf Euch genommen habt.", sourceObjective = "Tötet den Hundehetzer.", progress = "Ist es vorbei? Ist die Gefahr an der Schwelle des Todes abgewendet?", completion = "Ihr seid wirklich ein ganz erstaunlicher {race}! Wenn ich schon zuvor dachte, dass wir in Eurer Schuld stehen, so gibt es nun einfach keinen Weg mehr, Euch je für Eure Taten zu danken.\n\nAber wir wollen es dennoch versuchen. Vielen Dank, Held des ewigen Hains!", sourceObjectiveStatus = "unverified-source-field" }
quests[10913] = { id = 10913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unangemessenes Begräbnis", description = "Gibt es nichts, was man gegen diese Flut der Verderbnis tun kann? Meine Soldaten kämpfen schon seit Tagen gegen die Auchenai und ein Ende ist nicht in Sicht. Jeder Gefallene, ob Sha'tar oder Auchenai, wird sofort vom Schlachtfeld gezerrt. Ihre Seelen werden geraubt und an unbekannte Orte gebracht.\n\nDas werde ich nicht zulassen! Ein angemessenes Begräbnis ist leider nicht möglich, aber diese Bestien werden ihre Seelen nicht bekommen! Nehmt diese Fackel und begebt Euch zum Schlachtfeld östlich von hier. Verbrennt jeden Leichnam, den Ihr finden könnt! Wir werden ihre Rituale nicht verstärken!", sourceObjective = "Kommandant Ra'vaj beim Außenposten der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr 8 getötete Kämpfer der Auchenai und 8 getötete Verteidiger der Sha'tar verbrennt.", progress = "Ich weiß, es ist eine grausame Aufgabe...", completion = "<Kommandant Ra'vaj schüttelt traurig den Kopf.>\n\nEs ist nicht genug... Es ist einfach nicht genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[10914] = { id = 10914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen einen Helden!", description = "Es reicht. Wir brauchen einen Helden. Unsere Streitkräfte können der immer wachsenden Zahl der Auchenai nicht mehr Herr werden.\n\n<Kommandant Ra'vaj schaut Euch an.>\n\nWollt Ihr <unser Held/unsere Heldin> sein? Kehrt zum Schlachtfeld zurück und greift ihre Soldaten an. Beschäftigt sie, damit meine Späher hinter die Linien gelangen und herausfinden können, was sie dort vorbereiten.", sourceObjective = "Kommandant Ra'vaj beim Außenposten der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr 12 Initianden der Auchenai und 5 Verdammnisverkünder der Auchenai tötet.", progress = "Keine Gefangenen!", completion = "Ihr habt es geschafft, {name}! Dank Euch konnten wir eine neue Entdeckung machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10915] = { id = 10915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefallene Exarch", description = "Sie verfüttern die Seelen, die sie gestohlen haben, an einen Sarg, den sie aus der Auchenaikrypta entwendet haben. Meine Späher glauben, dass sich der erste Exarch der Krypta in diesem Sarg befindet. Die Auchenai versuchen, ihn wieder zum Leben zu erwecken!\n\nIhr müsst Euch zur westlichen Seite von Auchindoun durchschlagen und den Inhalt des Sargs stören, bevor sie ihm genügend Seelen füttern konnten. Falls Ihr Euch verirren solltet, folgt einfach den wandelnden Seelen.\n\nWas auch immer sich in dem Sarg befinden mag - vernichtet es!", sourceObjective = "Kommandant Ra'vaj beim Außenposten der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr den Inhalt des Sargs der Auchenai vernichtet.", progress = "Ihr müsst dieses uralte Böse vernichten, bevor es seine Macht wiedererlangt.", completion = "Der Sieg ist unser! Diese Niederlage wird die Auchenai um mehrere Wochen zurückwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10916] = { id = 10916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Gebetsperlen graben", description = "Anachoret Barada hat vor, die Verderbnis aus Oberst Jules zu exorzieren und braucht dafür einen Gehilfen. So ein Gehilfe muss allerdings gut vorbereitet sein...\n\nIch schäme mich sehr, es zuzugeben, aber ich habe meine Gebetsperlen im Hof der Ehrenfeste verloren. Ich glaube, dass Fei-Fei der Hund sie gestohlen und verbuddelt hat, aber ich weiß nicht wo. Sprecht mit seiner Meisterin, Stabsfeldwebel Tracy Stolzbrunn. Vielleicht weiß sie, wo Fei-Fei seine gestohlenen Schätze aufbewahrt.", sourceObjective = "Sucht die Gebetsperlen der Draenei und bringt sie zu Gehilfe Klatu in der Ehrenfeste.", progress = "Habt ihr die Gebetsperlen schon gefunden, {name}? Ihre Macht ist für viele heilige Rituale unerlässlich... darunter auch für einen Exorzismus...", completion = "Ihr habt die Gebetsperlen gefunden! Gut gemacht, {name}. Ihr seid in der Tat ein Wunder. Im einen Moment erschlagt Ihr die Schrecken der Höllenfeuerhalbinsel, im anderen findet Ihr verlorene Schätze. Euer Volk ist wirklich sehr vielseitig!\n\nEs ist gut, dass Ihr diese Perlen gefunden habt... Sie sind für das folgende Exorzismusritual von äußerster Wichtigkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10917] = { id = 10917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht eines Ausgestoßenen", description = "Als Ausgestoßener werde ich von den Arakkoa, die der Stadt Skettis treu ergeben sind, als tot betrachtet. Ich kann diese Mauern aus Angst um mein Leben nicht verlassen. Aber das heißt noch lange nicht, dass ich mich nicht rächen kann.\n\nIch habe einen kleinen Schatz, den ich hergeben würde, wenn Ihr mir dabei helft, meine Möchtegernmörder zu erledigen. Bringt mir die Federn der Bewohner der verschiedenen Arakkoaverstecke von Terokkar als Beweis für ihr Ableben.", sourceObjective = "Bringt 30 Arakkoafedern zu Vekax im unteren Viertel von Shattrath.", progress = "Seid Ihr mit den Federn zurück, {name}?", completion = "<Vekax krächzt vor Freude, als Ihr ihm den Beweis für den Tod seiner Feinde übergebt.>\n\nJa, das wird Skettis zeigen, dass wir Ausgestoßenen ihre Bestrafung nicht lammfromm hinnehmen. Hier ist die Belohnung, die ich Euch versprochen habe. Ich kann Euch noch mehr geben, wenn Ihr mir weitere Federn bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10918] = { id = 10918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Federn", progress = "Die Schoßhunde von Skettis behalten uns Ausgestoßene immer noch genau im Auge. Sobald einer von uns es wagt, einen Fuß aus Shattrath zu setzen, sind wir so gut wie tot.\n\nBringt mir mehr Federn als Beweis für Euren Sieg über sie.", completion = "<Vekax krächzt vor Freude, als Ihr ihm den Beweis für den Tod seiner Feinde übergebt.>\n\nJa, das wird Skettis zeigen, dass wir Ausgestoßenen ihre Bestrafung nicht lammfromm hinnehmen. Hier ist die Belohnung, die ich Euch versprochen habe. Ich kann Euch noch mehr geben, wenn Ihr mir weitere Federn bringt.\n\n<Diese Quest kann wiederholt werden, bis Ihr den Ruf 'Wohlwollend' erlangt habt.>" }
quests[10919] = { id = 10919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fei-Feis Belohnung", progress = "Fei-Fei schaut Euch erwartungsvoll an...", completion = "<Fei-Fei bellt glücklich und schnappt sich das Hundeleckerli. Er schaut nach links und rechts um zu entscheiden, wo er seinen neuen Schatz vergraben soll...>" }
quests[10920] = { id = 10920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Gefallenen", description = "Als die Schreckenswitwen unseren Außenposten angegriffen haben, hörten wir die Stimme der Naaru, die uns in die Schlacht schickte. Wir verfolgten die Kreaturen bis in die tiefe Nacht hinein. Ein paar unserer Leute wurden in der Dunkelheit tot aufgefunden, andere hörten wir im verzweifelten Kampf gegen die Spinnen.\n\nDer Morgen zeigte uns, dass wir tapfer gekämpft und dennoch verloren hatten. Das Gift der Schreckensweber wird meine Kameraden bald dahinraffen, und auch ich werde nicht mehr lange durchhalten können. Doch bevor ich sterbe möchte ich die Gewissheit haben, dass die Schreckenswitwen geschlagen wurden.", sourceObjective = "Verteidiger Haylen möchte, dass Ihr 20 Schreckenswitwen tötet und danach zu ihm westlich des Netherweberkamms zurückkehrt.", progress = "Ich kann das Gift in meinen Adern spüren. Die Naaru rufen mich, ich sehe das Licht. Sind die Schreckenswitwen schon besiegt?", completion = "Ich habe die Geräusche Eures Kampfes bis hierher hören können, {class}. Der Klang Eures Sieges hat mein Herz mit Hoffnung erfüllt. Wenn Ihr gegen eine solch gewaltige Überzahl bestehen könnt, kann auch ich vielleicht noch die Kraft finden, um meine Kameraden von diesem schrecklichen Ort fort zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10921] = { id = 10921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokkarantula", description = "Ihr habt sehr viele Schreckenswitwen erschlagen, aber sie werden sich weiter vermehren und uns bald wieder angreifen. Tief im Netherweberkamm befindet sich das Nest von Terokkarantula, der Brutmutter dieser grausamen Kreaturen. Wenn wir in Sicherheit leben wollen, muss sie sterben.", sourceObjective = "Verteidiger Haylen möchte, dass Ihr Terokkarantula tötet und danach zu ihm westlich des Netherweberkamms zurückkehrt.", progress = "Ist Terokkarantula schon tot?", completion = "Die Schreckensspinnen wurden geschlagen. Ihr habt so viele von ihnen getötet und nun auch noch ihre verderbte Mutter erlegt. Meine Vergiftungen sind zu schwer, als dass ich mich zurück in die Freiheit kämpfen könnte.\n\nBitte, nehmt etwas von meiner Ausrüstung. Ich werde mein Bündel erleichtern und Euch die nötigen Werkzeuge geben, um heil zum Außenposten der Sha'tar zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10922] = { id = 10922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Knochen wühlen", description = "Heda! Ihr seht aus, als könntet Ihr gut auf Euch selbst aufpassen, {race}. Meine Truppe und ich hier sind auf der Suche nach einem Leibwächter, der auf uns aufpasst, während wir zu einer Ausgrabungsstätte im Norden gehen. Die Bezahlung ist ziemlich gut und Ihr müsst nur schauen, dass keine fiese Kreatur mich oder meine Angestellten tötet.\n\nWenn Ihr es heil zurückschafft ohne irgendwelche Todesopfer, wird Zwergowitz da drüben Euch bezahlen.", sourceObjective = "Begleitet Letoll und seine Truppe und beschützt sie, während sie ihre Ausgrabung durchführen. Kehrt danach zu Zwergowitz beim Außenposten der Sha'tari zurück.", completion = "Ein Knochenwurm! Fantastisch! Das könnte tatsächlich das erste Mal seit Beginn der Geschichtsschreibung sein, dass Letoll tatsächlich eine Entdeckung gemacht hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[10923] = { id = 10923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Böse rückt näher", description = "Jetzt müsst Ihr das Schreckensrelikt in einem bösartigen nekromantischen Ritual benutzen, um Teribus den Verfluchten herauszufordern. Im Nordosten, hinter Auchindoun, liegt der gequälte Hügel. An diesem Ort versammeln sich die Nekromanten.\n\nDie Todessprecher und Verdammnisverkünder der Auchenai tragen Verdammnisschädel bei sich, die mit mächtigen nekromantischen Verzauberungen belegt sind. Wenn Ihr genügend Schädel sammelt, könnt Ihr ihre Macht mit der des Schreckensrelikts vereinen und Teribus so befehlen, sich Euch zu stellen.", sourceObjective = "Oakun möchte, dass Ihr das Schreckensrelikt zum gequälten Hügel bringt. Tötet dort die Todessprecher und Verdammnisverkünder der Auchenai, um 20 Verdammnisschädel zu sammeln. Sucht danach den Beschwörungskreis des gequälten Hügels auf und benutzt das Schreckensrelikt, um Teribus den Verfluchten zu beschwören und zu vernichten. Kehrt zu Oakun zurück, wenn Ihr Eure Aufgabe erfüllt habt.", progress = "Habt Ihr Teribus den Verfluchten aus den Himmeln Terokkars vertrieben?", completion = "Terokkar wurde von einem schlimmen Übel befreit. Die Sha'tar stehen in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[10924] = { id = 10924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwichtelt und zugenäht!", description = "Das Blut der Sphärenhetzer in dieser Gegend ist eine sehr mächtige Reagenz und mein größter Verkaufsschlager.\n\nNormalerweise ziehe ich mit meinen Wichtel Zeppit los, um es zu sammeln. Es ist einfach viel zu ätzend, als dass Ihr es sammeln könntet, aber Zeppit kann es nichts anhaben.\n\nHier im Laden ist immer mehr los. Hättet Ihr daher etwas dagegen, wenn ich Euch Zeppit mitschicke, um etwas Blut zu sammeln? Zeppits Aufmerksamkeit neigt jedoch dazu abzuschweifen. Ihr müsst daher nahe an dem Hetzer stehen, wenn er gestorben ist, um sicherzugehen, dass Zeppit seine Arbeit erledigt.", sourceObjective = "Bringt 8 Phiolen Sphärenhetzerblut zu Sab'aoth in Kosmozang.", progress = "War Zeppit freundlich genug, das Blut für Euch zusammeln?", completion = "Das sollte genügend Vorrat für meine Zwecke sein.\n\nIch hoffe, der Wichtel hat Euch nicht allzu viel Ärger gemacht. Er hat manchmal Haare auf den Zähnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10925] = { id = 10925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Böse rückt näher" }
quests[10926] = { id = 10926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Basislager der Sha'tari", description = "Wir werden es nicht ohne Hilfe zurück schaffen. Das Gift der Schreckensweber ist zu stark. Ihr müsst für uns zum Basislager der Sha'tari gehen. Späher Navrin wird eine Rettungstruppe nach uns schicken.", sourceObjective = "Verteidiger Haylen möchte, dass Ihr zum Basislager der Sha'tari in die Knochenwüste zurückkehrt und mit Späher Navrin sprecht.", completion = "Es ist gut zu wissen, dass einige unserer Krieger tapfer gegen die Schreckenswitwen gekämpft und überlebt haben. Wir werden sofort eine Rettungstruppe nach ihnen schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10927] = { id = 10927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krabbler erschlagen", description = "Kommandant Himmelsschatten möchte, dass wir diesen Tunnel freiräumen, damit wir den Handel mit der Zuflucht beschleunigen können. Ich darf meinen Posten hier nicht verlassen, daher übertrage ich Euch diese Aufgabe. Räumt den Tunnel frei und meldet Euch dann sofort bei Kommandant Himmelsschatten!", sourceObjective = "Tötet 6 Höhlenkrabbler.", completion = "Gute Arbeit, {class}. Dieser Tunnel ist unsere direkte Verbindung zum Sumpf.", sourceObjectiveStatus = "unverified-source-field" }
quests[10928] = { id = 10928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krabbler erschlagen", description = "Tor'chunk Zweiklaue möchte, dass wir diesen Tunnel freiräumen, damit wir den Handel mit dem Sumpfrattenposten beschleunigen können. Ich darf meinen Posten hier nicht verlassen, daher übertrage ich Euch diese Aufgabe. Räumt den Tunnel frei und meldet Euch dann sofort bei Tor'chunk Zweiklaue!", sourceObjective = "Tötet 6 Höhlenkrabbler.", completion = "Gute Arbeit, {class}. Dieser Tunnel ist unsere direkte Verbindung zum Sumpf.", sourceObjectiveStatus = "unverified-source-field" }
quests[10929] = { id = 10929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stampfen", description = "Würdet Ihr gerne noch mehr Aufgaben für die Forscherliga erledigen? Wir alle hier finden diese Knochenwürmer ziemlich faszinierend.\n\nIch habe hier eine Trommel, die Ihr draußen in der Knochenwüste benutzen könnt. Schlagt sie einfach und schaut, was dabei herauskommt. Wenn es ein Wurm ist, dann tötet ihn und bringt uns den Kadaver, damit wir ihn untersuchen können. Wir werden eine ganze Menge an Kadavern brauchen, wenn wir ein repräsentatives Testergebnis erzielen wollen.", sourceObjective = "Zwergowitz beim Basislager der Sha'tari in der Knochenwüste möchte, dass Ihr ihm 8 Kadaver eines ausgewachsenen Knochenwühlers bringt.", progress = "Wir glauben, dass das, was wir bei den Ausgrabungen gefunden haben, tatsächlich nur ein Wurmkind war!", completion = "Sandgnome? Ja, klar... Die Wüste kann schon schlimme Dinge mit den Leuten anstellen.\n\nIch glaube, wir werden mit diesen Würmern hier einen wahren Durchbruch erzielen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10930] = { id = 10930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Knochenwurm", description = "Ich hatte Recht! Die Kadaver, die Ihr mir gebracht habt, stammen von Wurmkindern! Wisst Ihr, was das bedeutet? Das bedeutet, dass es irgendwo da draußen noch einen großen geben muss! Wenn wir ihm das richtige Futter anbieten, können wir ihn sicher hervorlocken. Mal überlegen... etwas Großes! Ja!\n\nIch erinnere mich daran, hier auf der anderen Seite der Knochenwüste ein paar Grollhufe gesehen zu haben. Geht dorthin und tötet einen von ihnen. Benutzt die Trommel, sobald Ihr ihn erlegt habt. Hoffentlich kommt der große Wurm dann heraus um zu fressen. Bringt mir seine Organe, wenn Ihr es schafft ihn zu töten!", sourceObjective = "Zwergowitz beim Basislager der Sha'tari in der Knochenwüste möchte, dass Ihr ihm riesige Knochenwurmorgane bringt.\n\nBringt auch den Stampfer zu ihm zurück.", progress = "Nehmt ein oder zwei Freunde mit!", completion = "Erstaunlich! Schaut Euch das an! Dieses Wasauchimmer hat eine Art Staub in seiner Wiemanesauchnennenmag. Aber ich will Euch nicht mit meinen wissenschaftlichen Fachbegriffen langweilen. Ich habe den kleineren Würmern ein paar Zähne gezogen und daraus diese unglaublich scharfen Messer gemacht. Wollt Ihr eins?", sourceObjectiveStatus = "unverified-source-field" }
quests[10931] = { id = 10931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Exodar", description = "Euer Meister Caedmos der Exodar wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.", sourceObjective = "Sprecht mit Caedmos in der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10932] = { id = 10932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Exodar", description = "Euer Meister Caedmos der Exodar wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.", sourceObjective = "Sprecht mit Caedmos in der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10933] = { id = 10933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Silbermond", description = "Euer Meister Aldrae in Silbermond wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.", sourceObjective = "Sprecht mit Aldrae in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[10934] = { id = 10934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Silbermond", description = "Euer Meister Aldrae in Silbermond wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.", sourceObjective = "Sprecht mit Aldrae in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[10935] = { id = 10935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Exorzismus des Oberst Jules", description = "{name}, es ist an der Zeit, Oberst Jules zu retten. Sein Zustand hat sich verschlechtert, und Barada fürchtet, dass wir ihm nicht mehr helfen können, wenn wir Ihn nicht bald von seiner Verderbnis heilen.\n\nNehmt die Gebetsperlen, die Ihr gefunden habt, und sprecht mit Anachoret Barada, um das Ritual zu beginnen. Lasst Euch dabei auf keinen Fall unterbrechen... und wenn alles gut geht, wird Oberst Jules gerettet sein. Sprecht mit Jules, wenn Ihr es geschafft habt, und kehrt danach zu mir zurück.", sourceObjective = "Sprecht mit Anachoret Barada. Benutzt die Gebetsperlen, um bei dem Ritual zu helfen und sprecht mit Oberst Jules, wenn er gerettet wurde. Kehrt danach zu Gehilfe Klatu zurück.", progress = "Geht zu Anachoret Barada, {name}. Er muss mit seinem Ritual Erfolg haben, wenn der Oberst gerettet werden soll.", completion = "Ihr habt es geschafft, {name}. Ihr habt Oberst Jules' Seele gerettet und die Dunkelheit in ihm vertrieben. Das ist eine großartige und selbstlose Tat! Die Tat eines Helden!", sourceObjectiveStatus = "unverified-source-field" }
quests[10936] = { id = 10936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollbann sucht Euch", description = "Während Ihr beschäftigt wart, kam ein Bote und hat in der Halle auf Euch gewartet. Ich nehme an, er hatte keine Lust mehr zu warten oder er hat beim Anblick von Jules, der hier durch den Raum schwebt, das Weite gesucht.\n\nWie auch immer, Truppenkommandant Danath sucht Euch. Ich schlage vor, dass Ihr ihn so schnell wie möglich in der Kaserne aufsucht!", sourceObjective = "Gehilfe Klatu hat Euch informiert, dass Truppenkommandant Danath Trollbann nach Euch sucht. Sprecht mit ihm in der Kaserne der Ehrenfeste auf der Höllenfeuerhalbinsel.", completion = "Das wird auch langsam Zeit! Ich habe davon erfahren, was Ihr und dieser Draeneipriester angestellt habt! Ihr habt meinen Boten völlig schockiert!\n\nJetzt, da Ihr damit fertig seid, habe ich einen kleinen Auftrag in der Höllenfeuerzitadelle für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10937] = { id = 10937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Züchtigung des Drillmeisters", description = "Ich erhalte Berichte, denen zufolge die Höllenorcs der Zerschmetterten Hand vor der Höllenfeuerzitadelle dabei sind, einen groß angelegten Angriff zu organisieren. Offensichtlich sind sie alles andere als glücklich über Eure Siege über all die anderen Klans.\n\nBegebt Euch zur Basis der Zitadelle am Ende des Pfads des Ruhmes. Dort werdet Ihr sehen, dass die Höllenorcs mitten in den Vorbereitungen stecken und sie eiskalt überraschen.\n\nVernichtet den Verantwortlichen der Truppe. Tötet Drillmeister Zurok!", sourceObjective = "Truppenkommandant Danath Trollbann befiehlt Euch, Drillmeister Zurok so schnell wie möglich zur Strecke zu bringen. Kehrt zu dem Truppenkommandanten in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück, wenn der Drillmeister tot ist.", completion = "Ich wollte es nicht glauben, bis ich es nicht von Euch persönlich gehört habe. Unsere Späher berichten uns jetzt schon, dass die Zerschmetterte Hand ohne ihren geschätzten Drillmeister, der ihnen sagt, was zu tun ist, völlig überfordert ist.\n\nIhr habt einen langen Weg zurückgelegt, {name}. Ich vertraue darauf, dass Ihr diese Rüstung zusammen mit meinem Dank annehmt. Tragt sie mit Stolz, denn Ihr habt sie verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[10938] = { id = 10938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segenskartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Segenskartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr wisst gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Segenskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Segenskarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Segenskartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10939] = { id = 10939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Sturmkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr wisst gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Sturmkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Sturmkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Sturmkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10940] = { id = 10940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furienkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Furienkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr wisst gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Furienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Furienkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Furienkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10941] = { id = 10941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliriumkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Deliriumkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr wisst gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Deliriumkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Deliriumkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Deliriumkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10942] = { id = 10942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kinderwoche", description = "Ein ganz besonderes kleines Mädchen wird sich sehr darüber freuen, Euch zum Freund zu haben, und sei es nur für eine kurze Zeit.\n\nNehmt diese Pfeife. Ihr könnt damit das Kind rufen, dessen Patenschaft Ihr übernommen habt. Diese Patenschaft wird nicht lange dauern, nur solange die Kinderwoche andauert.\n\nBitte, {name}, ruft Eurer Waisenkind herbei. Ich weiß, dass sie schon darauf brennt Euch kennenzulernen und die Chance zu haben, einen Blick auf die Welt außerhalb der Stadt zu werfen!", sourceObjective = "Benutzt die Pfeife des Blutelfenwaisenkinds um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[10943] = { id = 10943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kinderwoche", description = "Ein ganz besonderes kleines Mädchen wird sich sehr darüber freuen, Euch zum Freund zu haben, und sei es nur für eine kurze Zeit.\n\nNehmt diese Pfeife. Ihr könnt damit das Kind rufen, dessen Patenschaft Ihr übernommen habt. Diese Patenschaft wird nicht lange dauern, nur solange die Kinderwoche andauert.\n\nBitte, {name}, ruft Eurer Waisenkind herbei. Ich weiß, dass sie schon darauf brennt Euch kennenzulernen und die Chance zu haben, einen Blick auf die Welt außerhalb der Stadt zu werfen!", sourceObjective = "Benutzt die Pfeife des Draeneiwaisenkinds um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[10944] = { id = 10944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gefährdete Geheimnis", description = "Nochmals vielen Dank, {name}. Ich kenne Euren Namen. Akama hat Euch seine Pläne anvertraut, daher werde ich Euch ebenso vertrauen.\n\nDie Nagas haben herausgefunden, dass ich gegen Illidan arbeite und mich grausamer Folter unterzogen. Sie haben jedoch nichts aus mir herausbekommen. Akama selbst hat mir beigebracht, wie man Schmerz mithilfe von Meditation überwindet.\n\nIllidan hat den Nagas aufgetragen, mich zu ihm persönlich zu bringen. Er hätte mich sofort durchschaut und die tiefsten Geheimnisse meiner Seele gesehen.\n\nWir müssen Akama warnen! Unsere Pläne sind in Gefahr!", sourceObjective = "Reist zum Kerker des Wächters im Schattenmondtal und sprecht mit Akama.", completion = "Ich danke Euch, {name}. Olum ist einer meiner engsten Freunde und meiner treuesten Anhänger. Sein Beitrag zu unserem Werk ist für unsere Pläne unverzichtbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10945] = { id = 10945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hch'uu und das Pilzvolk", description = "Ich habe eine Freundin namens Hch'uu. Sie hat mir erzählt, dass sie im Waisenhaus gelandet ist, weil sie vor einem bösen Fungusgiganten fliehen musste und sich verlaufen hat.\n\nWir hatten sehr viel Spaß zusammen, bis Ihr Volk sie letztes Jahr gefunden und mitgenommen hat. Ich glaube, sie haben sie an einen Ort namens Sporeggar gebracht.\n\nIch würde sie und das Pilzdorf gerne sehen. Die Waisenmatrone hat mir gesagt, dass es auf der westlichen Seite der Zangarmarschen liegt, zwischen dem Sporenwindsee und dem Sumpflichtsee.\n\nGehen wir dorthin? Gehen wir dorthin? Bitte?!", sourceObjective = "Bringt Euer Waisenkind Salandria nach Sporeggar in den Zangarmarschen. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt. Sprecht danach mit Hch'uu.", sourceObjectiveStatus = "unverified-source-field" }
quests[10946] = { id = 10946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die List der Aschenzungen", description = "Olums Opfer war gewaltig. Ich hätte ihn niemals gebeten, sein Leben für mich zu geben. Aber so ist es geschehen.\n\nWenn wir Illidan in falscher Sicherheit wiegen wollen, müssen wir seine Befehle ausführen, zumindest fürs Erste.\n\nIch befehlige eine große Armee von Aschenzungen, aber außer den Todeshörigen kann ich keinem davon trauen.\n\nIhr sollt die Tat, die Illidan wünscht, ausführen. Nehmt diese Gugel. Sie ist magisch. Jeder, der Euch Kaels Phönix Al'ar erschlagen sieht, wird Euch für einen meiner Männer halten.", sourceObjective = "Reist in die Festung der Stürme und tötet Al'ar, während Ihr die Gugel der Aschenzungen tragt. Kehrt nach Abschluß der Aufgabe zu Akama ins Schattenmondtal zurück.", progress = "Ist es vollbracht, {name}? Illidan ist kein besonders geduldiger Herr!", completion = "Das habt Ihr gut gemacht, {name}. Dies bringt uns einen Schritt näher, Illidans Blick abzuwenden. Von uns und von...\n\n\n\nEs liegt noch mehr Arbeit vor uns, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10947] = { id = 10947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Artefakt aus der Vergangenheit", description = "Dank Euch richtet sich Illidans Aufmerksamkeit nun auf Kael'thas. Es ist an der Zeit zu handeln!\n\nIn einer Vision sah ich ein mächtiges Artefakt, welches in unserem Entscheidungskampf von größter Bedeutung sein wird, das Phylakterium eines mächtigen Lichs, bekannt als Winterfrost. Leider ging es nach seiner Niederlage in der Schlacht um den Berg Hyjal für immer verloren.\n\nEs gibt jedoch einen Weg, um wieder an das Artefakt zu gelangen. Die Legenden sprechen von einem Ort in Azeroth, welcher von bronzenen Drachen bewacht wird... ein Ort an dem Vergangenheit und Gegenwart nebeneinander existieren. Dort werdet Ihr finden, was wir suchen!", sourceObjective = "Reist zu den Höhlen der Zeit in Tanaris und verschafft Euch Zugang zur Schlacht um den Berg Hyjal. Habt Ihr dies geschafft, so bezwingt Furor Winterfrost und bringt das zeitverzerrte Phylakterium zu Akama im Schattenmondtal.", progress = "Ist das Phylakterium bereits in Eurem Besitz, {name}?", completion = "Meine Vision... nun wird mir alles klar. Die Macht, die dieses Artefakt über eine Seele ausüben kann...  sie einzuschließen... sie in sich selbst aufzunehmen... Ich werde diese Kraft dazu nutzen, um zurückzuholen, was rechtmäßig mir gehört! Der Augenblick ist gekommen, um den Kampf gegen Illidan aufzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10948] = { id = 10948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seelengeisel", description = "Ihr fragt Euch vielleicht, warum ich so weit gehe, um mein Vorhaben zu verschleiern. Warum arbeite ich nicht einfach offiziell mit den Naaru zusammen?\n\nMeine ureigene Essenz, meine Seele, wird im Schwarzen Tempel als Geisel gehalten. Mit einem Wimpernschlag könnte Illidan mich ausradieren... bis jetzt! Dieses Phylakterium wird es mir ermöglichen, meine Seele wieder in meine Kontrolle zu bringen.\n\nEs ist soweit, {name}. Ich werde Maiev und meine Todeshörigen bis an Illidans Türschwelle führen.\n\nSprecht mit A'dal und berichtet ihm von unserem Plan. Wenn wir gemeinsam zuschlagen, werden wir Illidans Verteidigung durchbrechen können.", sourceObjective = "Reist nach Shattrath und erzählt A'dal von Akamas Bitte.", completion = "<A'dals Licht umfängt Euch, als er Euch begrüßt. Ihr habt das Gefühl, dass er schon weiß, worum Ihr ihn bitten wollt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10949] = { id = 10949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutritt zum Schwarzen Tempel", description = "<A'dal zeigt Euch ein Bild eines Naaru außerhalb des Schwarzen Tempels, der Seite an Seite mit Verteidigern der Draenei und Magistern der Blutelfen kämpft. Ihr wisst sofort, dass dies die Ablenkung ist, auf die Akama wartet.>", sourceObjective = "Reist zum Eingang des Schwarzen Tempels im Schattenmondtal und sprecht mit Xi'ri.", completion = "<Xi'ri scheint Eure Anwesenheit zu bemerken. Offensichtlich konzentriert er sich auf die Schlacht in der Umgebung.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10950] = { id = 10950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun und der Ring der Beobachtung", description = "Einer der Priester, der uns regelmäßig besucht, hat mir eine Geschichte über einen Ort in der Nähe erzählt. Er wird Auchindoun genannt und soll für die Draenei sehr wichtig sein.\n\nEr sagte, dass die Körper der verstorbenen Draenei an diesen Ort gebracht wurden. Aber vor einer Weile hat etwas Böses ihn in die Luft gejagt.\n\nIch würde dort gerne den Ring der Beobachtung sehen. Die Waisenmatrone hat mir gesagt, dass er in der Mitte der Knochenwüste liegt, auf der südlichen Seite der Wälder von Terokkar.\n\nKönnen wir dort bitte hingehen, <Herr/Frau> {name}?", sourceObjective = "Bringt Euer Waisenkind Dornaa zum Versammlungsstein beim Ring der Beobachtung in der Mitte von Auchindoun. Auchindoun liegt inmitten der Knochenwüste der Wälder von Terokkar. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10951] = { id = 10951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Reise zum Dunklen Portal", description = "Wie können wir uns all die interessanten Orte anschauen und dabei das Dunkle Portal vergessen?!\n\nDie Erwachsenen versuchen immer, uns Gruselgeschichten darüber zu erzählen, und schildern, wie gefährlich es dort ist mit den vielen Dämonen und all dem Zeugs.\n\n<Salandria rollt mit den Augen.>\n\nAber Ihr seid hier, also kann es ja nicht so schlimm sein, oder?\n\nIch will es selbst sehen. Könnt Ihr Euch noch erinnern, wo genau es sich am östlichen Rand der Höllenfeuerhalbinsel befindet?", sourceObjective = "Geht mit Eurem Waisenkind Salandria die Stufen des Schicksals hinauf und besucht das Dunkle Portal auf der Höllenfeuerhalbinsel. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10952] = { id = 10952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Reise zum Dunklen Portal", description = "Es gibt einen Ort, den wir auf jeden Fall anschauen müssen: das Dunkle Portal!\n\nDie Waisenmatronen versuchen uns immer Gruselgeschichten darüber zu erzählen und wie gefährlich es dort ist mit vielen Dämonen und Leuten wie Euch, die hindurch kommen.\n\n<Dornaa rollt mit den Augen.>\n\nAber Ihr seid hier und Ihr seid nett, also kann es ja nicht so schlimm sein, oder?\n\nIch will es selbst sehen. Könnt Ihr Euch noch erinnern, wo genau es sich am östlichen Rand der Höllenfeuerhalbinsel befindet?", sourceObjective = "Geht mit Eurem Waisenkind Dornaa die Stufen des Schicksals hinauf und besucht das Dunkle Portal auf der Höllenfeuerhalbinsel. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10953] = { id = 10953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besuch beim Thron der Elemente", description = "Habt Ihr vom Thron der Elemente gehört? Er soll angeblich in Nagrand sein wo all die mächtigen Elementare sind.\n\nIch werde bald eine große Magierin oder eine Hexenmeisterin! Daher werde ich lernen müssen, wie man diese Elemente bändigt.\n\nKönnen wir vielleicht dorthin gehen?\n\n<Salandria schaut Euch listig an.>\n\nDas wäre fast schon eine Bildungsreise. Der Thron soll angeblich nördlich von Garadar sein, auf der anderen Seite des Himmelsweisensees.", sourceObjective = "Bringt Euer Waisenkind Salandria zum Thron der Elemente in Nagrand. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt. Sprecht dann mit Elementaristin Sharvak.", sourceObjectiveStatus = "unverified-source-field" }
quests[10954] = { id = 10954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jheel ist beim Aerissteg!", description = "Ich vermisse meinen Bruder Jheel. Er ist ein paar Jahre älter als ich und hat eine Ausbildung bei den Astralen in Nagrand angefangen.\n\nEs wäre so schön ihn einmal zu besuchen. Er liebt Geologie und so was, daher hat er bestimmt sehr viel Spaß.\n\nDie Waisenmatrone hat mir gesagt, dass er an einem Ort namens Aerissteg in Nagrand in Ausbildung ist. Er soll sich an der Straße weit westlich von Telaar und nordwestlich des großen Bergs Oshu'gun befinden.", sourceObjective = "Bringt Euer Waisenkind Dornaa zum Aerissteg in Nagrand. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt. Sprecht dann mit Jheel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10955] = { id = 10955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morthis Flügelraunen", description = "Bevor die druidischen Orden sich zum Zirkel des Cenarius zusammenschlossen, brachten die Druiden der Kralle aufstrebenden jungen Druiden die Kunst des Fliegens bei. Nach der Auflösung des Ordens wurden die früheren Mitglieder was ihre Schüler angeht sehr wählerisch.\n\nMorthis Flügelraunen sucht noch immer nach einem würdigen Lehrling. Nur wenige Druiden haben je alle Formen beherrscht, die ihnen zur Verfügung stehen, doch Ihr versprecht das zu haben, wonach Morthis sucht. Sucht ihn bei der Zuflucht des Cenarius in den Zangarmarschen auf.", sourceObjective = "Sucht nach Morthis Flügelraunen in der Zuflucht des Cenarius in den Zangarmarschen.", completion = "<Morthis sieht Euch skeptisch an.>\n\nIch suche schon lange nach einem Schüler, dem ich mein Wissen weitergeben kann. Obwohl die Druiden der Kralle kein offizieller Orden mehr sind, werde ich bis ans Ende meiner Tage einer von ihnen sein.\n\nVon diesem Moment an nehme ich Euch als Schüler an. Ich werde Euch in die Geheimnisse der Sturmkrähe einweihen. Ihr müsst im Gegenzug bereit sein, alles, worum ich Euch bitte, zu tun. Habt Ihr das verstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[10956] = { id = 10956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sitz der Naaru", description = "Wisst Ihr etwas über die Naaru? Das sind diese engelhaften Wesen, die den Draenei schon lange Zeit helfen. Ich habe ein paar von ihnen in Shattrath gesehen.\n\nMan sagt, dass der Naaru O'ros dabei war, als die Exodar in Eure Heimatwelt gereist ist. Ich würde das gerne selbst sehen.\n\nKönnt Ihr mich dorthin bringen? Ich wette, wenn wir eines dieser Portale auf der Terrasse des Lichts in Shattrath benutzen, sind wir ganz schnell! Und wenn wir da sind, können wir einfach Eure Karte anschauen, wenn wir uns verirren.", sourceObjective = "Bringt Euren Schützling Dornaa zu O'ros im unteren Teil des Sitzes der Naaru in der Exodar auf der Azurmythosinsel. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt.\n\nVergesst nicht, dass Ihr in der Stadt Eure Karte verwenden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10957] = { id = 10957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlösung der Aschenzungen", description = "Als Illidan die Treue der Zerschlagenen erlangt hat, war Akama der Weiseste unter uns. Er wusste, dass eine direkte Konfrontation mit dem Verräter das Ende unseres Volkes bedeuten würde.\n\nStattdessen hat er diesen Moment in aller Verstohlenheit geplant und vorbereitet. Ein Versagen wäre eine Katastrophe... nicht nur für Akama, nicht nur für die Zerschlagenen, sondern für die gesamte Scherbenwelt. Niemand, der Illidan so nahe stand, war je in der Lage gewesen, ihm einen solchen Schlag zu versetzen.\n\nHelft Akama dabei, seine Seele zu befreien. Dann wird er Euch Zutritt zu Illidans Sanktum gewähren.", sourceObjective = "Helft Akama die Kontrolle über seine Seele wieder zu erlangen, indem Ihr Akamas Schemen im Schwarzen Tempel besiegt. Kehrt anschließend zu Seher Kanai zurück.", progress = "Ja, {name}?", completion = "Es ist vollbracht, {name}. Nun ist es an der Zeit, Illidan zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10958] = { id = 10958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht die Aschenzungen auf", description = "<Als Ihr zu Xi'ri aufblickt, schärft sich Euer Geist und Euer Wille wird stark. Eure Arbeit hier ist noch nicht vorüber. Ihr müsst in den Schwarzen Tempel gehen und Akamas Anhänger finden.>\n\n<Es hängt sehr viel von Akamas Erfolg ab.>", sourceObjective = "Sucht Akamas Todeshörige im Schwarzen Tempel.", completion = "Wir haben Euch bereits erwartet, {name}. Akama braucht dringend Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10959] = { id = 10959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz des Verräters", description = "Jetzt, da Illidans Leutnants besiegt sind, wird Akama die Türen zu Illidans Sanktum aufbrechen. Haltet Euch und Eure Streitkräfte bereit, um sofort hinein zu stürmen, sobald Akama es geschafft hat.\n\nWir wissen immer noch nicht, was aus Maiev geworden ist, aber wir müssen ohne sie beginnen.\n\nIch hoffe, dass Eure Streitkräfte der Sache gewachsen sind. Illidan wird nicht sehr erfreut sein, wenn er Akama zu Gesicht bekommt.", sourceObjective = "Seher Kanai möchte, dass Ihr Illidan im Schwarzen Tempel besiegt.", progress = "Ja, {name}?", completion = "Es ist geschehen, wie es vorherbestimmt war, {name}. Illidans Leutnants sind einer nach dem anderen gefallen... und sogar der Verräter fand den Tod!\n\nWisset eines, {name}: bei jeder Entscheidung, die Akama seit der Ankunft Illidans in seinem Leben getroffen hat, war dieser Augenblick sein Ziel. Illidan ist nun endlich tot und unser Volk... ist frei!", sourceObjectiveStatus = "unverified-source-field" }
quests[10960] = { id = 10960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn ich groß bin...", description = "Wusstet Ihr in meinem Alter schon, dass Ihr später mal <ein/eine:c> {class} werden wollt?\n\nIch weiß noch nicht, was ich einmal werden will. Vielleicht ein Magier oder Hexenmeister, wie ich vorhin schon sagte - oder vielleicht ein Paladin der Blutritter! Ja, ich will auf jeden Fall Blutritter werden!\n\nMan sagt, dass die echten Blutritter in Silbermond in Eurer Welt ausgebildet werden. Könnt Ihr mich dorthin bringen? Die Geschichten, die ich gehört habe, besagen, dass die Paladinlehrer sich auf dem Platz der Weltenwanderer in dieser Stadt aufhalten.\n\nBitte bringt mich dorthin. Bitte!", sourceObjective = "Bringt Euren Schützling Salandria zu den Paladinlehrern auf dem Platz der Weltenwanderer in Silbermond. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt. Sprecht danach mit Lady Liadrin, der Matriarchin der Blutritter.\n\nVergesst nicht, dass Ihr in der Stadt Eure Karte verwenden und die Wachen nach den Paladinlehrern fragen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10961] = { id = 10961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zauber des Erwachens", description = "Vor langer Zeit wurden die Relikte, mit deren Hilfe man den Weg der Sturmkrähe lehrte, einem uralten Druiden anvertraut.\n\nWir werden diese Relikte für Eure Ausbildung brauchen, daher müssen wir den Wächter aus seinem Schlummer erwecken.\n\nIch werde Euch einen Trank zubereiten, mit dessen Hilfe Ihr den Vorgang erleichtern könnt. Für das Gebräu benötige ich gewöhnliche Kräuter und Sumpfblüten, die auf den höchsten Pilzen in den Marschen wachsen. Fliegt an ihnen hoch und seid beim Sammeln der Blüten vorsichtig, {name}, sie sind ziemlich empfindlich und könnten bei falscher Handhabung heftig explodieren.", sourceObjective = "Bringt 10 Sumpfblüten, 10 Urflechten und 10 Traumwinden zu Morthis Flügelraunen in der Zuflucht des Cenarius.", progress = "Habt Ihr alle Zutaten, die ich für die Zubereitung des Tranks benötige? Vorsicht, bringt nur keine Pollen in meine Nähe, bitte. Ich muss deswegen immer furchtbar niesen.\n\n<Morthis schnüffelt gedemütigt bei einem Niesen.>", completion = "<Morthis nimmt die Kräuter entgegen und untersucht sie. Er holt eine Phiole hervor und beginnt den Trank zu mischen.>\n\nEs dauert nur einen Moment, {name}. Dann müsst Ihr zur Mondlichtung reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10962] = { id = 10962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit die Höhlen zu besuchen", description = "Im Waisenhaus erzählt der alte Priester, der uns immer besuchen kommt, oft Geschichten über die Höhlen der Zeit. Er sagt, dass sie im Zentrum der Zeit liegen und unheimlich wichtig sind, damit alle Dinge ihren gewohnten Gang gehen.\n\nIch weiß nicht genau, was das heißt, aber er hat gesagt, dass es da Drachen gibt, die dabei helfen die Welt zu retten! Ich will einen Drachen sehen!\n\nKönnten wir da hingehen? Er sagte, dass der Eingang sich am östlichen Rand einer großen Wüste namens Tanaris befände.\n\nVielleicht könnt Ihr mir ja auch ein Andenken kaufen, während wir da sind?", sourceObjective = "Bringt Euren Schützling Dornaa zu Zaladormu, dem Drachen auf der Anhöhe in den Höhlen der Zeit. Ruft sie zu Euch, falls sie nicht anwesend ist, wenn Ihr ankommt.\n\nErwerbt danach für sie einen Spielzeugdrachen bei Alurmi, dem Rüstmeister der Hüter der Zeit, in der Nähe des Endes des Eingangstunnels.", sourceObjectiveStatus = "unverified-source-field" }
quests[10963] = { id = 10963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit die Höhlen zu besuchen", description = "Im Waisenhaus erzählt der stinkende alte Priester, der uns immer besuchen kommt, oft Geschichten über die Höhlen der Zeit. Er sagt, dass sie im Zentrum der Zeit liegen und unheimlich wichtig sind, damit alle Dinge ihren gewohnten Gang gehen.\n\nIch weiß nicht genau, was das heißt, aber er hat gesagt, dass es da Drachen gibt, die dabei helfen die Welt zu retten! Ich will einen Drachen sehen!\n\nKönnten wir da hingehen? Er sagte, dass der Eingang sich am östlichen Rand einer großen Wüste namens Tanaris befände.\n\nVielleicht könnt Ihr mir ja auch ein Andenken kaufen, während wir da sind?", sourceObjective = "Bringt Euren Schützling Salandria zu Zaladormu, dem Drachen auf der Anhöhe in den Höhlen der Zeit. Ruft sie zu Euch, falls sie nicht anwesend ist, wenn Ihr ankommt.\n\nErwerbt danach für sie einen Spielzeugdrachen bei Alurmi, dem Rüstmeister der Hüter der Zeit, in der Nähe des Endes des Eingangstunnels.", sourceObjectiveStatus = "unverified-source-field" }
quests[10964] = { id = 10964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schläfer wecken", description = "Nehmt den Zauber mit Euch und reist zu Sturmgrimms Grabhügel auf der Mondlichtung. Im südlichsten Teil von Sturmgrimms Grabhügel, der von den Traumwächtern bewacht wird, werdet Ihr Clintar Traumwandler finden.\n\nGebt ihm den Zaubertrank und beschützt ihn, während er erwacht. Er wird sehr leicht verwundbar sein, während sein Geist sich mit seinem Körper verbindet, und Euch sicher nicht erkennen. Erklärt ihm, wer Ihr seid, wenn er zu Kräften kommt, {name}. Er wird Eure Hilfe brauchen, um die Relikte für das Ritual zu sammeln.", sourceObjective = "Benutzt den Zauber des Erwachens um Clintar Traumwandler aus dem Smaragdgrünen Traum zu holen. Sprecht mit ihm, sobald er zu sich kommt.", progress = "<Ihr bereitet Euch darauf vor, dem schlafenden Druiden den Zaubertrank zu verabreichen.>", completion = "<Der {class} erwacht aus seinem Schlaf und wirkt benommen und ausgezehrt. Sein Blick wandert auf der Suche nach unsichtbaren Verfolgern im Raum herum.>\n\nMorthis?\n\nNein, Ihr seid nicht Morthis... Wer seid Ihr, {race}, und warum stört Ihr meine Ruhe?", sourceObjectiveStatus = "unverified-source-field" }
quests[10965] = { id = 10965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als ein Traum", description = "<Clintar hört Euch nickend zu, als Ihr Morthis Anweisungen weitergebt, aber er scheint Angst zu haben.>\n\nIch kann mich nicht vollständig aus dem Smaragdgrünen Traum zurückziehen, um Euch zu helfen. Ich werde Euch jedoch ein Fragment meiner Seele auf der Suche nach den Relikten mitgeben. Passt gut darauf auf, {race}, denn mein Geist ist sehr zerbrechlich.\n\nDer Smaragdgrüne Traum selbst ist zu einem fremdartigen und gefährlichen Ort geworden. Er hält mich fest umklammert. Ich werde mich nicht lösen können, bis der Smaragdgrüne Traum wieder normal geworden ist. Was Ihr um Euch herum seht ist nur ein Nachhall der Wirklichkeit im Traum selbst!", sourceObjective = "Beschützt Clintar Traumwandlers Geist während er die Relikte von Aviana sammelt. Sprecht danach mit Traumwächter Lurosa.", progress = "Beeilt Euch, {race}. Wenn diese Kreaturen aus dem Grabhügel entkommen, ist nicht nur Clintar Traumwandler in Gefahr!", completion = "Ihr hattet Glück, dass Clintar stark genug war, seine Essenz so lange am Leben zu erhalten, {name}. Nur wenige Druiden schaffen das, während sie im Smaragdgrünen Traum angegriffen werden. Gebt gut auf die Relikte Acht!", sourceObjectiveStatus = "unverified-source-field" }
quests[10966] = { id = 10966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Verdammt! Ich glaube, wir müssen zum Waisenhaus in Shattrath zurück.\n\nIch hatte so viel Spaß! Ihr seid <der/die> Tollste aller Welten, {name}! Ihr seid jetzt <mein großer Bruder/meine große Schwester>!\n\n<Dornaas Augen füllen sich mit Tränen.>\n\nIch werde Euch so vermissen! Wenn ich groß bin, will ich genauso sein wie Ihr!!!", sourceObjective = "Kehrt zum Waisenhaus in Shattrath zurück und übergebt die Pfeife Eures Schützlings an Waisenmatrone Gnädig im unteren Viertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10967] = { id = 10967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Verdammt! Ich glaube, wir müssen zum Waisenhaus in Shattrath zurück.\n\nIch hatte so viel Spaß! Ihr seid <der/die> Tollste aller Welten, {name}! Ihr seid jetzt <mein großer Bruder/meine große Schwester>!\n\n<Salandrias Augen füllen sich mit Tränen.>\n\nIch werde Euch so vermissen!!!", sourceObjective = "Kehrt zum Waisenhaus in Shattrath zurück und übergebt die Pfeife Eures Schützlings an Waisenmatrone Gnädig im unteren Viertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10968] = { id = 10968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besucht den Weissager", description = "Ich spüre, dass dieses Kind etwas ganz besonderes ist.\n\nIhr solltet sie zu Weissager Nobundo hier auf der Exodar bringen. Ich glaube, dass er Euch beide schon erwartet.\n\nIhr findet Nobundo auf der höchsten Terrasse in der Kristallhalle.", sourceObjective = "Bringt Euren Schützling Dornaa zu Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.\n\nVergesst nicht, dass Ihr in der Stadt Eure Karte verwenden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10969] = { id = 10969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Ameer!", description = "Es scheint als ob eine außenstehende Macht Interesse an den Geschäftsmethoden des Konsortiums gewonnen hat. In den letzten beiden Tagen wurden fünf Händler des Konsortiums als vermisst gemeldet. Es besteht großer Grund zur Annahme, dass das Astraleum etwas damit zu tun hat. Wenn Ihr helfen möchtet, sucht nach Kommandant Ameer beim Wachposten des Protektorats.\n\nIhr findet den Wachposten des Protektorats östlich von hier auf der nächsten Insel.", sourceObjective = "Sucht Kommandant Ameer beim Wachposten des Protektorats auf.", completion = "Ja, das stimmt. Doch das Konsortium ist nicht die einzige Gruppierung, die Verluste zu vermelden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10970] = { id = 10970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein barmherziger Auftrag", description = "Wir haben diese Gefängniskugel auf unserer letzten Spähermission im Gebiet des Astraleums sichergestellt. Hätte sie nicht dieses schwache Störsignal gesendet, hätten wir sie vielleicht nie gefunden.\n\nWir glauben, dass einer von uns darin eingesperrt ist, aber wir haben keine Möglichkeit die Kugel zu öffnen ohne den Inhalt zu verletzen.\n\nWir wissen nur, dass praktisch jedes Mitglied des Astraleums den Schlüssel dazu haben könnte. Beschafft Euch einen Schlüssel und bringt ihn zu uns, damit wir das Geheimnis der Kugel entschlüsseln können.", sourceObjective = "Beschafft Euch den sichergestellten Gefängnisschlüssel des Astraleums und bringt ihn zu Kommandant Ameer beim Wachposten des Protektorats im Nethersturm.", progress = "Hattet Ihr Glück?", completion = "Tretet zurück, {name}. Es könnte auch eine Falle des Astraleums sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10971] = { id = 10971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Astraleums", description = "<Ameer hält eine Marke hoch.>\n\nIch habe diese Identifizierungsmarke eines Gefangenen bei den Überresten des gefallenen Vorpostens gefunden. Ich gehe davon aus, dass alle ihre Gefangenen auf diese Weise markiert werden.\n\nIch werde damit anfangen, alle Marken zu katalogisieren. Vielleicht kann ich so etwas über das System ihrer Gefangennahmen herausfinden. Falls Ihr auf Euren Abenteuern noch mehr Gefängnisschlüssel des Astraleums finden solltet, könnt Ihr damit die Gefängnisse des Astraleums beim Stützpunkt des Astraleums direkt südlich von hier aufschließen. Bringt mir alle Identifizierungsmarken, die Ihr finden könnt!", sourceObjective = "Kommandant Ameer beim Wachposten des Protektorats im Nethersturm möchte, dass Ihr ihm eine Identifizierungsmarke eines Gefangenen des Astraleums bringt.", progress = "Habt Ihr ein paar Identifizierungsmarken finden können?", completion = "Es scheint sich hierbei um mehr als eine einfache Identifizierungsmarke zu handeln. Auf den Marken ist eine Art Code zu sehen. Ich stehe kurz davor, ihn zu entschlüsseln. Wenn ich doch nur mehr Marken hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[10972] = { id = 10972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katalog der Gefangenen des Astraleums", description = "Ich brauche mehr Identifizierungsmarken, {name}. Ich konnte bisher herausfinden, dass sie nicht nur die Gefangenen katalogisieren, sondern auch Aussagen über ihre Aufenthaltsorte machen!\n\nSobald wir diesen Code entschlüsselt haben, können wir genau feststellen, wo unsere Verbündeten festgehalten werden und sie mit minimalem Gewalteinsatz befreien.", progress = "Ich brauche mehr Identifikationsmarken, {name}. Ich konnte bisher herausfinden, dass sie nicht nur die Gefangenen katalogisieren, sondern auch Aussagen über ihre Aufenthaltsorte machen!\n\nSobald wir diesen Code entschlüsselt haben, können wir genau feststellen, wo unsere Verbündeten festgehalten werden und sie mit minimalem Gewalteinsatz befreien.", completion = "Wir sind der Wahrheit auf der Spur, {name}." }
quests[10973] = { id = 10973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tausend Welten", description = "Ich habe den Code entschlüsselt! Jede Marke ist in verschiedene Segmente geteilt. Die Vorderseite der Marke ist immer gleich. Darauf steht: \"Tausend Welten...\". Ich bin mir nicht sicher, was das zu bedeuten hat, aber es klingt irgendwie heimtückisch.\n\nAuf der Rückseite der Marke stehen die wichtigen Angaben. Die erste Gruppe von Runen gibt den Aufenthaltsort an, die zweite die Art der Gefangenschaft. Des Weiteren sieht es aus, als ob die Schlüssel zu einem besonderen Schlüssel zusammengefügt werden können, mit dem man eine andere Art von Gefängnis öffnen kann. Jetzt brauche ich noch mehr Schlüssel...", sourceObjective = "Kommandant Ameer am Wachposten des Protektorats im Nethersturm möchte, dass Ihr ihm 5 Gefängnisschlüssel des Astraleums bringt.", progress = "Ich weiß, dass ich Euch um viel bitte, aber denkt an all die Leben, die wir retten könnten!", completion = "<Ameer fügt die Schlüssel geschickt zusammen und betrachtet die Markierungen auf der so hergestellten Schlüsseltafel.>\n\n\"Tausend Welten zerschlagen, tausend weitere noch zu bezwingen... So lautet der Wille des Nexuskönigs.\"\n\n<Ameer dreht die Tafel um und liest die Rückseite.>\n\nStasiskammern von Bash'ir?", sourceObjectiveStatus = "unverified-source-field" }
quests[10974] = { id = 10974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stasiskammern von Bash'ir", description = "Das Astraleum hat eine kleine Siedlung am nördlichsten Rand des Schergrats, die als Landeplatz von Bash'ir bekannt ist. Laut der Schlüsseltafel soll es in Bash'ir noch größere Gefängnisse geben. Die Anhänger des Astraleums nennen sie Stasiskammern.\n\nDie Schlüsseltafel gewährt Zugang zu einer ganz bestimmten Stasiskammer am Landeplatz, die als Stasiskammer Alpha bekannt ist. Nehmt den Schlüssel und kundschaftet sie aus.\n\nMein Bild wird neben dem Landeplatz von Bash'ir auf Eure Rückkehr warten. Sprecht mit mir, wenn Ihr fertig seid.", sourceObjective = "Benutzt die Schlüsseltafel des Astraleums - Alpha um die Stasiskammer Alpha im Landeplatz von Bash'ir im Schergrat zu öffnen.\n\nBringt Beweisstücke aus Alpha zum Bild von Kommandant Ameer beim Landeplatz von Bash'ir.", progress = "Ihr habt es geschafft! Hattet Ihr Glück?", completion = "<Das Bild von Kommandant Ameer kramt in den Beweisstücken.>\n\nEs ist schlimmer als ich dachte... Diese Kammern enthalten wilde Bestien und Kreaturen von vielen verschiedenen Welten. Das Astraleum hofft, eines Tages Kontrolle über diese Bestien zu gewinnen und sie ihrem Willen zu unterwerfen. Wir müssen sie alle vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10975] = { id = 10975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung der Kammern von Bash'ir", progress = "Wir sitzen in der Sackgasse, {name}. Die Daten, die Ihr gesammelt habt, haben uns genügend Informationen geliefert, um unsere Verbündeten aus den kleineren Gefängnissen des Nethersturms retten zu können. Wir müssen uns jedoch dringend um die Bedrohung kümmern, die von den Kammern hier im Ladeplatz von Bash'ir ausgeht.\n\nSchließt Euch dem Kampf gegen das Astraleum an! Bringt mir die Gefängnisschlüssel des Astraleums, damit ich Stasiskammerschlüssel für die Stasiskammern von Bash'ir für Euch herstellen kann.", completion = "Es gibt immer noch mehr Arbeit, die erledigt werden muss, {name}. Begebt Euch nun auf die Suche nach einer Stasiskammer und vernichtet, was auch immer darin lauern mag!" }
quests[10976] = { id = 10976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Abzeichen des Nexuskönigs", description = "Jetzt muss ich wissen, was das Astraleum in der Managruft in Auchindoun gefangen hält.\n\nVielleicht ist Euch in Euren Kämpfen gegen die Bestien der Stasiskammern von Bash'ir ein Gegenstand untergekommen, der als Abzeichen des Nexuskönigs bekannt ist. Wenn Ihr einen solchen Gegenstand finden solltet, bringt ihn sofort zu mir! Dieses Abzeichen ist der letzte Teil, den ich zur Herstellung eines Schlüssels brauche, der Euch Zugang zu der Stasiskammer in der Managruft gewähren wird.", sourceObjective = "Das Bild von Kommandant Ameer beim Landeplatz von Bash'ir im Schergrat möchte, dass Ihr ihm ein Abzeichen des Nexuskönigs bringt.", progress = "Dies wird Eure furchteinflößendste Aufgabe sein, {name}.", completion = "Endlich!\n\n<Kommandant Ameer liest die Inschrift auf dem Abzeichen des Nexuskönigs.>\n\nZwei Gefängnisse? Schon der Gedanke an die Schrecken, die darin hausen mögen, lässt mich erzittern...", sourceObjectiveStatus = "unverified-source-field" }
quests[10977] = { id = 10977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stasiskammern der Managruft", description = "Ich habe aus dem Abzeichen des Nexuskönigs einen neuen Schlüssel hergestellt, mit dem Ihr die Stasiskammern in der Managruft betreten könnt.\n\nLaut den Glyphen auf dem Abzeichen gibt es gleich zwei davon: eine in der Nähe der Vorderseite, eine weitere in der Nähe von Nexusprinz Shaffar. Der Schlüssel, den ich Euch nun geben werde, öffnet die Stasiskammer in der Nähe der Vorderseite.\n\nIch möchte, dass Ihr in die Managruft von Auchindoun reist und die Stasiskammer der Managruft öffnet.", sourceObjective = "Das Bild von Kommandant Ameer beim Landeplatz von Bash'ir im Schergrat möchte, dass Ihr den Stasiskammerschlüssel der Managruft verwendet, um die Stasiskammer in der Managruft Auchindouns zu öffnen.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich könnte verstehen, wenn Ihr lieber nicht weitermachen wollt, {name}.", completion = "Ich habe von Euren Heldentaten erfahren, {name}. Haramad und ich sind uns beide einig, dass Ihr dafür eine großartige Belohnung verdient habt.\n\nObwohl... Ach, Ihr habt schon genug getan. Ich kann Euch nicht guten Gewissens um noch mehr bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10978] = { id = 10978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Morthis Flügelraunen", description = "Jetzt, da die Relikte geborgen wurden, müsst Ihr diesen Ort so schnell wie möglich wieder verlassen. Clintar hat seine eigene Sicherheit sowie die der Traumwächter für Euch aufs Spiel gesetzt, {name}. Nun muss er sich vollkommen auf den Kampf gegen die Macht konzentrieren, die in den Smaragdgrünen Traum eingedrungen ist.\n\nBringt die Relikte zu Morthis Flügelraunen und berichtet ihm, was Ihr hier gesehen habt. Vielleicht kann er uns dabei helfen herauszufinden, mit wem Clintar es zu tun hat.", sourceObjective = "Bringt die Relikte von Aviana zu Morthis Flügelraunen in der Zuflucht des Cenarius in den Zangarmarschen.", progress = "Hat Clintar Euch bei der Beschaffung der Relikte geholfen?", completion = "<Morthis nimmt Euch die Relikte ab, während Ihr Eure Erlebnisse in den Grabhügeln schildert.>\n\nDas sind äußerst beunruhigende Nachrichten, {name}. Es gab ein paar Störungen im Smaragdgrünen Traum, aber ich kann mich nicht entsinnen, dass je von einer außenstehenden Macht gesprochen wurde, die ihre Finger im Spiel hat. Seid Ihr sicher, dass Clintar es genau so gemeint hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[10979] = { id = 10979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum ewigen Hain", description = "Seid Ihr sicher, dass Ihr einen Raben im Grabhügel gesehen habt?\n\nDas ist eine erschreckende Entwicklung. Wir können Clintar und den Traumwächtern nicht direkt helfen. Wenn wir jedoch herausfinden, was den Smaragdgrünen Traum bedroht, können wir es vielleicht aufhalten.\n\nWir haben erfahren, dass ein alter Arakkoakult im Schergrat wiederauflebt, der den Rabengott anbetet. Geht zum ewigen Hain und sucht nach Arthorn Windweise. Vielleicht besteht zwischen den Geschehnissen dort und dem Angriff auf den Smaragdgrünen Traum eine Verbindung.", sourceObjective = "Sprecht mit Arthorn Windweise im ewigen Hain im Schergrat.", completion = "<Arthorn hört aufmerksam zu. Ihr erklärt, dass Morthis Flügelraunen Euch geschickt hat, um zu untersuchen, ob zwischen dem Kult des Rabengottes und den merkwürdigen Geschehnissen auf der Mondlichtung ein Zusammenhang besteht. Die Nachricht erschüttert sie zwar, jedoch scheint es mehr an der Art und Weise der Botschaft selbst zu liegen.>\n\nOh mein...\n\nIch habe Timeon bei seinen Nachforschungen über den Rabenkult unterstützt. Ich hätte jedoch nie gedacht, dass der Rabe auch außerhalb des Schergrats Einfluss hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[10980] = { id = 10980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch des Raben", description = "Euren Erzählungen nach scheint Morthis mit seinen Verdächtigungen doch richtig gelegen zu haben. Wir brauchen jedoch Gewissheit.\n\nBei seinen Nachforschungen ist Timeon auf ein 'Buch des Raben' gestoßen, das angeblich ein altes Schriftstück des Kultes sein soll.\n\nDie Arakkoageister werden sich Euren Augen nicht zu erkennen geben. Begebt Euch mit diesem Stein zu den höchsten Gipfeln im westlichen Teil des Schergrats südlich des Rabenwaldes, beschafft Euch das Auge eines Ätherrochen und kombiniert beides, um Eure Sicht zu verstärken. Sucht nach dem Geist, den Timeon als Geist von Sai'kkal dem Ältesten identifiziert hat.", sourceObjective = "Benutzt das Auge eines Ätherrochen in Verbindung mit Eurem Stein des Sehers, um die Geister des Rabenkultes sehen zu können. Sucht beim Vortexgipfel nach dem Geist von Sai'kkal dem Ältesten und fragt ihn über das 'Buch des Raben' aus. Kehrt danach zu Arthorn Windweise zurück.", progress = "<Arthorn schaut Euch hoffnungsvoll an.>\n\nKonntet Ihr an Informationen über das Buch gelangen?", completion = "Ist es nicht erstaunlich, dass diese Kultisten sogar unter den Arakkoa als Ketzer galten? Dass der Hass der traditionellen Priester auf sie groß genug war um ihren heiligen Text zu zerstören ist unglaublich! Wir müssen an dieses Buch herankommen, {name}. Es ist der Schlüssel zum Geheimnis des Rabengottes. Damit werden wir verhindern können, dass er den Smaragdgrünen Traum an sich reißt.\n\nSollten wir Erfolg haben, wird Morthis mich vielleicht endlich als seinen Schüler akzeptieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10981] = { id = 10981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexusprinz Shaffars persönliche Kammer", progress = "Nur die standhaftesten und erfahrensten Abenteurer würden auf ein solches Angebot eingehen, {name}. Falls Ihr Euch den Schrecken der zweiten Stasiskammer der Managruft stellen wollt, kann ich einen Schlüssel dazu herstellen. Bringt mir ein Abzeichen des Nexuskönigs! Dann werde ich tun, worum Ihr bittet.", completion = "Und hier habt Ihr den versprochenen Schlüssel zu Shaffars persönlicher Stasiskammer." }
quests[10982] = { id = 10982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge des Haramad", sourceObjective = "Ihr habt viel für das Protektorat und das Konsortium getan, {name}. Daher ist es nur gerecht, dass einer unserer neuen Schlüssel an Euch geht. Mit diesem Schlüssel könnt Ihr Shaffars persönliche Stasiskammer jederzeit öffnen, ohne den Schlüssel dabei zu zerstören.\n\n\n\nEr ist von Dauer und wird auf ewig Euch gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[10983] = { id = 10983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mog'dorg der Weise", description = "Mog'dorg weise! Er schicken Grok in Stadt, Hilfe holen. Blutschlägerklan brauchen Hilfe.\n\nMog'dorg sagen, schicken mächtige Kleine zu ihm in Schergrat. Er stehen auf Turm bei Zirkel des Blutes. Mog'dorg weise!", sourceObjective = "Besucht Mog'dorg den Weisen auf einem der Türme außerhalb des Zirkels des Blutes im Schergrat.", completion = "Grok sagt, ich bin weise? Ich weiß ja nicht so recht.\n\nVielleicht liegt das daran, dass ich der Einzige meines Klans bin, der aufrichtig versucht uns vor der Vernichtung durch den Speerspießerklan zu retten. Und natürlich vor Gruul und seinen Söhnen, die sie unterstützen.\n\nIch hoffe, dass Ihr gekommen seid, um uns aus der unaufhaltsamen Verdammnis zu erretten, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10984] = { id = 10984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit dem Oger", description = "<V'erus Stimme erfüllt Euren Geist mit kristallener Melodie und Klarheit.>\n\nEs streunt ein Oger im unteren Viertel umher, der alle Passanten um Hilfe anfleht. Doch keiner will seiner Not Gehör schenken. Könntet Ihr ihm vielleicht helfen?\n\nSein Name ist Grok. Er sitzt in der Nähe der Händler im Südwesten.\n\nSeid bedankt, {name}.", sourceObjective = "Sprecht mit dem Oger Grok im unteren Viertel von Shattrath.", completion = "Ihr helfen Grok? Grok brauchen Hilfe! Blutschläger brauchen Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[10985] = { id = 10985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ablenkungsmanöver für Akama", description = "<Licht pulsiert um Xi'ri herum während die Streitkräfte der Aldor und der Seher seine Befehle ausführen. Xi'ris Armee ist bereit, Illidans Streitkräfte zurückzudrängen und Akama das nötige Ablenkungsmanöver zu verschaffen. Der Naaru wartet auf Eure Aufforderung den Angriff durchzuführen.>", sourceObjective = "Stellt sicher, dass Akama und Maiev den Schwarzen Tempel im Schattenmondtal betreten, nachdem Xi'ris Streitkräfte ihr Ablenkungsmanöver durchgeführt haben.", progress = "<Xi'ri registriert Eure Anwesenheit.>", completion = "<Xi'ri pulsiert vor Energie, Ihr fühlt, wie ein Gegenstand in Euren Händen Gestalt annimmt. Es ist das Medaillon, das Ihr A'dal im Namen von Akama gegeben habt. Seine Macht hat sich durch die Magie der Naaru noch verstärkt. Die Sha'tar haben Euch das Medaillon von Karabor anvertraut, und damit den Zugang zum Schwarzen Tempel.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10986] = { id = 10986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick zum Himmel", description = "Alle Teile des Buchs des Raben zu finden wird schwierig. Wenn sie es überhaupt überleben. Wir benötigen schärfere Augen als Eure dafür.\n\nUnten im westlichen Nagrand, am östlichen Rand der Zwielichthöhe, untersucht Behüterin Elaira die lokalen Vogelarten. Sucht sie auf und schaut, ob sie Eure Vogelperspektive etwas verbessern kann, damit Ihr die Teile des Buchs des Raben finden könnt.", sourceObjective = "Sprecht mit Behüterin Elaira bei der Zwielichthöhe in Nagrand.", completion = "<Elaira hört Euch aufmerksam zu, als Ihr ihr von Eurer Suche nach dem Buch des Raben und Arthorns Vorschlag berichtet, die verschollenen Teile des Buchs mit Hilfe von Vögeln zu finden.>\n\nDas ist eine ausgezeichnete Idee. Nagrand ist voll von geeigneten Kandidaten für diese Aufgabe, aber welchen sollen wir wählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10987] = { id = 10987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spatz in der Hand", description = "Die wilden Sperber Nagrands haben von allen Raubvögeln hier die schärfsten Augen. Wegen Ihrer Größe wurden sie von den größeren Windrocs aus den meisten Gegenden verdrängt.\n\nDie meisten Sperber nisten hier auf der Zwielichthöhe. Wenn Ihr einen davon fangt, kann ich ihn so trainieren, dass er die Teile Eurer vergrabenen Tafel entdecken kann.\n\nDas wird allerdings nicht so einfach. Die Sperber sind sehr scheu und werden fliehen, sobald sie Euch sehen. Ich schlage vor, dass Ihr einen davon in die Enge treibt oder Euch nahe genug anschleicht, damit Ihr ihn mit einem Netz fangen könnt.", sourceObjective = "Benutzt das Sperbernetz um einen wilden Sperber zu fangen und bringt ihn zu Behüterin Elaira auf der Zwielichthöhe.", progress = "Habt Ihr einen Sperber fangen können?", completion = "Gut gemacht! Ich versuche immer noch, das Vertrauen der Sperber zu gewinnen, aber meine Kenntnisse über sie reichen bereits aus, um diesen hier für Eure Zwecke auszubilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10988] = { id = 10988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rabensteine", description = "Ich habe Euren Sperber so dressiert, dass er auf einen bestimmten Pfeifton reagiert. Wenn er diesen Ton hört, wird der Vogel zu Euch fliegen und Euch zu dem nächsten Tafelfragment führen. Arthorn berichtete, dass die Tafelfragmente im Gebiet von Skettis in den südöstlichen Wäldern von Terokkar vergraben sind. Dort wird der Vogel auf Euch warten.\n\nBringt die Pfeife zurück zu Arthorn, wenn Ihr alle Steine zusammen habt. Sie wird sich darum kümmern, dass es dem Vogel gut geht und ihn in die Freiheit entlassen.\n\nRichtet Arthorn meine Grüße aus, wenn Ihr sie seht.", sourceObjective = "Sammelt 8 Rabensteine in Skettis und bringt sie zu Arthorn Windweise im ewigen Hain im Schergrat.", progress = "Habt Ihr genügend Fragmente gesammelt, damit ich das Buch des Raben rekonstruieren kann?", completion = "<Arthorn nimmt Euch die Fragmente des Buchs des Raben ab und setzt sie zusammen.>\n\nEin Teil der Schrift ist verwittert, aber ich sollte das meiste davon entziffern können...", sourceObjectiveStatus = "unverified-source-field" }
quests[10989] = { id = 10989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mog'dorg der Weise", description = "Mog'dorg der Weise wartet auf Euch auf Spitze des Turms. Er mir aufgetragen, nach fähigen Helden wie Euch Ausschau zu halten. Ihr ihn in einer sehr wichtigen Sache sprechen müsst.\n\nGeht jetzt, aber erzählt niemandem davon! Es ist ein Geheimnis!", sourceObjective = "Sprecht mit Mog'dorg dem Weisen auf der Spitze des Turms außerhalb des Zirkels des Blutes im Schergrat, bei dem Chort sich aufhält.", completion = "Endlich hat Chort mir jemanden geschickt, der in der Lage sein könnte, mir zu helfen. Ich bin bemüht, die Blutschläger vor der Auslöschung durch die Speerspießer zu bewahren. Und natürlich durch Gruul und seine Söhne, die sie unterstützen.\n\nIch vertraue fest darauf, dass Ihr unserer Geheimorganisation helfen und uns in die Freiheit führen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10990] = { id = 10990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Adlers", description = "Das Buch des Raben berichtet, dass die Anhänger des Raben die Geister seiner Rivalen eingefangen und in kleinen Schreinen aus Stein gebannt haben. Jedem Schrein wurde ein Wächter zugeteilt, um zu verhindern, dass die Feinde des Raben sie befreien.\n\nDer erste dieser Schreine ist der des Adlers und befindet sich in den Hügeln südlich des Jorunesees und westlich der Steinbrecherfeste in den Wäldern von Terokkar.\n\nDie Tafel besagt, dass der Adler tapfer gekämpft hat, jedoch von einem Schwarm von Feinden überwältigt wurde. Die Rüstung und Belastbarkeit Eurer Bärenform ist für einen solchen Kampf bestens geeignet.", sourceObjective = "Besiegt den Wächter des Adlers und erlangt die Essenz des Adlers. Benutzt Arthorns Sperberpfeife, um Arthorns Sperber zu rufen, damit dieser die Kunde von Eurem Erfolg übermittelt.\n\nWenn Ihr die Pfeife verloren habt und Ersatz benötigt, sucht Arthorn Windweise im ewigen Hain auf.", progress = "<Der Sperber scheint mit Arthorns Stimme zu sprechen.>\n\nKonntet Ihr die Essenz des Adlergeistes befreien?", completion = "<Arthorn scheint die Macht der Essenz über die Sinne des Sperbers wahrzunehmen.>\n\nAuch tausende von Jahren der Gefangenschaft konnten die Macht des Adlergeistes nicht schmälern. Wenn die anderen Essenzen genauso stark sind wie die des Adlers, hat der Rabengott allen Grund Euch zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10991] = { id = 10991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Falken", description = "<Der Vogel spricht mit Arthorns Stimme.>\n\nDer zweite Geist, der von den Anhängern des Raben gebannt wurde, war der Geist des Falken.\n\nEr wurde zum Gedenken an die Priester des Raben, als sie noch über Macht verfügten, in der Nähe von Skettis eingesperrt.\n\nAm Ufer des Sees von Ere'Noru, im Nordwesten von Skettis, werdet Ihr den Schrein des Falken finden.\n\nUm den Wächter des Falken zu bezwingen, müsst Ihr die Kräfte des Falken zu Eurem Vorteil nutzen. Setzt die Schnelle und Anmut Eurer Katzengestalt ein, um den Wächter zu besiegen, bevor dieser seine volle Macht erlangt!", sourceObjective = "Besiegt den Wächter des Falken und erlangt die Essenz des Falken. Benutzt Arthorns Sperberpfeife, um Arthorns Sperber zu rufen, damit dieser die Kunde von Eurem Erfolg übermittelt.\n\nWenn Ihr die Pfeife verloren habt und Ersatz benötigt, sucht Arthorn Windweise im ewigen Hain auf.", progress = "<Wieder einmal erklingt Arthorns Stimme aus dem Schnabel des Sperbers.>\n\nHabt Ihr die Essenz des Falken?", completion = "<Der Sperber übermittelt Arthorns Worte.>\n\nGut gemacht, {name}. Ich hatte schon Angst, dass das Gefängnis des Falken bei der Explosion von Auchindoun zerstört wurde. Wir sind schon fast auf die Begegnung mit Anzu vorbereitet, {name}. Ich würde gerne mit Euch gehen, um da zu sein, wenn dieser selbst ernannte 'Gott' zurück in seine Grube getrieben wird, aus der er gekrochen ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[10992] = { id = 10992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Habichts", description = "<Arthorns Stimme richtet sich an Euch.>\n\nDer letzte und mächtigste Geist, der im Buch des Raben erwähnt wird, ist der Geist des Habichts. Man sperrte ihn in einen Schrein, fern von Skettis, auf einer entlegenen Insel südöstlich von Auchindoun.\n\nIch vermute, dass mit der Beschreibung nur eine Insel gemeint sein kann, die Stätte der Gramschwingen.\n\nDie Tafel beschreibt, dass die Krallen des Vogel dem Wächter des Habichts kaum einen Kratzer zufügen können. Verzichtet daher in dieser Schlacht auf körperliche Angriffe und beschwört zum Bezwingen dieses Feindes den Zorn der Sterne. Wiederholt den Fehler des Habichts nicht!", sourceObjective = "Besiegt den Wächter des Habichts und bringt die Essenz des Habichts zu Arthorn Windweise im ewigen Hain.", progress = "Konntet Ihr den Wächter des Habichts besiegen und die Essenz besorgen?", completion = "Endlich haben wir alle Essenzen zusammen. Morthis Flügelraunen muss einen Weg finden, um sie in einem Amulett zu vereinen. Mit diesem Amulett könnt Ihr den Rabengott herausfordern, ihn aus dem Smaragdgrünen Traum locken und schließlich besiegen. Ich werde ihm meine Aufzeichnungen über die Geister zusenden, in der Hoffnung, dass er den Wert meiner Erkenntnisse zu schätzen weiß.\n\nEin jeder der Geister hat einen Glücksbringer gesegnet, den ich für Euch bereit hielt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10993] = { id = 10993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Zuflucht des Cenarius", description = "Bringt die Essenzen zu Morthis Flügelraunen und berichtet ihm von unseren Erkenntnissen über den Rabengott.\n\nMorthis weiß am besten, wie man die Essenzen und Informationen einsetzen kann, um Anzu hervorzulocken. Macht Euch schnell auf den Weg zu ihm. Keiner weiß, wie lange Clintar und die Traumwächter den Angriffen des Raben noch standhalten können!\n\n<Arthorn greift nach Eurem Arm als Ihr Euch zum Gehen abwendet.>\n\nBitte, {name}, erzählt Morthis wie sehr ich Euch geholfen habe. Ich fürchte, dass er mein Mitwirken nicht selbst erkennt!", sourceObjective = "Bringt Arthorns Päckchen zu Morthis Flügelraunen in der Zuflucht des Cenarius.", progress = "Ich habe auf Nachricht von Arthorn gewartet. Was habt Ihr herausgefunden?", completion = "<Morthis nimmt das Päckchen entgegen, entdeckt Arthorns Notizen und überfliegt sie, ohne etwas über den Absender verlauten zu lassen.>\n\nEinerseits ist es eine Erleichterung endlich zu wissen, wer unser Feind ist, doch dieser Anzu ist ein Wesen von nicht zu unterschätzender Macht. Es ist wichtig, das Wesen und den Namen seines Feindes zu kennen, aber wir sind noch nicht bereit, ihm entgegen zu treten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10994] = { id = 10994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Jagd nach dem Mondstein", description = "Wenn man die Essenzen mit einem seltenen Edelstein wie dem Mondstein des Südstroms verbindet, habt Ihr die Möglichkeit, sie im Kampf gegen Anzu freizulassen.\n\nDas einzige Problem dabei ist, dass die Mondsteine des Südstroms nur auf der Azsharaseite des Flusses auf den Klippen nahe der Flussquelle gefunden werden können.\n\nDen letzten Nachtelfenspähern, die nach den Steinen suchten, ist großes Unheil widerfahren. Ihr Boot liegt noch immer in der Nähe der Stelle, wo sie den Stein gesichtet haben, im Fluss. Haltet Eure Augen offen und nähert Euch der Fundstelle von Seiten Azsharas.", sourceObjective = "Bringt einen Mondstein des Südstroms zu Morthis Flügelraunen in der Zuflucht des Cenarius.", progress = "Ihr seht aus, als hättet Ihr einiges durchgemacht! War der Mondstein wirklich so schwer zu finden?", completion = "<Morthis scheint hin- und hergerissen. Einerseits möchte er über Eure Geschichte lachen, andererseits ist ihm bewusst, wie knapp Ihr mit dem Mondstein entkommen seid. Er begnügt sich damit, den leuchtenden Stein anzustarren.>\n\nIch werde mich daran machen, den Stein mit den Essenzen der Vögel zu erfüllen. Bald werdet Ihr bereit sein, den Rabengott herauszufordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10995] = { id = 10995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grulloc hat zwei Schädel", description = "Im Osten, am Rand von Drachenend, könnt Ihr das verfluchte Dunkel finden. An diesem Ort schmiedet Grulloc, Sohn des Gruul, seine dümmlichen Pläne.\n\nIch habe gehört, dass er trickreich um eines seiner Besitztümer gebracht wurde. Wart Ihr das etwa? Nur zu schade, dass er bei dieser Gelegenheit nicht gleich umgebracht wurde.\n\nWenn wir unsere Freiheit wiedererlangen wollen, müsst Ihr ihm seinen wertvollsten Besitz rauben: einen Drachenschädel, den er als Erinnerung an das Gemetzel seines Vaters am schwarzen Drachenschwarm bewahrt. Doch um an den Schädel heranzukommen, werdet Ihr ihn töten müssen.", sourceObjective = "Beschafft Euch Grullocs Drachenschädel.", progress = "Ist Grulloc schon Geschichte?", completion = "Das muss ein harter Kampf gewesen sein, {class}. Ich bin sehr erleichtert, dass er uns nun nicht mehr auf die Pelle rücken wird.\n\nIch werde diesen Schädel zu Chort schicken, damit er auf ihn aufpasst. Ich glaube, dass wir unser Ziel mit eurer Hilfe erreichen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[10996] = { id = 10996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maggocs Schatztruhe", description = "Im Messergrat über uns und im Südosten zieht Maggoc seine Kreise. Sein Vater hat ihn zum Wächter des östlichen Teils der Berge erkoren, und er benutzt sein Amt, um jegliches Wesen zu terrorisieren, das ihm in die Quere kommt.\n\nAls Sohn des Gruul muss auch er verschwinden, damit mein Klan überleben kann. Und da kommt Ihr ins Spiel.\n\nMaggoc trägt stets eine Schatztruhe bei sich. Beweist mir, dass Ihr ihn umgebracht habt, indem Ihr mir seine teure Truhe bringt. Was auch immer Ihr darin finden mögt, dürft Ihr gerne behalten.", sourceObjective = "Beschafft Euch Maggocs Schatztruhe.", progress = "Habt Ihr die Truhe?", completion = "Sie war leer? Was ein Pech! Aber nun habt Ihr eine Ahnung von der sinnlosen Gewalt, unter der wir leiden müssen.\n\nJetzt, da Maggoc tot ist, sind wir meinem Traum von einem Zuhause, in dem wir Oger unser Schicksal selbst schmieden können, einen entscheidenden Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10997] = { id = 10997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sogar ein Gronn hat Standards", description = "Kennt Ihr Euch in Shattrath aus, {class}? Über der Stadt im Nordwesten gibt es einen Ort, den man die Hügelwand nennt. Man kann nur mit einem fliegenden Reittier dorthin gelangen.\n\nEiner der Söhne Gruuls, Slaag, hat sich selbst ins Exil dorthin begeben und die Herrschaft über die Oger der Gordunni, die dort leben, an sich gerissen. Auch wenn er so weit entfernt lebt, können wir ihn nicht am Leben lassen. Er könnte zurückkommen, wenn er erfährt, dass seine Brüder tot sind!\n\n{name}, Ihr müsst dorthin reisen und seine Standarte als Beweis für seinen Tod mitbringen.", sourceObjective = "Beschafft Euch Slaags Standarte.", progress = "Haltet Ihr Slaags Standarte schon in Euren Händen?", completion = "Ich bin erleichtert, dass Slaag nicht mehr unter uns weilt. Nun müssen wir nicht länger in Angst vor seiner drohenden Rückkehr leben!\n\nWenn Ihr nichts dagegen habt, würde ich die Standarte gerne als Symbol der Hoffnung für alle Oger dieser Berge entgegennehmen.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10998] = { id = 10998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den übelsten Kreisen", description = "Es gibt einen weiteren Gronn, der getötet werden muss: Skulloc Seelenschänder. Er weiß sich zu verstecken, doch es gibt einen Weg, ihn hervorzulocken.\n\nEr wurde von einem Ogerhexenmeister namens Vim'gol der Üble ausgebildet, an dessen Zauberfolianten Ihr gelangen müsst!\n\nMan beschwört Vim'gol, indem man innerhalb eines Feuerkreises bei seinem Zirkel steht. Findet Vim'gols Kreis in den Bergen im Nordosten, nahe der zerschlagenen Wildnis.\n\nUnd {name}, solltet Ihr hören, dass Vim'gol davon spricht größer zu werden, dann sorgt dafür, dass Eure Gefährten wieder jeden der fünf Feuerkreise besetzen, um seinen Zauber zu unterbrechen!", sourceObjective = "Beschafft Euch Vim'gols üblen Zauberfolianten.", progress = "Habt Ihr Vim'gol den Üblen beschworen und seinen toten Klauen den Zauberfolianten entrissen?", completion = "Ich scheue mich davor, ein Ding von solcher Abscheulichkeit auch nur anzufassen. Und doch müssen wir den Folianten lesen, wenn wir sein Wissen erkunden und Skulloc aus seinem Versteck locken möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10999] = { id = 10999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schuss, ein Treffer", description = "Bringt mir 8 Troggsteinzähne." }
quests[11000] = { id = 11000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schänder der Seelen", description = "Der Zauberfoliant ist der Schlüssel zu Skullocs Untergang.\n\nUm das Ritual zu beginnen, müsst Ihr am Hügel des Seelenschänders laut aus dem Buch vorlesen. Daraufhin werden der Geist des Seelenschänders sowie die Geister seiner Opfer erscheinen. Sie werden versuchen, den Seelenschänder zu vernichten. Ihr müsst sie so lange daran hindern, bis Skulloc vollständig in diese Welt übergetreten ist.\n\nDurchquert den Dolchrachenklamm Richtung Norden. Ihr findet den Grabhügel auf der anderen Seite des Zirkels des Blutes auf der rechten Seite vor Gruuls Unterschlupf.\n\nBringt mir Skullocs Seele!", sourceObjective = "Beschafft Euch Skullocs Seele.", progress = "Habt Ihr Skullocs Seele schon geraubt?", completion = "Es ist also vorüber. Ihr habt uns von den Fesseln der Sklaverei durch die Söhne von Gruul befreit. Ihr habt den Klan der Blutschläger vor der sicheren Auslöschung bewahrt.\n\nEs gibt keine Worte um zu beschreiben, wie tief ALLE Oger des Schergrats, Blutschläger wie Speerspießer, in Eurer Schuld stehen, {name}.\n\nSchaut dort, wie all die Oger sich versammeln um Euch Tribut zu zollen! Sollen Gruul und seine Marionette, der alte König Maulgar, sich ruhig in ihrem Unterschlupf verkriechen. Geht zu den Ogern als ihr neuer König!", sourceObjectiveStatus = "unverified-source-field" }
